import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-b1-001","clusterId":"B","werkstueckRef":"B.1","stufe":1,"question":"Eine Kollegin ist überzeugt, ihr neuer Kollege sei unzuverlässig. Seit Wochen sammelt sie jede seiner Verspätungen und erzählt davon. Dass er gestern ein Projekt pünktlich und sauber abgeliefert hat, nennt sie „reinen Zufall“. Was ist an ihrem Vorgehen am ehesten fehlerhaft?","options":["Sie übernimmt das Urteil des Teams über den neuen Kollegen, statt die Verspätungen selbst zu prüfen, und folgt damit der Mehrheit statt eigenen Gründen.","Sie hält den Kollegen für unzuverlässig, weil ihre Vorgesetzte ihn so beurteilt, ohne zu prüfen, ob diese ihn überhaupt gut genug kennt.","Sie sucht, deutet und behält Informationen so, dass sie ihr bestehendes Urteil stützen, und wertet Gegenteiliges wie das pünktliche Projekt ab.","Sie sieht in seinen Verspätungen die Ursache für die Unruhe im Team, obwohl beides nur zeitlich zusammen auftritt und kein Zusammenhang belegt ist."],"correctIndex":2,"explanation":"Die Kollegin prüft ihr Urteil nicht, sie dekoriert es. Sie sammelt gezielt, was passt (einseitige Suche), und erklärt den Gegenbeleg zum „Zufall“ (einseitige Deutung). Auch die Erinnerung läuft bei diesem Muster typischerweise einseitig: Gründe für die eigene Seite werden eher gefunden und behalten. Das ist der Bestätigungsfehler: keine bloße Sturheit, sondern ein Verarbeitungsmuster auf diesen drei Ebenen. Es fehlt vor allem eines: der ernsthafte Versuch, das eigene Urteil zu widerlegen. Die Übernahme der Teammeinung klingt nach Mitläufertum, doch die Verspätungen hat sie selbst gesammelt. Die Berufung auf eine Vorgesetzte wäre ein Autoritätsfehler, doch es kommt keine Vorgesetzte vor. Verspätungen als Ursache von Unruhe im Team wären eine Verwechslung von Zeitlichem und Ursächlichem, doch von Unruhe im Team ist keine Rede.","coreRule":"⚡ Suche zuerst nach dem stärksten Beleg gegen deine Position, nicht nach dem nächsten dafür.","quote":"Er hat nicht ermittelt. Er hat nur seine anfängliche Vermutung dekoriert.","quoteLabel":"Merksatz:","beleg":"Werkstück B.1 (Der Detektiv und der Gärtner; Kernidee; Kontext & Tiefe, drei Ebenen)","status":"entwurf","scenario":"","kurz":"Sie sucht und deutet so, dass ihr Urteil bestehen bleibt: Verspätungen zählen, das pünktliche Projekt ist „Zufall“. Der naheliegende Fehler ist, das für Prüfen zu halten, obwohl nie versucht wird, das Urteil zu widerlegen.","prueffrage":"Was müsste der Kollege tun, damit sie ihr Urteil über ihn ändern würde?","rueckmeldung":[{"option":0,"text":"Mitläufertum liegt nahe, wenn jemand ein Urteil über Dritte fällt. Hier hat sie die Verspätungen aber selbst gesammelt, und von einem Urteil des Teams ist nirgends die Rede. Der Fehler liegt in ihrer eigenen Verarbeitung."},{"option":1,"text":"Wer sein Urteil auf eine Vorgesetzte stützt, macht tatsächlich oft einen Fehler. Im Szenario kommt aber keine Vorgesetzte vor: Das Urteil stammt aus dem, was sie selbst beobachtet und sammelt."},{"option":3,"text":"Aus gemeinsamem Auftreten eine Ursache zu machen, wäre ein typischer Fehler. Von Unruhe im Team steht in der Situation aber nichts. Es geht darum, wie sie ihr Urteil über den Kollegen stützt, nicht um eine Ursachenzuschreibung."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175, 178","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson (1998), Verlagsfassung APA","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"eb9d93993b21a466"}},{"id":"qx-b1-002","clusterId":"B","werkstueckRef":"B.1","stufe":2,"question":"Was ist an diesem Vorgehen das Hauptproblem?","scenario":"Du willst einen Staubsaugerroboter kaufen und hast dich schon in ein Modell verliebt. Abends gibst du in die Suchmaschine „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ ein.","options":["Du suchst mit „Vorteile“ und „begeisterte Erfahrungsberichte“ nur nach Zustimmung zu Modell X, sodass das Ergebnis schon vorgegeben ist, bevor du etwas liest.","Du vergleichst Modell X mit allzu vielen Staubsaugerrobotern, sodass das Überangebot die Entscheidung am Ende eher erschwert als erleichtert.","Du schließt vom hohen Preis von Modell X auf seine Qualität, sodass der Preis dein Urteil schon vorab bestimmt, bevor du Berichte liest.","Du lässt dich vom Testsiegel auf der Seite von Modell X überzeugen, ohne zu prüfen, wer es vergeben hat, sodass das Urteil auf bloßem Vertrauen beruht."],"correctIndex":0,"explanation":"Wer „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ eingibt, fragt nicht nach Belegen gegen das Modell, sondern nach Argumenten dafür. Das ist die tendenziöse Suche: Wir googeln nicht „Beweise gegen meine Position“, sondern „Argumente für meine Position“. Das Problem liegt hier auf der Ebene der Suche, noch bevor Deutung oder Erinnerung ins Spiel kommen. Eine Suche, die die Entscheidung wirklich prüft, würde gezielt auch nach „Kritik“, „Probleme mit“ oder „Gegenargumenten“ fragen.","coreRule":"⚡ Schon die Wahl der Suchbegriffe kann das Ergebnis vorwegnehmen: Wer nur nach Bestätigung fragt, findet nur Bestätigung.","beleg":"Werkstück B.1 (Kontext & Tiefe, Ebene „Suche“; Werkbank-Frage)","status":"entwurf","kurz":"Mit „Vorteile“ und „begeisterte Erfahrungsberichte“ fragst du nur nach Argumenten für dein Wunschmodell, nicht nach Belegen dagegen. Die Schieflage steckt schon in der Suche: Das Ergebnis ist vorgezeichnet, bevor du etwas liest.","prueffrage":"Welche Wörter stehen in den beiden Suchanfragen, und nach welchen Wörtern wird dort gar nicht gesucht?","rueckmeldung":[{"option":1,"text":"Viele Vergleichsmodelle würden zwar tatsächlich die Wahl erschweren können. Im Fall hast du aber nur Modell X nachgeschlagen, ein Überangebot kommt gar nicht vor."},{"option":2,"text":"Vom Preis auf die Qualität zu schließen ist ein echter Stolperstein. Von einem Preis ist hier aber nirgends die Rede; die Schieflage liegt in den Suchbegriffen, nicht in einem Preisurteil."},{"option":3,"text":"Blindes Vertrauen in ein Siegel ist riskant, ohne Frage. Hier taucht aber gar kein Siegel auf, die Schieflage steckt allein in den Suchbegriffen."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"bd968df758c45794"}},{"id":"qx-b1-003","clusterId":"B","werkstueckRef":"B.1","stufe":3,"question":"Ein Freund investiert seit Jahren in ein Finanzsystem, das hohe Renditen garantiert. Mehrere Bekannte haben ihr Geld verloren, eine Verbraucherzentrale warnt, und die Auszahlungen stocken. Er sagt trotzdem: „Das sind alles Neider, mein System funktioniert.“ Warum ist sein Festhalten hier ein ernstes Problem und nicht nur eine harmlose Eigenart?","options":["Weil ihm schlicht die Informationen über das System fehlen und wer zu wenig weiß, mit seinen Entscheidungen leicht Schaden anrichtet.","Weil er sich nur unter Gleichgesinnten bewegt, die ihn bestärken, und der Gruppendruck dieses Umfelds ihn vom Umdenken abhält.","Weil es hier um ein wichtiges Thema geht und er trotz deutlicher Gegenbeweise nicht umdenkt, weil ihm sein Weltbild wichtiger ist.","Weil er seine Überzeugung auf ein einzelnes Erlebnis stützt und aus diesem Einzelfall auf die Wirksamkeit des ganzen Systems schließt."],"correctIndex":2,"explanation":"Einseitige Informationsverarbeitung ist an sich oft harmlos: Wer glaubt, die eigene Fußballmannschaft sei die beste, richtet damit kaum Schaden an. Gefährlich wird es, wenn zwei Dinge zusammenkommen: Es geht um ein wichtiges Thema, und überwältigende Gegenbeweise ändern nichts mehr an der Meinung. Dann wird der Schutz des eigenen Weltbildes wichtiger als die Anerkennung der Realität, und Menschen bleiben in betrügerischen Finanzsystemen, folgen gefährlichen Kulten oder lehnen medizinisch notwendige Behandlungen ab. Entscheidend sind das wichtige Thema und die Unbeweglichkeit gegenüber überwältigenden Gegenbeweisen. Fehlende Information ist hier nicht das Problem, denn die Warnungen und die stockenden Auszahlungen kennt er und schlägt sie trotzdem in den Wind. Von einem bestärkenden Umfeld oder von Gruppendruck ist im Fall keine Rede. Von einem einzelnen Erlebnis als Grundlage ebenso wenig; gegen sein System sprechen vielmehr mehrere unabhängige Hinweise.","coreRule":"⚡ Kritisch wird es bei wichtigen Themen, wenn Gegenbeweise nichts mehr bewegen.","beleg":"Werkstück B.1 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Entscheidend ist nicht die einseitige Sicht an sich, sondern die Kombination: ein folgenreiches Thema und mehrere unabhängige Gegenhinweise, die ihn nicht bewegen. Dann schützt er sein Weltbild statt sein Geld.","prueffrage":"Welche Warnzeichen liegen ihm schon vor, und wie erklärt er sie sich?","rueckmeldung":[{"option":0,"text":"Fehlendes Wissen kann tatsächlich zu schlechten Entscheidungen führen. Hier kennt er aber die Verluste der Bekannten, die Warnung und die stockenden Auszahlungen und wertet sie ab. Es mangelt nicht an Information, sondern am Umgang mit ihr."},{"option":1,"text":"Ein bestärkendes Umfeld kann Festhalten verstärken. Davon steht im Fall aber nichts: Von Gleichgesinnten oder Gruppendruck ist keine Rede. Entscheidend ist, dass er sich trotz deutlicher Gegenbeweise bei einem wichtigen Thema nicht bewegt."},{"option":3,"text":"Aus einem Einzelfall auf das Ganze zu schließen, wäre ein eigener Denkfehler. Hier fehlt aber ein solches Einzelerlebnis: Gegen das System sprechen mehrere unabhängige Hinweise, die er alle beiseiteschiebt."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b37453d19d07877f"}},{"id":"qx-b1-004","clusterId":"B","werkstueckRef":"B.1","stufe":4,"question":"Welche Einschätzung dieser Reaktion trifft zu?","scenario":"Du erzählst einem Bekannten, dass eine Behörde seine Behauptung über eine geheime Absprache geprüft und widerlegt hat. Er antwortet: „Genau das würden sie ja sagen – das beweist es erst recht!“","options":["Er verzerrt die Aussage der Behörde zu einer leichter angreifbaren Behauptung und widerlegt nur diese, sodass die eigentliche Aussage unberührt bleibt.","Er deutet auch die Widerlegung durch die Behörde als weiteren Beleg um, sodass nichts mehr gegen seine Überzeugung von der Absprache sprechen kann.","Er beruft sich auf Fachleute, die seine Behauptung über die Absprache stützen, sodass das Ansehen Dritter seine Überzeugung tragen soll.","Er hält an seiner Überzeugung von der Absprache fest, weil viele in seinem Umfeld sie teilen, sodass die Zahl der Zustimmenden als Beleg zählt."],"correctIndex":1,"explanation":"Wenn auch die Widerlegung als Beweis gilt, wird der Glaube zur „sich selbst versiegelnden Schleife“: Jedes Ereignis, egal wie unzusammenhängend, wird als weiterer Beweis gedeutet. Das ist der Bestätigungsfehler, die Neigung, Informationen so zu deuten, dass sie die eigene Überzeugung stützen. Eine hilfreiche Gegenfrage lautet: Welches Ergebnis würde er überhaupt als Widerlegung gelten lassen? Ein Strohmann klingt naheliegend, doch er gibt die Aussage der Behörde nicht verzerrt wieder, er deutet sie um. Eine Berufung auf Fachleute wäre ein Autoritätsargument, doch er nennt keine, sondern lehnt gerade die Behörde ab. Der Mitläufereffekt setzt voraus, dass er die Meinung anderer übernimmt, doch von anderen ist im Gespräch keine Rede.","coreRule":"⚡ Wenn selbst die Widerlegung als Bestätigung zählt, kann nichts mehr gegen die Überzeugung sprechen.","beleg":"Werkstück B.1 (Anwendung & Relevanz: Bei Verschwörungsmythen)","status":"entwurf","kurz":"Wer auch die Widerlegung als Beweis wertet, kann durch nichts mehr widerlegt werden: Jedes Ereignis bestätigt dann die Überzeugung. Das ist der Bestätigungsfehler, und die Gegenfrage lautet, was er überhaupt als Widerlegung gelten ließe.","prueffrage":"Welche neue Information über die Absprache bringt der Bekannte vor, nachdem er von der Prüfung gehört hat?","rueckmeldung":[{"option":0,"text":"Ein Strohmann bräuchte eine verzerrte Wiedergabe der Behördenaussage. Die gibt er aber nicht verzerrt wieder, er deutet sie um und macht aus der Widerlegung einen Beleg für seine eigene Überzeugung."},{"option":2,"text":"Autoritätsargumente setzen voraus, dass sich jemand auf Fachleute beruft. Hier nennt er keine, sondern lehnt gerade die Behörde ab. Sein Fehler liegt darin, wie er mit Gegenbelegen umgeht, nicht in einer Berufung auf Dritte."},{"option":3,"text":"Ein Mitläufereffekt würde bedeuten, dass er die Meinung anderer übernimmt. Von anderen ist im Gespräch aber keine Rede; entscheidend ist allein, wie er die Widerlegung deutet."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"178","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"b7d77d8c347fed20"}},{"id":"qx-b1-005","clusterId":"B","werkstueckRef":"B.2","stufe":1,"question":"Eine Kollegin stellt nach drei Wochen Einarbeitung fest: „Ich habe die Fehler in meinem Bericht gar nicht bemerkt. Ich hielt ihn für einwandfrei, dabei war er voller Mängel.“ Welche Erklärung für diese Lage ist am sparsamsten?","options":["Sie hat schwach gearbeitet und besitzt zugleich noch nicht die Fähigkeiten, die nötig wären, um Mängel im eigenen Bericht zu bemerken.","Sie hat schwach gearbeitet und stand beim Gegenlesen unter hohem Zeitdruck, sodass sie Fehler übersah, die sie sonst bemerkt hätte.","Sie hat schwach gearbeitet und ahnt die Mängel im Bericht, redet sich die Qualität aber schön, um ihr Selbstbild zu schützen.","Sie hat schwach gearbeitet und beim Prüfen nur nach Hinweisen gesucht, die ihre gute Meinung stützen, sodass ein Bestätigungsfehler wirkte."],"correctIndex":0,"explanation":"Hier greifen zwei Probleme ineinander: Die Leistung ist schlecht, und zugleich fehlt der Maßstab, um das zu merken. Die Fähigkeiten, die man für einen guten Bericht braucht, sind dieselben, die man braucht, um die Qualität eines Berichts zu beurteilen. Wer sie noch nicht hat, kann seine Fehler also nicht erkennen, und die Selbstsicherheit bleibt hoch. So beschreiben es Dunning und Kruger; wie viel davon echte metakognitive Blindheit und wie viel ein statistischer Effekt ist, ist in der Fachliteratur umstritten. In der Studie von Kruger und Dunning (1999) lag das schwächste Viertel beim 12. Perzentil und hielt sich für das 68., während das beste Viertel beim 86. lag und sich für das 74. hielt; das Problem trifft also die Schwächsten am härtesten. Zeitdruck klingt naheliegend, wäre aber eine zusätzliche Annahme, die der Fall nicht hergibt, und bei Hast würde sie die Mängel eher ahnen. Schönreden zum Schutz des Selbstbilds setzt voraus, dass sie die Mängel ahnt, doch sie sagt, sie habe sie nicht bemerkt. Ein Bestätigungsfehler müsste erst vorausgesetzt werden, während die fehlende Beurteilungsfähigkeit allein schon alles erklärt.","coreRule":"⚡ Wem das Können fehlt, dem fehlt oft auch der Maßstab, um das zu bemerken.","beleg":"Werkstück B.2 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Schwache Leistung und fehlender Maßstab greifen ineinander: Wer die Fähigkeiten für einen guten Bericht noch nicht hat, kann auch dessen Mängel kaum erkennen. Zeitdruck, Schönreden oder Bestätigungsfehler wären zusätzliche Annahmen, die der Fall nicht hergibt.","prueffrage":"Welche Annahmen musst du über die Kollegin treffen, die der Fall selbst gar nicht erwähnt?","rueckmeldung":[{"option":1,"text":"Zeitdruck klingt plausibel, ist aber eine Zusatzannahme, die der Fall nicht nennt. Außerdem setzt er voraus, dass sie die Fehler sonst erkannt hätte, und gerade das ist hier fraglich. Bei Hast würde man Mängel eher ahnen."},{"option":2,"text":"Schönreden zum Schutz des Selbstbilds kommt im Alltag oft vor. Es setzt aber voraus, dass sie die Mängel ahnt. Sie sagt jedoch, sie habe sie nicht bemerkt und den Bericht für einwandfrei gehalten."},{"option":3,"text":"Beim Prüfen sucht man tatsächlich gern Bestätigung. Dieser Fehler müsste hier aber erst unterstellt werden, und auch er braucht einen Maßstab, um Mängel zu erkennen. Fehlt dieser Maßstab, ist die Erklärung bereits vollständig."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"},{"typ":"doi","kurz":"Magnus, J. R.; Peresetsky, A. A. (2022): A Statistical Explanation of the Dunning–Kruger Effect. Frontiers in Psychology 13","oeffentlich":true,"doi":"10.3389/fpsyg.2022.840180","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nuhfer, E. u. a. (2016): Random Number Simulations Reveal How Random Noise Affects the Measurements and Graphical Portrayals of Self-Assessed Competency. Numeracy 9(1), Art. 4","oeffentlich":true,"doi":"10.5038/1936-4660.9.1.4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"fe0134046d669c15"}},{"id":"qx-b1-007","clusterId":"B","werkstueckRef":"B.2","stufe":2,"question":"Was verrät diese Szene über die Verlässlichkeit der Einschätzung deines Nachbarn?","scenario":"Dein Nachbar hat sich zwei Wochen lang Videos zur Gebäudestatik angesehen. Beim Hausbau erklärt er dem Bauingenieur, dessen Berechnungen seien „unnötig kompliziert“, und Experten seien ohnehin „alle gekauft“. Auf die Nachfrage, wie die Lasten im Dachstuhl verteilt werden, weicht er aus und wiederholt nur, er sehe das „ganz klar“.","options":["Seine große Gewissheit nach zwei Wochen Videos und die Abwertung der Fachleute sprechen eher für Selbstüberschätzung, denn Anfängern bleiben Lücken im eigenen Wissen oft verborgen.","Dass sich Bauingenieure gelegentlich irren, macht seine Skepsis gegenüber den Berechnungen für den Dachstuhl berechtigt, denn auch ein Fachmann sollte nicht ungeprüft recht bekommen.","Dass ihm die Berechnungen des Ingenieurs unnötig kompliziert erscheinen, spricht dafür, dass sie überladen sind, denn gute technische Lösungen sind meist einfach.","Weil es um sein eigenes Haus geht, hat er ein starkes Eigeninteresse an einem guten Ergebnis, und das spricht dafür, dass er seine Aussagen sorgfältig geprüft hat."],"correctIndex":0,"explanation":"Wer nur kurz in ein komplexes Feld hineingeschaut hat, dem fehlen oft genau die Fähigkeiten, um die Lücken im eigenen Wissen zu erkennen; dann fühlt sich das wenige Gelernte wie ein vollständiges Bild an. Typische Anzeichen sind große Gewissheit nach kurzer Beschäftigung und das pauschale Abwerten von Fachleuten („alle gekauft“). Dazu passt, dass er der konkreten Sachfrage ausweicht: Echte Prüfung würde die Gegenargumente verstehen wollen, statt die Berechnungen als „unnötig kompliziert“ abzutun. Sicherheit allein sagt wenig darüber aus, ob jemand recht hat, und hier spricht die Konstellation eher für Selbstüberschätzung. Ob er im Einzelfall trotzdem etwas Richtiges sagt, bleibt offen und ließe sich nur an der Sache selbst prüfen.","coreRule":"⚡ Große Sicherheit nach kurzer Beschäftigung ist ein Warnzeichen, kein Qualitätsmerkmal.","beleg":"Werkstück B.2 (Red Flags; Anwendung & Relevanz: Das Betriebssystem der „Selber-Denker“)","status":"entwurf","kurz":"Große Gewissheit nach nur zwei Wochen Videos, pauschales Abwerten der Fachleute und Ausweichen vor der Sachfrage passen eher zu Selbstüberschätzung. Wer wenig weiß, sieht die eigenen Lücken oft nicht und hält das Gelernte für ein vollständiges Bild.","prueffrage":"Was antwortet dein Nachbar, wenn man ihn bittet, seine Einschätzung an einem konkreten Bauteil zu erklären?","rueckmeldung":[{"option":1,"text":"Dass sich auch Fachleute irren, stimmt, und blindes Vertrauen wäre falsch. Doch solche Skepsis ist erst berechtigt, wenn sich ein konkreter Fehler benennen lässt, und genau dem weicht der Nachbar aus."},{"option":2,"text":"Gute Lösungen sind oft tatsächlich einfach. Ob eine Berechnung unnötig kompliziert ist, kann aber nur beurteilen, wer sie versteht. Der Eindruck des Nachbarn zeigt eher eine Lücke im eigenen Verständnis als einen Mangel der Rechnung."},{"option":3,"text":"Beim eigenen Haus steht für ihn viel auf dem Spiel, das stimmt. Eigeninteresse sichert aber keine Sorgfalt: Wer auf die Sachfrage keine Antwort hat, hat vermutlich nicht geprüft, so groß der Wunsch nach einem guten Ergebnis auch ist."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Light, N. u. a. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"be22d8c8392d8510"}},{"id":"qx-b1-008","clusterId":"B","werkstueckRef":"B.2","stufe":4,"question":"Welche Rückmeldung an deine Kollegin trifft am genauesten, was die Daten tragen?","scenario":"Eine Pressemitteilung fasst eine Untersuchung aus den USA zusammen: In fünf Befragungen zu sieben Themen mit wissenschaftlichem Konsens, darunter Impfungen, Gentechnik, Evolution und Klimawandel, schätzten diejenigen, die dem Konsens am stärksten widersprachen, ihr eigenes Wissen am höchsten ein, schnitten in einem Wissenstest im Mittel aber am schlechtesten ab. Beim Klimawandel war dieser Zusammenhang schwächer. Die Teilnehmenden wurden nur befragt und getestet, niemand wurde einer Bedingung zugeteilt. Deine Kollegin will in einem Vortrag in Deutschland sagen: „Selbstüberschätzung macht Menschen zu Gegnern des Konsenses, und zwar bei jedem Wissenschaftsthema.“","options":["Der Satz ist belegt, weil fünf getrennte Befragungen dasselbe Muster zeigten; offen ist nur, ob er sich auf Deutschland übertragen lässt.","Der Satz geht zu weit: Weil der Zusammenhang beim Klimawandel schwächer war, haben Wissen und Haltung zum Konsens nichts miteinander zu tun.","Der Satz geht zu weit: Die Befragungen zeigen nur, dass beides zusammen auftritt, nicht was woraus folgt, und beim Klimawandel war es schwächer.","Der Satz ist belegt, weil die Konsensgegner im Wissenstest messbar schlechter abschnitten; ein objektives Testergebnis zeigt mehr als bloße Meinung."],"correctIndex":2,"explanation":"Deine Kollegin springt von einem Zusammenhang auf eine Ursache und dehnt ihn zugleich auf jedes Thema aus. Eine Befragung misst, welche Merkmale gemeinsam auftreten, nicht was woraus folgt: Denkbar ist, dass Selbstüberschätzung zur Ablehnung führt, dass die Ablehnung das Gefühl von Besserwissen verstärkt oder dass ein dritter Faktor beides erzeugt. Dazu kommt die Reichweite: Der beschriebene Befund stammt aus fünf Studien in den USA (Light u. a. 2022, Science Advances) zu sieben Themen mit wissenschaftlichem Konsens, und bei stark politisierten Themen, vor allem beim Klimawandel, war der Zusammenhang schwächer. Ein „verursacht“ und ein „bei jedem Thema“ gehen also weiter, als die Daten tragen; als Waffe gegen Andersdenkende taugt der Befund nicht. Fünf Befragungen wiederholen denselben Zusammenhang, machen ihn aber nicht zur Ursache, solange niemand einer Bedingung zugeteilt wurde. Auch ein objektiver Wissenstest misst nur eines der gemeinsam auftretenden Merkmale genauer und klärt die Richtung nicht. Und ein schwächerer Zusammenhang ist kein fehlender: Selbsteinschätzung, tatsächliches Wissen und Haltung zum Konsens hängen in den Daten durchaus zusammen.","coreRule":"⚡ Ein Zusammenhang aus Befragungen zeigt, was zusammen auftritt, nicht was woraus folgt.","beleg":"Werkstück B.2 (Anwendung & Relevanz); Fn. gl-b-light (Light u. a. 2022, Science Advances 8(29), eabo0038)","status":"entwurf","kurz":"Befragungen zeigen, dass Selbstüberschätzung und Ablehnung gemeinsam auftreten, nicht was woraus folgt; beim Klimawandel war der Zusammenhang zudem schwächer. Aus „tritt zusammen auf“ wird leicht „verursacht“ und „überall“.","prueffrage":"Wurde irgendjemand einer Bedingung zugeteilt, und welche Themen deckt die Untersuchung überhaupt ab?","rueckmeldung":[{"option":0,"text":"Fünf Befragungen mit ähnlichem Muster überzeugen, und die Übertragbarkeit auf Deutschland ist tatsächlich offen. Wiederholte Messung eines Zusammenhangs macht daraus aber keine Ursache, und beim Klimawandel war er schwächer, also nicht „bei jedem Thema“."},{"option":1,"text":"Dass der Satz zu weit geht, stimmt, und beim Klimawandel war der Zusammenhang schwächer. Schwächer heißt aber nicht fehlend: Selbsteinschätzung, Wissen und Haltung hängen in den Daten durchaus zusammen, nur ist die Ursache offen."},{"option":3,"text":"Ein Wissenstest misst genauer als eine Selbstauskunft, das ist richtig. Er macht aber nur eines der gemeinsam auftretenden Merkmale schärfer und sagt nichts über die Richtung; zudem war der Zusammenhang nicht bei jedem Thema gleich stark."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Light, N.; Fernbach, P. M.; Rabb, N.; Geana, M. V.; Sloman, S. A. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3a0f8aba750b7d44"}},{"id":"qx-b1-009","clusterId":"B","werkstueckRef":"B.3","stufe":1,"question":"Welche Einschätzung ist hier am ehesten ein Fehlschluss und warum?","options":["Sie schätzt das Hai-Risiko nach den lebhaften Nachrichtenbildern der letzten Woche ein, die ihr leicht einfallen, nicht nach der tatsächlichen Häufigkeit von Haiangriffen und Autounfällen.","Sie schätzt das Hai-Risiko nach der Opferzahl ein, die ihr in den Nachrichten der letzten Woche zuerst begegnet ist, und bleibt an dieser Zahl hängen, statt sie mit Autounfällen zu vergleichen.","Sie schätzt das Hai-Risiko nach der Haltung ihres Umfelds ein, das nach dem Angriff ebenfalls nicht mehr baden geht, und übernimmt sie ungeprüft, während Autofahren für alle selbstverständlich bleibt.","Sie schätzt das Hai-Risiko danach ein, wie vorhersehbar der Angriff am Küstenort im Rückblick wirkt, und hält das Baden deshalb für erkennbar gefährlich, die Autofahrt dagegen nicht."],"correctIndex":0,"explanation":"Mara beurteilt die Wahrscheinlichkeit danach, wie leicht ihr Beispiele einfallen. Ein dramatischer, frisch gesehener Fall mit starken Bildern ist mental sehr präsent, die Gefahr der Autofahrt dagegen nur eine blasse, abstrakte Statistik. Das Risiko, auf der Fahrt tödlich zu verunglücken, ist statistisch um ein Vielfaches höher als das, von einem Hai getötet zu werden. Leichtigkeit des Abrufs hängt von Emotionalität, Lebhaftigkeit, zeitlicher Nähe und medialer Wiederholung ab, nicht nur von der tatsächlichen Häufigkeit (Tversky und Kahneman, 1974). Hier liegt die Verfügbarkeitsheuristik vor. Die anderen Erklärungen nennen bekannte Verzerrungen, passen aber nicht: Ein Ankereffekt setzt eine genannte Zahl voraus, und im Szenario kommt keine vor. Dass ihr Umfeld ihre Haltung prägt, steht nirgends; sie begründet ihre Angst mit den Nachrichten der letzten Woche. Und der Rückschaufehler betrifft die Beurteilung von Vergangenem, sie beurteilt aber die Gegenwart.","coreRule":"⚡ Was mir leicht einfällt, erscheint mir wahrscheinlicher und wichtiger, auch wenn die Statistik etwas anderes sagt.","beleg":"Werkstück B.3 (Kernidee; Kontext & Tiefe); Fn. gl-b-verfuegbarkeit (Tversky/Kahneman 1974, Science 185(4157), S. 1127); Fn. gl-b-hai-auto (International Shark Attack File; NHTSA 2024, Overview of Motor Vehicle Traffic Crashes in 2022)","status":"entwurf","scenario":"Nach einer Woche voller Nachrichten über einen Hai-Angriff an einem Küstenort sagt Mara: „Ich gehe dort nicht mehr ins Wasser, das ist mir zu gefährlich.“ Am selben Tag fährt sie ohne zu zögern mit dem Auto zum Supermarkt. Ein Freund hält ihr vor, ihre Risikoeinschätzung sei verzerrt.","kurz":"Mara misst das Risiko daran, wie leicht ihr Beispiele einfallen: Der frische Hai-Fall ist bildhaft präsent, die Gefahr der Autofahrt eine blasse Statistik. Dabei ist das Unfallrisiko auf der Straße statistisch um ein Vielfaches höher.","prueffrage":"Was genau hat Mara in dieser Woche erfahren: eine Zahl, die Meinung von Bekannten oder Berichte über einen Fall?","rueckmeldung":[{"option":1,"text":"Ein Vergleich mit Autounfällen fehlt tatsächlich. Doch ein Ankereffekt setzt eine genannte Zahl voraus, an der die Einschätzung hängen bleibt, und im Szenario fällt keine Opferzahl. Maras Urteil stützt sich auf die Bilder der Woche."},{"option":2,"text":"Dass andere Menschen unsere Haltung prägen, kommt vor. Im Szenario steht aber nichts über ihr Umfeld, und Mara begründet ihre Angst selbst mit den Nachrichten der letzten Woche."},{"option":3,"text":"Der Rückschaufehler betrifft Vergangenes, das im Nachhinein vorhersehbar scheint. Mara beurteilt jedoch, wie gefährlich Baden und Autofahren jetzt sind, und von Vorhersehbarkeit ist im Szenario nirgends die Rede."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"391e26dc11734c23"}},{"id":"qx-b1-010","clusterId":"B","werkstueckRef":"B.3","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Kollegin fehlerhaft, und wie schätzt du dein Risiko stattdessen sinnvoll ein?","scenario":"Seit drei Tagen berichtet die Lokalpresse täglich über Wohnungseinbrüche in deiner Stadt, mit Fotos aufgebrochener Türen. Du merkst, dass du dich abends plötzlich unsicher fühlst. Eine Kollegin sagt: „Wenn ständig darüber berichtet wird, muss es ja wirklich häufiger geworden sein.“","options":["Sie schließt aus der Menge der Berichte auf die Häufigkeit der Fälle, obwohl Berichte nur zeigen, was die Redaktion aufgreift; du prüfst deshalb die langfristigen Zahlen für deinen Wohnort.","Sie überträgt die Einbrüche, über die die Lokalpresse berichtet, auf das ganze Land, obwohl sich Regionen stark unterscheiden; du prüfst deshalb die Zahlen anderer Städte und Bundesländer.","Sie achtet nur auf die Einbruchsberichte der letzten drei Tage, die ihre Sorge bestätigen, und überliest Beruhigendes; du liest deshalb gezielt auch Meldungen, die zur Gelassenheit beitragen.","Sie vertraut der einen Lokalzeitung mit ihren Fotos aufgebrochener Türen zu stark, obwohl auch Redaktionen irren; du vergleichst deshalb mit der Berichterstattung einer überregionalen Zeitung."],"correctIndex":0,"explanation":"Wie viel über ein Thema berichtet wird, sagt zunächst etwas über die Berichterstattung, nicht über die Häufigkeit des Ereignisses selbst. Wiederholung und eindrückliche Bilder machen Fälle im Kopf leicht abrufbar, und was uns leicht einfällt, halten wir gern für häufig oder wahrscheinlich: die Verfügbarkeitsheuristik. Diese Faustregel ist im Alltag oft brauchbar, führt bei statistischen Risiken aber leicht in die Irre; ständige Berichte über Kriminalität können das Gefühl einer gefährlichen Welt erzeugen, selbst wenn die Kriminalitätsstatistiken sinken. Die passende Gegenfrage lautet: Was sagen die langfristigen, nüchternen Zahlen zur tatsächlichen Häufigkeit? Das Unsicherheitsgefühl ist dabei real, ersetzt aber keine Messung.","coreRule":"⚡ Wenn die Nachrichten laut sind, frag die langweilige Statistik.","quote":"Was sagen die langfristigen, langweiligen Statistiken über die tatsächliche Häufigkeit dieses Ereignisses?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.3 (Kontext & Tiefe: Mediale Wiederholung; Das Adaptive Talent; Das Anti-Denkmuster)","status":"entwurf","kurz":"Die Menge der Berichte zeigt, worüber die Redaktion berichtet, nicht, wie oft eingebrochen wird. Was dank Wiederholung und Bildern leicht einfällt, halten wir für häufig; dagegen helfen die langfristigen Zahlen deines Wohnorts.","prueffrage":"Über wie viele Einbrüche wurde in den drei Tagen berichtet, und woran erkennst du, ob das mehr sind als sonst?","rueckmeldung":[{"option":1,"text":"Regionale Unterschiede sind real, doch hier wird nichts aufs ganze Land übertragen; es geht nur um deine Stadt. Zahlen anderer Orte sagen nicht, ob es bei euch häufiger wurde."},{"option":2,"text":"Gerade Sorge macht empfänglich für Bestätigendes, und gezielt Beruhigendes zu lesen kann sich gut anfühlen. Die Kollegin sucht aber nicht gezielt, sie deutet, was ihr täglich begegnet. Beruhigende Meldungen ersetzen zudem keine Messung der Häufigkeit."},{"option":3,"text":"Quellen zu vergleichen ist grundsätzlich klug, und auch Redaktionen irren. Eine überregionale Zeitung würde aber vermutlich dieselben Fälle zeigen und sagt so nichts über die tatsächliche Häufigkeit."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Pew Research Center (2016): Voters' perceptions of crime continue to conflict with reality","oeffentlich":true,"url":"https://www.pewresearch.org/short-reads/2016/11/16/voters-perceptions-of-crime-continue-to-conflict-with-reality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Availability Heuristic“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"20d9c6ba923067c5"}},{"id":"qx-b1-011","clusterId":"B","werkstueckRef":"B.3","stufe":3,"question":"Welche Schlussfolgerung zieht diese Auswertung am besten, ohne mehr in sie hineinzulesen, als sie hergibt?","options":["Das Risiko, im Meer zu ertrinken, und das Risiko im Straßenverkehr sind beide höher als das Risiko, von einem Hai getötet zu werden.","Das Risiko im Straßenverkehr ist höher als das Risiko, im Meer zu ertrinken, deshalb ist die Fahrt zum Strand gefährlicher als das Baden.","Das Hai-Risiko an bewachten Stränden ist gleich null, denn bei 264 Millionen Besuchen starb niemand; Warnungen sind dort überflüssig.","Ertrinken ist am Strand die häufigste Todesursache überhaupt, denn die Auswertung zeigt mehr Ertrunkene als Hai-Opfer."],"correctIndex":0,"explanation":"Bei rund 264 Millionen Strandbesuchen starb niemand durch einen Hai, ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern. Die Bezugsgrößen passen nicht genau zusammen: Die meisten Ertrunkenen starben außerhalb der bewachten Abschnitte, und die Verkehrszahl bezieht sich auf gefahrene Meilen statt auf Strandbesuche. Genau verrechnen lassen sich die Zahlen deshalb nicht; die Rangfolge trägt trotzdem, weil in den Daten kein einziger Hai-Todesfall vorkommt, während Ertrinken und Straßenverkehr messbar Todesopfer fordern. Das Risiko mit dem lebhaftesten Bild ist also nicht das größte. Eine Gefahr zu relativieren heißt aber nicht, sie zu leugnen. Verkehr und Ertrinken haben verschiedene Bezugsgrößen, sodass sich nicht sagen lässt, welches von beiden gefährlicher ist. Kein beobachteter Todesfall ist noch kein Risiko von null, und die Zahlen betreffen ohnehin nur bewachte Strände. Dass mehr Menschen ertrinken als von Haien getötet werden, sagt nichts über alle anderen Todesursachen am Strand.","coreRule":"⚡ Das Risiko mit dem dramatischsten Bild ist selten das mit den meisten Opfern.","beleg":"Werkstück B.3 (Die Angst vor dem Hai); Fn. gl-b-hai-auto (USLA-Daten, Stand Februar 2001; NHTSA 2024, S. 1)","status":"entwurf","scenario":"Nach einem Hai-Angriff in den Nachrichten meiden viele Urlauber das tiefe Wasser. Eine Auswertung von Strandbesuchen in den USA zeigt: Bei rund 264 Millionen Besuchen an bewachten Ozeanstränden starb kein einziger Mensch durch einen Hai. Ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern, die meisten außerhalb der bewachten Abschnitte. Im US-Straßenverkehr starben 2022 rund 1,33 Menschen je 100 Millionen gefahrene Meilen.","kurz":"Kein Hai-Todesfall bei 264 Millionen Besuchen, aber messbar Ertrunkene und Verkehrstote: Die Rangfolge trägt. Der naheliegende Fehler ist, das Risiko mit dem eindrucksvollsten Bild zu verwechseln, obwohl sich Verkehr und Ertrinken nicht genau verrechnen lassen.","prueffrage":"Wie viele Todesfälle durch Haie nennt die Auswertung, und welche anderen Todesursachen beziffert sie?","rueckmeldung":[{"option":1,"text":"Der Verkehr fordert tatsächlich Todesopfer, ebenso das Ertrinken. Eine Rangfolge der beiden ergibt sich aber nicht, denn die eine Zahl bezieht sich auf gefahrene Meilen, die andere auf Strandbesuche; dazu kommt die unbekannte Länge der Anfahrt."},{"option":2,"text":"Ein sehr kleines Risiko lässt sich so gut belegen. Kein beobachteter Todesfall ist aber kein Beweis für ein Risiko von null, und die Zahlen betreffen nur bewachte Strände. Eine Gefahr zu relativieren heißt nicht, sie zu streichen."},{"option":3,"text":"Dass mehr Menschen ertrinken als von Haien getötet werden, stimmt nach diesen Zahlen. Daraus folgt aber keine Rangfolge unter allen Todesursachen am Strand, denn andere Ursachen kommen in der Auswertung gar nicht vor."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4f8e1c91cef29d12"}},{"id":"qx-b1-012","clusterId":"B","werkstueckRef":"B.3","stufe":4,"question":"Warum ist dein Eindruck, dass das Ritual funktioniert, so überzeugend, und was folgt daraus für die Bewertung?","scenario":"Du hast einmal im Stillen „um einen Parkplatz gebeten“ und sofort einen gefunden. Seitdem bist du überzeugt, dass das Ritual funktioniert. Auf Nachfrage räumst du ein, dass es in den allermeisten anderen Fällen nicht geklappt hat, du dich daran aber kaum erinnerst.","options":["Der Treffer ist lebhaft und leicht abrufbar, die Fehlschläge nicht; das Gefühl der Wirksamkeit sagt nichts über die Trefferquote aus.","Du hältst nach vielen Fehlschlägen einen Treffer für überfällig (Spielerfehlschluss); darum wirkt der nächste Versuch aussichtsreicher, als er ist.","Du verlässt dich auf Erzählungen anderer über das Ritual; solche Berichte aus zweiter Hand solltest du nach ihrer Quelle bewerten.","Du erklärst Fehlschläge nachträglich mit Störungen weg, sodass das Ritual nicht widerlegbar ist; es müsste so formuliert werden, dass es scheitern kann."],"correctIndex":0,"explanation":"Ein einzelner Zufallstreffer ist emotional und bildhaft, er fällt dir leicht wieder ein. Die vielen Fehlschläge sind unauffällig und verblassen. Weil uns leicht Abrufbares wichtig und häufig erscheint, entsteht der Eindruck von Wirksamkeit, ohne dass sich an der tatsächlichen Trefferquote etwas ändert. Man erinnert sich lebhaft an den einen Treffer und vergisst die hundert Male, bei denen es nicht funktioniert hat. Beurteilen lässt sich das Ritual deshalb nur an allen Versuchen, nicht an dem Treffer, der dir am lebhaftesten einfällt. Ein Spielerfehlschluss würde voraussetzen, dass du nach den Misserfolgen einen Treffer erwartest, doch überzeugt dich gerade der eine Treffer. Von Erzählungen anderer ist im Fall keine Rede, es geht um deinen eigenen Versuch. Und du erklärst die Fehlschläge nicht weg, sondern räumst sie auf Nachfrage ein.","coreRule":"⚡ Bewerte ein Ritual nach allen Versuchen, nicht nach dem Treffer, der dir am lebhaftesten einfällt.","beleg":"Werkstück B.3 (Anwendung & Relevanz: Bei Esoterik & Aberglaube)","status":"entwurf","kurz":"Der eine Treffer ist lebhaft und leicht abrufbar, die vielen Fehlschläge verblassen. Dieser Eindruck wirkt überzeugend, sagt aber nichts über die Trefferquote. Bewerten lässt sich das Ritual nur an allen Versuchen, nicht an dem einen, der dir am lebhaftesten einfällt.","prueffrage":"Wie viele Versuche gab es insgesamt, und bei wie vielen davon klappte es?","rueckmeldung":[{"option":1,"text":"Dass nach vielen Misserfolgen ein Treffer „fällig“ sei, ist ein bekannter Irrtum. Hier passt er aber nicht, denn überzeugt hat dich gerade der eine Treffer, nicht eine Pechsträhne, auf die du eine Wende erwartest."},{"option":2,"text":"Berichte aus zweiter Hand sollte man tatsächlich nach ihrer Quelle bewerten. Im Szenario geht es aber um deinen eigenen Versuch, von Erzählungen anderer ist keine Rede."},{"option":3,"text":"Nachträgliches Wegerklären macht Behauptungen unwiderlegbar, und eine prüfbare Formulierung wäre sinnvoll. Du erklärst hier aber nichts weg, sondern räumst die Fehlschläge ein; sie bleiben nur blass in der Erinnerung."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Availability Heuristic“, „Misleading Vividness“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"d1f9100563144855"}},{"id":"qx-b1-013","clusterId":"B","werkstueckRef":"B.4","stufe":2,"question":"Was ist an deiner Argumentation fehlerhaft?","scenario":"Nach einem Derby sagst du: „Die Fans des anderen Vereins sind doch alle gleich – grölen, pöbeln, werfen mit Bechern.“ Auf den Einwand, dass auch in deiner eigenen Fankurve ein paar Leute Becher werfen, antwortest du: „Ja, aber unsere Leute sind ganz verschieden: Familien, Rentner, Studenten, Ultras. Da kann man nicht pauschal urteilen.“","options":["Du misst mit zweierlei Maß: Die gegnerischen Fans siehst du als gleichförmige Masse, deine eigene Kurve dagegen als Vielfalt einzelner Menschen.","Du greifst die Person an, die dich auf die Becher in deiner Kurve hinweist: Statt auf ihren Einwand einzugehen, stellst du ihre Glaubwürdigkeit infrage.","Du folgst der Mehrheit in deiner Fankurve: Das Urteil über die Becherwürfe der gegnerischen Fans übernimmst du von den anderen, ohne es selbst zu prüfen.","Du stützt dich auf eine Autorität: Dein Urteil über die gegnerischen Fans begründest du damit, dass Vereinsverantwortliche sie ebenso sehen und du ihnen vertraust."],"correctIndex":0,"explanation":"Dieses Muster heißt Outgroup-Homogenität: Wir sehen die Mitglieder einer fremden Gruppe als stereotype, homogene Masse („Die sind doch alle gleich“), die Mitglieder der eigenen Gruppe dagegen als vielfältige, einzigartige Individuen. Genau das passiert in deiner Argumentation: Die gegnerischen Fans fasst du zu einem einheitlichen Typus zusammen, bei deiner eigenen Kurve differenzierst du sofort. Ob dein Urteil trägt, prüfst du mit der Frage: Wie würde ich diese Aussage bewerten, wenn sie von einem Mitglied meiner eigenen Gruppe käme?","coreRule":"⚡ Frag dich bei jeder Gruppe: Würde ich sie auch als „alle gleich“ beschreiben, wenn es meine eigene wäre? Wenn nicht, sprichst du über ein Klischee, nicht über Menschen.","quote":"„Die sind doch alle gleich.“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.4 (Kontext & Tiefe: Outgroup-Homogenität)","status":"entwurf","kurz":"Die gegnerischen Fans fasst du zu einer einheitlichen Masse zusammen, deine eigene Kurve dagegen differenzierst du sofort. Dasselbe Muster, einmal pauschal, einmal individuell, verschiebt den Maßstab zu deinen Gunsten.","prueffrage":"Wer steht an einem Spieltag alles in der gegnerischen Kurve?","rueckmeldung":[{"option":1,"text":"Der Einwand bezieht sich auf deine Kurve, deshalb wirkt dein „Ja, aber…“ wie ein Ausweichen. Du gehst aber inhaltlich auf ihn ein und greifst die Person nicht an. Der Fehler liegt im ungleichen Maßstab, nicht im Angriff auf jemanden."},{"option":2,"text":"Das Urteil ist tatsächlich pauschal und ungeprüft. Dass du es von der Mehrheit deiner Kurve übernimmst, steht aber nirgends: Du sagst es als eigenen Eindruck. Entscheidend ist, dass du zwei Gruppen verschieden behandelst."},{"option":3,"text":"Ein Urteil, das sich auf andere beruft, würde hier verführen. Im Szenario stützt du dich aber auf deinen eigenen Eindruck, nicht auf Verantwortliche oder deren Ansicht. Auffällig ist stattdessen, wie unterschiedlich du die beiden Gruppen betrachtest."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Quattrone, G. A.; Jones, E. E. (1980): The perception of variability within in-groups and out-groups. JPSP 38(1)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0c41817d998902ab"}},{"id":"qx-b1-014","clusterId":"B","werkstueckRef":"B.4","stufe":1,"question":"Eine Schlagzeile erklärt das so: „Offenbar waren die Jungen schon vorher voller Vorurteile.“ Wie beurteilst du diese Erklärung im Licht des Ablaufs?","options":["Die Schlagzeile trifft zu: Dass sich beide Gruppen gleich eigene Namen und Flaggen gaben, verrät eine mitgebrachte Neigung zur Abgrenzung.","Die Schlagzeile greift zu kurz: Die Jungen waren vorher unauffällig und einander fremd; die Feindseligkeit kam erst mit dem Wettkampf der Leiter.","Die Schlagzeile trifft zu: Flaggen zu verbrennen und handgreiflich zu werden ist so heftig, dass es nur aus länger gewachsener Abneigung entsteht.","Die Schlagzeile greift zu kurz: Weil die Gruppen zuerst getrennt lebten, blieb die Feindseligkeit ein Spiel und wurde nie zu echter Abneigung."],"correctIndex":1,"explanation":"Die Erklärung „Vorurteile waren schon vorher da“ lässt sich an der zeitlichen Abfolge prüfen: Die Jungen waren vor dem Lager unauffällige Kinder und kannten einander nicht. Erst mit der Gruppenbildung und dem eigens inszenierten Wettkampf entstanden Abwertung, Flaggenverbrennung und Handgreiflichkeiten. Wenn sich ein Verhalten erst einstellt, nachdem die Umstände verändert wurden, liegt die Veränderung der Umstände als Ursache näher als eine verborgene Vorbelastung. Zugleich gilt: Der Wettstreit wurde von den Versuchsleitern gezielt konstruiert, und ein früherer Versuch (1953) scheiterte und wurde abgebrochen; nach Perrys Archivrecherche weigerten sich die Jungen dort, Feindseligkeit gegeneinander zu entwickeln. Das bekannte Lager war der dritte von drei Versuchen. Namen und Flaggen entstanden erst im Lager, als die Gruppen getrennt untergebracht waren; sie gehören zur Gruppenbildung und belegen nichts Mitgebrachtes. Länger gewachsene Abneigung setzt voraus, dass man sich kennt, doch die Gruppen waren einander nie begegnet. Und ein bloßes Spiel war es nicht, wenn Flaggen brennen und es zu Handgreiflichkeiten kommt.","coreRule":"⚡ Passt eine Erklärung nicht zum zeitlichen Ablauf, prüfe zuerst, was sich unmittelbar vor der Wirkung verändert hat – und ob die Situation inszeniert wurde.","beleg":"Werkstück B.4 (Das Ferienlager-Experiment); Fn. gl-b-sherif (Sherif u. a. 1961, S. 18 und 96; Perry 2018)","status":"entwurf","scenario":"Zwei Gruppen unauffälliger elfjähriger Jungen, die sich vorher nie begegnet waren, verbringen Zeit in einem Ferienlager. Zuerst leben sie getrennt voneinander und geben sich eigene Namen und Flaggen. Dann lassen die Versuchsleiter sie in einem eigens entworfenen Wettkampf gegeneinander antreten. Im Verlauf dieses Wettkampfs beleidigen sich die Gruppen, verbrennen gegenseitig ihre Flaggen und werden handgreiflich.","kurz":"Die Jungen waren vorher unauffällig und kannten einander nicht; Abwertung und Gewalt traten erst auf, nachdem die Leiter Gruppen und Wettkampf geschaffen hatten. Dann liegt die Veränderung der Umstände als Ursache näher als eine verborgene Vorbelastung.","prueffrage":"Was war mit den Jungen vor dem Lager, und was wurde im Lager erst von außen verändert?","rueckmeldung":[{"option":0,"text":"Eigene Namen und Flaggen wirken wie ein Zeichen innerer Abgrenzung. Sie entstanden aber erst im Lager, als die Gruppen getrennt untergebracht waren, und gehören zur Gruppenbildung. Mitgebrachte Vorurteile belegen sie nicht."},{"option":2,"text":"Verbrannte Flaggen und Handgreiflichkeiten sind tatsächlich heftig. Länger gewachsene Abneigung setzt aber voraus, dass man sich kennt, und die Gruppen waren einander nie begegnet. Auch heftige Gewalt kann binnen kurzer Zeit entstehen, wenn die Umstände sie begünstigen."},{"option":3,"text":"Dass die Schlagzeile zu kurz greift, stimmt. Ein bloßes Spiel war es aber nicht: Wenn Flaggen brennen und es zu Handgreiflichkeiten kommt, ist die Feindseligkeit real, auch wenn sie erst im Lager entstand."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): Intergroup Conflict and Cooperation: The Robbers Cave Experiment, Vorwort 1954 (Classics in the History of Psychology, York University)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/preface1954.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): The Robbers Cave Experiment, Kap. 3: Role of Staff, Subject Selection, Experimental Site (Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/chap3.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Perry, G. (2018): The Lost Boys: Inside Muzafer Sherif's Robbers Cave Experiment. Melbourne: Scribe","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e97c8d96211439f8"}},{"id":"qx-b1-015","clusterId":"B","werkstueckRef":"B.4","stufe":3,"question":"Wie beurteilst du die Lage und die Behauptung des Stadtrats am besten?","options":["Kein Grund zur Sorge: Die Fans zeigten bisher kaum Abneigung, also bleibt ihre Vorliebe harmlos, auch wenn Aufstiegskampf und Rundmails hinzukommen.","Der Stadtrat hat recht: Schon dass die Fans bevorzugt bei Sponsoren des eigenen Vereins kaufen, ist eine Abwertung des anderen, die auf Gelegenheit wartet.","Grund zur Sorge erst später: Feindschaft entsteht erst, wenn sich die Fans beider Vereine in Herkunft oder Aussehen deutlich voneinander unterscheiden.","Grund zur Sorge jetzt: Die Vorliebe bestand bisher ohne Abneigung; kippen kann sie durch den Kampf um denselben Platz und die Rundmails des Vorsitzenden."],"correctIndex":3,"explanation":"Der Stadtrat setzt zwei Dinge gleich, die sich trennen lassen: Bevorzugung der eigenen Gruppe und Abwertung der fremden. Die Forschung (Brewer 1999) zeigt, dass Benachteiligung anderer allein aus der Vorliebe für die eigene Gruppe entstehen kann, ohne negative Gefühle oder feindselige Absicht gegenüber den anderen. Genau das zeigt die Umfrage: Die Fans bevorzugen ihren Verein, ohne den anderen abzulehnen. Wer „automatisch“ sagt, behauptet eine Notwendigkeit, wo es nur eine Möglichkeit gibt, und dagegen genügt ein einziges Gegenbeispiel. In Feindschaft kippt die Bindung erst unter zusätzlichen Bedingungen: wahrgenommene Bedrohung, Konkurrenz oder gezielte Aufhetzung durch Anführer. Mit dem Kampf um denselben Aufstiegsplatz und den Rundmails, die eine Bedrohung behaupten, kommen solche Bedingungen jetzt hinzu. Entwarnung übersieht deshalb, dass sich die Umstände gerade ändern. Der Einkauf bei den eigenen Sponsoren ist Bevorzugung, keine Abwertung. Und auffällige Unterschiede in Herkunft oder Aussehen sind in der Forschung nicht als nötig für Feindschaft belegt; belegt sind Bedrohung, Konkurrenz und Aufhetzung.","coreRule":"⚡ Gruppenliebe ist nicht dasselbe wie Fremdenhass; sie kippt unter Bedrohung, Konkurrenz und Aufhetzung. Wer „zwangsläufig“ behauptet, muss zeigen, dass es keine Ausnahme gibt.","beleg":"Werkstück B.4 (Das Adaptive Talent); Fn. gl-b-brewer-kipp (Brewer 1999, Journal of Social Issues 55(3), S. 431, 434–438)","status":"entwurf","scenario":"In einer Kleinstadt gibt es zwei Fußballvereine. Eine Umfrage unter den Fans des einen zeigt: Sie halten ihren Verein für den besseren und kaufen bevorzugt bei seinen Sponsoren, Abneigung gegen den anderen Verein oder dessen Fans äußert aber kaum jemand. In der neuen Saison kämpfen beide Vereine erstmals um denselben Aufstiegsplatz, und der Vorsitzende des Fanclubs schreibt in Rundmails, die anderen wollten „uns alles wegnehmen“. Ein Stadtrat meint: „Wer seinen Verein liebt, hasst die anderen automatisch; Liebe zur eigenen Gruppe und Hass auf die fremde sind dasselbe.“","kurz":"Die Fans bevorzugen ihren Verein, ohne den anderen abzulehnen; beides lässt sich also trennen, und „automatisch“ stimmt nicht. Kippen kann die Bindung aber unter Konkurrenz und gezielter Aufhetzung, und die kommen jetzt hinzu.","prueffrage":"Was äußern die befragten Fans tatsächlich über den anderen Verein, und was hat sich seitdem in der Lage verändert?","rueckmeldung":[{"option":0,"text":"Dass bisher kaum Abneigung zu hören ist, stimmt und ist ein gutes Zeichen. Es gilt aber für die damalige Lage: Mit dem Kampf um denselben Platz und den Rundmails kommen Bedingungen hinzu, unter denen die Vorliebe kippen kann."},{"option":1,"text":"Dass die Fans den eigenen Verein bevorzugen, trifft zu. Wer bei dessen Sponsoren kauft, wertet damit aber noch niemanden ab; genau diese Gleichsetzung steckt im Satz des Stadtrats, und die Umfrage zeigt, dass beides getrennt vorkommt."},{"option":2,"text":"Gruppenunterschiede wirken einleuchtend als Auslöser, nötig sind sie für Feindschaft aber nicht: Belegt sind Bedrohung, Konkurrenz und Aufhetzung. Die sind hier schon im Spiel, also gibt es keinen Grund, mit der Sorge zu warten."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431, 434–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3), Verlagsfassung","oeffentlich":false,"doi":"10.1111/0022-4537.00126"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2e9aa261c1403718"}},{"id":"qx-b1-016","clusterId":"B","werkstueckRef":"B.4","stufe":4,"question":"Welche Prüffrage setzt am Kern dieses Musters an?","scenario":"Ein Skandal in der Partei, die du wählst, ist für dich eine „Kampagne der Gegner“. Derselbe Skandal bei der anderen Partei ist für dich ein Beweis ihrer moralischen Verkommenheit.","options":["Welche der beiden Parteien hat in den vergangenen Jahren mehr solcher Skandale gehabt, und wie schwer wogen sie jeweils?","Wie verlässlich sind die Medien, die über beide Skandale berichten, und welche der beiden Parteien behandeln sie schonender?","Gibt es für den Vorwurf im jeweiligen Skandal belastbare Belege, und lässt er sich unabhängig von beiden Parteien überprüfen?","Würde ich denselben Vorgang genauso bewerten, wenn die Rollen vertauscht wären und er bei der anderen Partei geschehen wäre?"],"correctIndex":3,"explanation":"Das Muster ist ein doppelter Maßstab: Derselbe Vorgang gilt als „Kampagne“, wenn er die eigene Seite trifft, und als Beweis für „moralische Verkommenheit“, wenn er die andere trifft. Dahinter steckt die Gruppenzugehörigkeits-Verzerrung: Statt zu fragen, ob etwas wahr ist, fragt man, ob es der eigenen Seite nützt. Am Kern setzt an, wer seinen Maßstab auf die Probe stellt, indem er sich vorstellt, derselbe Vorgang geschehe bei der anderen Partei, und prüft, ob das Urteil gleich bliebe. Fällt es anders aus, liegt die Asymmetrie in der Bewertung und nicht im Vorgang. Die anderen Fragen sind für sich sinnvoll, passen aber nicht zu diesem Muster: Ein Vergleich der Skandalbilanz klärt Fakten, ändert aber nichts daran, dass derselbe Vorgang je nach Lager unterschiedlich gewogen wird. Auch die Medienlage zu prüfen betrifft die Berichterstattung und nicht das eigene Urteil. Und selbst wenn ein Vorwurf belegt ist, bleibt offen, warum er bei der eigenen Partei als Kampagne und bei der anderen als Beweis gilt.","coreRule":"⚡ Vertausche die Rollen: Gilt mein Maßstab auch, wenn es um meine eigene Seite geht?","quote":"Ist das gut für uns oder für die?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.4 (Anwendung & Relevanz: Bei politischer Polarisierung; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Hier wird mit zweierlei Maß gemessen: Derselbe Vorgang gilt als Kampagne oder als Beweis, je nachdem, wen er trifft. Das zeigt sich, wenn man die Rollen vertauscht und prüft, ob das Urteil gleich bliebe. Fällt es anders aus, liegt die Schieflage im Urteil.","prueffrage":"Worin unterscheiden sich die beiden Skandale in der Sache, abgesehen davon, welche Partei betroffen ist?","rueckmeldung":[{"option":0,"text":"Ein Vergleich der Skandale klärt Fakten und ist für sich sinnvoll. Er erklärt aber nicht, warum derselbe Vorgang je nach Lager einmal als Kampagne und einmal als Beweis gilt. Die Schieflage im Urteil bleibt bestehen."},{"option":1,"text":"Die Verlässlichkeit der Medien zu prüfen ist grundsätzlich klug. Sie betrifft aber die Berichterstattung und nicht dein eigenes Urteil. Das Muster entsteht auch bei sauberer Berichterstattung, wenn der Maßstab je nach Lager wechselt."},{"option":2,"text":"Belege und unabhängige Überprüfbarkeit sind wichtig, damit prüfst du aber den Vorwurf. Selbst bei einem klar belegten Vorwurf bliebe offen, warum er bei der eigenen Partei als Kampagne und bei der anderen als Beweis gilt."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"defc9471b9f06fc4"}},{"id":"qx-b1-017","clusterId":"B","werkstueckRef":"B.5","stufe":1,"question":"Eine Wirtschaftsjournalistin sagt: „Dass die Firma so erfolgreich wurde, ist doch klar: Der Gründer war ein Visionär, jede seiner Entscheidungen führte zwangsläufig zum Erfolg. Man sieht es an seiner Biografie.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Die im Rückblick stimmige Erzählung vom Garagengründer wird mit einer Erklärung verwechselt, die den Erfolg schon vorher verlässlich vorhergesagt hätte.","Die Journalistin schließt vom Erfolg dieses einen College-Abbrechers auf eine Regel für alle Gründer, obwohl ein Einzelfall keine Verallgemeinerung trägt.","Die Journalistin stellt nur zwei Möglichkeiten zur Wahl, den Visionär oder den gescheiterten Garagengründer, und blendet alle Abstufungen dazwischen aus.","Die Journalistin beruft sich auf das Ansehen der Zeitschrift, die das Porträt druckte, statt dessen Behauptungen zu prüfen, sodass ein Autoritätsargument den Schluss trägt."],"correctIndex":0,"explanation":"Im Rückblick lassen sich unzusammenhängende Ereignisse leicht zu einer stimmigen Ursache-Wirkungs-Geschichte verbinden, die zwingend wirkt, weil man das Ergebnis schon kennt. Vorher hätte sie aber niemand verlässlich erzählen können: Zufall, Glück, Timing und Konkurrenten mit ähnlichen Ideen, die nur Pech hatten, fehlen in der glatten Erzählung. Eine gute Erklärung im Nachhinein ist deshalb noch keine gute Vorhersage. Der Test: Welche unzusammenhängenden Fakten bleiben übrig, wenn du die erzählerischen Verbindungslinien weglässt? Die anderen Gedanken benennen echte Denkfehler, passen aber nicht auf diesen Fall: Die Journalistin spricht nur über diese eine Firma und stellt keine Regel für alle Gründer auf. Sie bietet auch kein Entweder-oder an, denn von einem gescheiterten Gründer ist nirgends die Rede. Und sie beruft sich auf die Biografie und nicht auf das Ansehen der Zeitschrift.","coreRule":"⚡ Eine glatte Geschichte im Rückblick ist noch keine Vorhersage.","beleg":"Werkstück B.5 (Kernidee; Kontext & Tiefe; Die Legende des Star-CEOs; Anti-Denkmuster)","status":"entwurf","scenario":"Ein Zeitschriftenporträt über den Gründer eines Tech-Konzerns erzählt eine runde Geschichte: der rebellische College-Abbrecher, die Garage, der Kampf gegen die trägen Riesen. Jede Entscheidung erscheint im Rückblick wie ein kluger, folgerichtiger Schritt zum Gipfel.","kurz":"Im Rückblick verbindet sich alles zu einer stimmigen Geschichte, weil man das Ergebnis schon kennt. Der Fehler: Eine gute Erklärung im Nachhinein ist keine Vorhersage. Zufall, Glück und Pech der Konkurrenten fehlen in der glatten Erzählung.","prueffrage":"Welche Entscheidungen des Gründers hätten genauso gut schiefgehen können?","rueckmeldung":[{"option":1,"text":"Von einem Einzelfall auf alle Gründer zu schließen, wäre tatsächlich ein Fehler. Die Journalistin spricht aber nur über diese eine Firma und stellt keine Regel für alle Gründer auf, hier liegt der Fehler also woanders."},{"option":2,"text":"Ein falsches Entweder-oder wäre ein echter Denkfehler. Im Zitat tritt aber nirgends ein gescheiterter Gründer als Alternative auf: Die Journalistin bietet gar keine Auswahl an, sie erklärt den Erfolg einfach für zwangsläufig."},{"option":3,"text":"Ein Argument allein aufs Ansehen einer Quelle zu stützen, trägt nicht. Die Journalistin beruft sich aber auf die Biografie des Gründers und nicht auf das Renommee der Zeitschrift, die das Porträt druckte."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Roese, N. J.; Vohs, K. D. (2012): Hindsight Bias. Perspectives on Psychological Science 7(5)","oeffentlich":false,"doi":"10.1177/1745691612454303"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"29fcf44c64b4dbe2"}},{"id":"qx-b1-018","clusterId":"B","werkstueckRef":"B.5","stufe":2,"question":"Welche Prüfung hilft am besten, um zu klären, ob die Reportage mehr ist als eine gute Geschichte?","scenario":"Du liest eine Reportage über den Aufstieg einer Firma: klar, spannend, jede Wendung begründet. Du willst prüfen, ob die Erzählung die Fakten trägt oder nur gut klingt.","options":["Die Verbindungen zwischen den Wendungen gedanklich löschen und fragen, welche Einzelfakten bleiben und welche Rolle Zufall und Glück spielten.","Die Interessen der Autorin klären, etwa ob die Firma die Reportage bezahlt hat, und die geschilderten Wendungen danach entsprechend vorsichtig bewerten.","Die Wendungen nacheinander auf innere Widersprüche durchsehen und fragen, ob eine behauptete Ursache an anderer Stelle der Reportage widerlegt wird.","Die Wendungen einer Person ohne Branchenwissen erklären und fragen, ob sie jede Ursache für den Aufstieg nachvollziehen und begründen kann."],"correctIndex":0,"explanation":"Eine kohärente Erzählung entsteht oft erst im Rückblick: Das Gehirn verbindet Einzelereignisse zu einer Ursache-Wirkungs-Kette und blendet Zufall, Glück und gescheiterte Konkurrenz aus. Wer die Verbindungslinien gedanklich entfernt, sieht, welche belegbaren Fakten übrig bleiben und wo die Geschichte nur Lücken füllt. Die anderen Prüfungen klingen vernünftig, treffen aber nicht den Punkt: Die Interessen der Autorin zu klären ist sinnvoll, sagt aber nichts darüber, ob die Ursachenkette trägt. Dass die Reportage keine Widersprüche enthält, gehört zu einer gut gebauten Geschichte und belegt nicht, dass sie wahr ist. Und dass auch Leser ohne Branchenwissen jede Ursache nachvollziehen können, spricht für gutes Erzählen und nicht für Wahrheit: Eine Geschichte kann klar sein und trotzdem Zufall und Glück ausblenden.","coreRule":"⚡ Streich die Verbindungslinien und sieh nach, welche Fakten übrig bleiben.","beleg":"Werkstück B.5 (Das Anti-Denkmuster; Werkbank-Frage)","status":"entwurf","kurz":"Gerade die glatte Verknüpfung der Wendungen entsteht oft erst im Rückblick und blendet Zufall und Glück aus. Wer die Verbindungen gedanklich streicht, sieht, welche belegbaren Fakten übrig bleiben und wo die Geschichte nur Lücken füllt.","prueffrage":"Woher stammen die einzelnen Angaben der Reportage, und wo ließen sie sich unabhängig von ihr nachprüfen?","rueckmeldung":[{"option":1,"text":"Zu wissen, wer hinter einem Text steht, ist sinnvoll. Es sagt aber nichts darüber, ob die Ursachenkette trägt: Auch eine bezahlte Reportage kann stimmen, eine unabhängige kann trotzdem nur gut klingen."},{"option":2,"text":"Eine Geschichte ohne innere Widersprüche wirkt solide. Widerspruchsfreiheit gehört aber zu einer gut gebauten Erzählung und belegt nicht, dass sie wahr ist; Zufall und Glück bleiben auch dann unsichtbar."},{"option":3,"text":"Wenn Laien jede Ursache nachvollziehen können, ist die Reportage gut erzählt. Das sagt aber nichts über die Fakten: Eine klare Geschichte kann Zufall und Glück trotzdem ausblenden."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"936eace452d13680"}},{"id":"qx-b1-019","clusterId":"B","werkstueckRef":"B.5","stufe":4,"question":"Nach einem Börsencrash behauptet ein Bekannter: „Das war von langer Hand geplant. Eine kleine Gruppe von Großinvestoren hat gezielt auf den Absturz gewettet und alle anderen ins Verderben geschickt.“ Er hat viele Details parat, die zusammen eine stimmige Geschichte ergeben. Was ist an seiner Argumentation das Kernproblem?","options":["Sie macht aus Zufall, Fehlern und vielen Einzelentscheidungen eine runde Geschichte mit Bösewicht und Plan; dass sie stimmig klingt, beweist nicht ihre Wahrheit.","Sie beruft sich darauf, dass viele Menschen den Crash für abgekartet halten, obwohl die Verbreitung einer Behauptung nichts über ihre Wahrheit sagt (Mehrheitsargument).","Sie schließt vom Verhalten der wettenden Großinvestoren auf alle Anlegerinnen und Anleger, obwohl ein Einzelfall nichts über die Gesamtheit sagt (Verallgemeinerung).","Sie hält eine halb geplante, halb zufällige Entwicklung des Crashs für wahr, nur weil sie zwischen „alles Plan“ und „alles Zufall“ liegt (Kompromissfehlschluss)."],"correctIndex":0,"explanation":"Große, chaotische Ereignisse wie Wirtschaftskrisen, Pandemien oder Kriege entstehen meist aus einer Mischung von Inkompetenz, Zufall und systemischen Kräften. Die Behauptung macht daraus eine runde Geschichte mit einem allmächtigen Bösewicht, einem geheimen Plan und einem klaren Gut-Böse-Schema. Solche Geschichten sind psychologisch befriedigender als die komplizierte Realität, und genau deshalb wirken sie überzeugend. Dass die Erzählung stimmig klingt, sagt aber nichts darüber, ob sie wahr ist: Der Erzählfehler macht die Qualität der Geschichte zum Maßstab ihrer Glaubwürdigkeit statt die Qualität der Fakten. Prüfen lässt sich die Behauptung nur anhand der harten Einzelfakten, die übrig bleiben, wenn man die Verbindungslinien der Erzählung wegdenkt. Die anderen Fehlschlüsse gibt es, sie liegen hier aber nicht vor: Der Bekannte beruft sich nicht darauf, dass viele Menschen es glauben, sondern auf Details. Er spricht von einer kleinen Gruppe und verallgemeinert nicht auf alle Anleger. Und zwei Standpunkte, zwischen denen er einen Mittelweg wählt, gibt es in seiner Argumentation nicht.","coreRule":"⚡ Je runder die Geschichte, desto genauer solltest du nach Zufall und banaler Erklärung fragen.","beleg":"Werkstück B.5 (Anwendung & Relevanz: Bei Verschwörungsmythen; Anti-Denkmuster: Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Aus Zufall, Fehlern und vielen Einzelentscheidungen wird eine runde Geschichte mit Plan und Bösewicht. Wer die Stimmigkeit der Erzählung für ihre Wahrheit hält, misst die Qualität der Geschichte statt die der Fakten.","prueffrage":"Welche der vielen Details lassen sich einzeln belegen, wenn du die Verbindungen dazwischen weglässt?","rueckmeldung":[{"option":1,"text":"Mehrheitsargumente sind tatsächlich unzuverlässig. Der Bekannte stützt sich aber gar nicht darauf, dass viele es glauben, sondern auf viele Details, die zusammenpassen. Sein Problem liegt in der Geschichte selbst, nicht in der Zahl ihrer Anhänger."},{"option":2,"text":"Von Einzelfällen auf alle zu schließen ist ein verbreiteter Fehler. Der Bekannte spricht jedoch ausdrücklich von einer kleinen Gruppe und folgert nichts über alle Anleger. Die anderen Anleger tauchen nur als Opfer auf, nicht als Beleg."},{"option":3,"text":"Beim Kompromissfehlschluss wird zwischen zwei Standpunkten die Mitte gewählt. Der Bekannte vertritt aber nur eine Position, nämlich „alles war Plan“, und sucht keinen Mittelweg. Seine Schwäche liegt darin, dass die Stimmigkeit der Geschichte als Beweis herhalten muss."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5724570/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"d5b4d0de40efdd34"}},{"id":"qx-b1-020","clusterId":"B","werkstueckRef":"B.6","stufe":1,"question":"Was ist an Jonas' Überlegung fehlerhaft?","options":["Er rechnet die ausgegebenen 3.000 Euro, die nicht mehr zurückzuholen sind, in eine Entscheidung ein, die nur von künftigen Kosten und Nutzen abhängen sollte.","Er hängt am Motorrad, nur weil es ihm gehört, und bewertet es deshalb höher als das zuverlässige für 2.500 Euro, das ihm nicht gehört (Besitztumseffekt).","Er setzt die Reparatur für 1.800 Euro zu optimistisch als die letzte an, weil Vorhaben meist länger dauern und mehr kosten als geplant (Planungsfehlschluss).","Er orientiert sich an anderen Motorradbesitzern, die ihre Maschinen trotz wiederholter Werkstattbesuche weiterreparieren, und folgt damit der Mehrheit (Mitläufereffekt)."],"correctIndex":0,"explanation":"Die 3.000 Euro sind weg, egal ob Jonas weiterrepariert oder aufgibt; sie verändern keine der beiden Möglichkeiten. Vernünftig ist ein Vergleich dessen, was noch kommt: weitere 1.800 Euro für ein Motorrad mit unsicherem Zustand gegen 2.500 Euro für ein zuverlässiges, abzüglich dessen, was das alte beim Verkauf noch einbringt. Dieser Vergleich kann durchaus für die Reparatur ausgehen; fehlerhaft ist die Begründung, denn wer die Vergangenheit mitrechnet, weil sonst alles „umsonst“ gewesen wäre, hält leicht an einer schlechten Investition fest. Diese Falle heißt Versunkene-Kosten-Falle (Sunk Cost Fallacy). Eine hilfreiche Prüffrage: Würdest du das Motorrad in diesem Zustand heute zu diesem Preis neu kaufen?","coreRule":"⚡ Entscheide nach dem, was kommt, nicht nach dem, was schon weg ist.","beleg":"Werkstück B.6 (Kernidee; Kontext & Tiefe); Fn. gl-b-sunk-cost (Arkes/Blumer 1985, OBHDP 35(1), S. 124)","status":"entwurf","scenario":"Jonas hat vor einem Jahr 3.000 Euro in ein gebrauchtes Motorrad gesteckt. Seitdem war er viermal in der Werkstatt, der Motor macht weiter Probleme, und der Mechaniker schätzt die nächste Reparatur auf weitere 1.800 Euro. Ein vergleichbares, zuverlässiges Motorrad gäbe es für 2.500 Euro. Jonas sagt: „Ich habe schon 3.000 Euro hineingesteckt. Wenn ich jetzt aufgebe, war das alles umsonst. Ich repariere weiter.“","quote":"","quoteLabel":"","kurz":"Die 3.000 Euro sind weg, ob Jonas repariert oder aufgibt. Entscheidend ist nur, was noch kommt: 1.800 Euro für unsicheren Zustand gegen 2.500 Euro für Zuverlässigkeit. Das Argument „sonst war alles umsonst“ rechnet Vergangenes mit.","prueffrage":"Was spricht nach vier Werkstattbesuchen dafür, dass die nächste Reparatur die letzte ist?","rueckmeldung":[{"option":1,"text":"Dass Eigenes oft höher bewertet wird, ist ein bekannter Effekt. Jonas begründet aber nicht mit Zuneigung zum Motorrad, sondern mit dem bereits ausgegebenen Geld; genau dieses Argument trägt die Entscheidung nicht."},{"option":2,"text":"Reparaturen werden tatsächlich oft teurer als gedacht. Die 1.800 Euro stammen hier aber vom Mechaniker, und Jonas behauptet nicht, es sei die letzte Reparatur. Seine Begründung hängt an der Vergangenheit, nicht an der Schätzung."},{"option":3,"text":"Sich an der Mehrheit zu orientieren, kann Entscheidungen verzerren. Im Szenario kommen aber keine anderen Besitzer vor; Jonas begründet allein mit dem bereits investierten Geld."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1b4df1ffec23e15f"}},{"id":"qx-b1-021","clusterId":"B","werkstueckRef":"B.6","stufe":2,"question":"Welche Prüffrage setzt genau am Fehler in der Begründung der Leitung an?","scenario":"In deiner Firma läuft seit vier Jahren ein Softwareprojekt, das nach Einschätzung des Teams nie fertig wird. In der Sitzung sagt die Leitung: „Wir haben schon so viel investiert – jetzt aufzugeben wäre Verschwendung.“ Du darfst eine einzige Prüffrage stellen.","options":["„Könnten wir den Verlust verkraften, der bei einem Abbruch nach vier Jahren Arbeit abzuschreiben wäre?“","„Würden wir dieses Projekt heute, im jetzigen Zustand und mit dem heutigen Wissen, noch einmal beginnen?“","„Haben wir in den ersten vier Jahren Fehler gemacht, aus denen wir für künftige Projekte lernen können?“","„Hat die Leitung, die das Projekt vor vier Jahren angestoßen hat, damals alle Beteiligten ausreichend angehört?“"],"correctIndex":1,"explanation":"Der Fehler liegt darin, dass bereits ausgegebenes Geld und vergangene Mühe zum Grund für die Fortsetzung gemacht werden. Diese Kosten sind unwiederbringlich weg, egal ob das Projekt weiterläuft oder nicht; für die Entscheidung zählen nur künftige Kosten und künftiger Nutzen. Die Frage, ob man das Vorhaben heute im jetzigen Zustand neu beginnen würde, blendet die Vergangenheit aus und zwingt dazu, nur die Zukunft zu bewerten.","coreRule":"⚡ Frag nicht, wie viel du schon investiert hast, sondern ob du heute noch einsteigen würdest.","quote":"Würde ich einsteigen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.6 (Das Anti-Denkmuster; Verbindungen: Null-Basis-Check A.14)","status":"entwurf","kurz":"Die Begründung der Leitung stützt sich auf Geld und Mühe, die ohnehin verloren sind, egal ob das Projekt weiterläuft. Wer fragt, ob man heute noch einmal beginnen würde, blendet das aus und bewertet nur künftige Kosten und künftigen Nutzen.","prueffrage":"Welchen Grund nennt die Leitung in der Sitzung dafür, das Projekt weiterzuführen?","rueckmeldung":[{"option":0,"text":"Die Frage klingt nach nüchterner Finanzplanung, bleibt aber bei Geld, das bereits ausgegeben ist. Ob man den Verlust verkraftet, spricht weder für noch gegen die Fortsetzung und bewertet nicht, was künftig noch kostet und bringt."},{"option":2,"text":"Aus den Fehlern der ersten Jahre zu lernen ist wertvoll, vor allem für spätere Projekte. Für die Frage, ob das Weitermachen jetzt begründet ist, sagt diese Rückschau jedoch nichts aus und lässt die Begründung der Leitung unberührt."},{"option":3,"text":"Ob damals alle Beteiligten gehört wurden, kann eine berechtigte Frage an den Entscheidungsprozess sein. Sie betrifft aber die Vergangenheit und klärt nicht, ob das Projekt künftig mehr nützt, als es noch kostet."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6d9a5758a342f745"}},{"id":"qx-b1-022","clusterId":"B","werkstueckRef":"B.6","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass aus gesunder Ausdauer irrationale Sturheit geworden ist?","options":["Die Gründerin macht weiter, obwohl der Markttest eindeutig negativ ausfiel, und verweist auf die zwei Jahre, die sie schon investiert hat.","Der Doktorand wiederholt sein Experiment, obwohl der erste Versuch ein Jahr Arbeit kostete und scheiterte, und verweist auf den gefundenen Messfehler.","Der Mann hält an der Fernbeziehung fest, obwohl der Alltag nach Jahren des Pendelns anstrengend bleibt, und verweist auf den vereinbarten Umzug.","Die Frau behält ihre Aktien, obwohl der Kurs im letzten Monat fiel und sie im Minus liegt, und verweist auf die unveränderten Geschäftszahlen."],"correctIndex":0,"explanation":"Ausdauer ist oft nötig und nützlich: Wer nach dem ersten Rückschlag aufgibt, erreicht langfristige Ziele nie. Der Kipppunkt zur Sturheit liegt dort, wo neue, negative Informationen ignoriert werden, um die ursprüngliche Entscheidung zu schützen. Entscheidend ist also, wie jemand mit neuer Information umgeht und wonach er seine Entscheidung begründet. Nur die Gründerin stützt sich auf bereits Investiertes und übergeht die eindeutig negative Information. Die zwei Jahre sind unwiederbringlich verloren, gleich wie sie sich entscheidet, und dürfen deshalb die Entscheidung über die Zukunft nicht lenken. Prüffrage: Würde ich heute, mit dem aktuellen Wissen, noch einmal einsteigen?","coreRule":"⚡ Ausdauer hält durch, trotz Schwierigkeiten – Sturheit hält fest, trotz Gegenbeweisen.","beleg":"Werkstück B.6 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","scenario":"Vier Menschen halten an einem Vorhaben fest, das nicht richtig läuft: eine Gründerin mit ihrem Start-up, ein Doktorand mit seinem Experiment, ein Mann mit seiner Fernbeziehung und eine Frau mit ihrer Aktienposition.","kurz":"Entscheidend ist, wonach jemand sich richtet: Die gescheiterte Gründerin beruft sich auf bereits investierte Jahre und übergeht ein eindeutig negatives Ergebnis. Diese Jahre sind verloren, so oder so, und dürfen die Entscheidung über die Zukunft nicht lenken.","prueffrage":"Worauf stützt sich jede der vier Personen, wenn sie begründet, warum sie weitermacht?","rueckmeldung":[{"option":1,"text":"Ein Jahr verlorene Arbeit und ein gescheiterter Versuch lassen an Sturheit denken. Der Doktorand nennt aber einen konkreten Messfehler, den er beim nächsten Versuch ausschließen kann; sein Grund zeigt also nach vorn."},{"option":2,"text":"Jahre des Pendelns und ein weiterhin anstrengender Alltag wirken wie ein Zeichen für Sturheit. Der vereinbarte Umzug ist jedoch ein Grund, der in die Zukunft weist und den Alltag ändern wird; Anstrengung allein zeigt noch nichts."},{"option":3,"text":"Ein gefallener Kurs und ein Minus klingen nach einem Fehler, an dem man nicht festhalten sollte. Ein Verlust auf dem Papier sagt aber wenig, und die Frau stützt sich auf unveränderte Geschäftszahlen, also auf einen Grund für die Zukunft."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"70f5a8d617144fac"}},{"id":"qx-b1-023","clusterId":"B","werkstueckRef":"B.6","stufe":4,"question":"Welche Rückfrage der Freundin würde ihr am besten helfen, ihre Entscheidung neu zu prüfen?","scenario":"Eine Frau engagiert sich seit zehn Jahren in einer Gemeinschaft, die eine bestimmte Lehre vertritt. Inzwischen hat sie ernste Zweifel an deren Aussagen. Eine Freundin fragt sie, warum sie trotzdem bleibt. Sie antwortet: „Ich habe zehn Jahre, meine Freundschaften und mein Geld hineingesteckt. Wenn ich jetzt gehe, war das alles umsonst.“","options":["„Würdest du heute, so wie du die Lehre jetzt einschätzt, neu einsteigen?“","„Wie viel Geld und Zeit hast du investiert, und was davon ist noch zu retten?“","„Wann sind deine Zweifel zum ersten Mal aufgekommen, und was hat sie ausgelöst?“","„Gab es in den zehn Jahren auch gute Momente, und was haben sie dir bedeutet?“"],"correctIndex":0,"explanation":"Die zehn Jahre und das Geld sind ausgegeben und kommen nicht zurück, egal ob sie bleibt oder geht; solche versunkenen Kosten sollten die künftige Entscheidung nicht lenken. Zählen darf, was von nun an für oder gegen das Bleiben spricht, und dazu gehört auch, welche Freundschaften ein Austritt gefährden würde; über die Lehre selbst sagt aber auch das nichts. Die Frage nach dem Neueinstieg richtet den Blick genau darauf und zwingt, die Lehre so zu bewerten, wie sie heute dasteht. Genau diese Bindung ans Investierte hält Menschen oft in Kulten und Glaubenssystemen fest, selbst wenn Zweifel aufkommen. Den Aufwand zu überblicken ist verständlich, doch das Investierte lässt sich nicht zurückholen und ändert nichts an der künftigen Lage. Zu wissen, wann die Zweifel begannen, kann beim Verstehen helfen, prüft aber die Lehre nicht. Und die guten Momente gehören zur Vergangenheit, sie sagen nichts darüber, was die Lehre heute wert ist.","coreRule":"⚡ Bereits Verlorenes darf die Entscheidung nicht lenken: Frag, ob du heute noch einsteigen würdest.","beleg":"Werkstück B.6 (Anwendung & Relevanz: Bei irrationalen Glaubenssystemen; Kontext & Tiefe)","status":"entwurf","kurz":"Die zehn Jahre und das Geld sind weg, egal ob sie bleibt oder geht, und sollten daher nicht lenken. Die Frage nach dem Neueinstieg bewertet die Lehre so, wie sie heute dasteht, und löst damit die Bindung ans Investierte.","prueffrage":"Was genau an den Aussagen der Gemeinschaft bezweifelt sie, und seit wann?","rueckmeldung":[{"option":1,"text":"Sich den Aufwand klarzumachen ist verständlich und wirkt wie eine nüchterne Bilanz. Zurückholen lässt sich davon aber nichts, und für das Weitere ändert es nichts. Wer fragt, was noch zu retten ist, hält den Blick auf der Vergangenheit."},{"option":2,"text":"Zu wissen, wann und wodurch die Zweifel begannen, kann helfen, sie zu verstehen. Ob die Lehre heute trägt, prüft das jedoch nicht, denn es beleuchtet nur, wie die Zweifel entstanden sind."},{"option":3,"text":"Gute Erfahrungen zählen für ihr Leben durchaus. Sie liegen aber hinter ihr und sagen nichts darüber, was die Lehre heute wert ist. Genau das müsste sie für ihre Entscheidung klären."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"afb025096b34e889"}},{"id":"qx-b1-024","clusterId":"B","werkstueckRef":"B.7","stufe":1,"question":"Was ist an der Aussage der Kollegin das Hauptproblem?","scenario":"Am Tag nach einer Wahl, bei der Kandidat A überraschend deutlich gewonnen hat, hörst du in der Kantine drei Sätze: (a) „Das musste ja so kommen.“ (b) „Ich habe doch gesagt, dass er gewinnt“ – dabei hatte sich der Sprecher vor der Wahl auf keinen Sieger festgelegt. (c) Eine Kollegin: „Das hätte man doch sehen müssen!“ Du weißt, dass vor der Wahl selbst Fachleute uneins waren und die Umfragen knapp standen.","options":["Sie misst die Vorhersehbarkeit am Ergebnis und blendet aus, dass Fachleute vorher uneins waren und die Umfragen knapp standen.","Sie wertet den Sieg von A ab, weil sie ihn politisch ablehnt, und urteilt parteiisch (Gruppenzugehörigkeits-Verzerrung).","Sie führt den überraschend deutlichen Sieg von A allein auf dessen Persönlichkeit zurück, nicht auf die Umstände (Attributionsfehler).","Sie stützt sich auf einprägsame Bilder aus dem Wahlkampf von A statt auf nüchterne Umfragezahlen und Prognosen (Verfügbarkeitsheuristik)."],"correctIndex":0,"explanation":"Wer den Ausgang kennt, sortiert die damaligen Informationen neu: Was zum Ergebnis passt, wirkt im Rückblick wichtig, was auf andere Ausgänge hindeutete, verliert an Gewicht. Vor der Wahl waren selbst Fachleute uneins und die Umfragen knapp, die Lage war also offen; der Satz „Das hätte man doch sehen müssen!“ misst sie am Wissen von heute und urteilt dadurch unfair. Die drei Sätze aus der Kantine zeigen drei Spielarten des Rückschaufehlers: „Das musste ja so kommen“ ist das Gefühl der Unvermeidbarkeit, „Ich habe doch gesagt, dass er gewinnt“ die Gedächtnisverzerrung (die eigene frühere Einschätzung rutscht in Richtung des Ergebnisses), „Das hätte man doch sehen müssen!“ das Gefühl der Vorhersehbarkeit. Hilfreich ist die Frage: Welche Informationen, die ich jetzt habe, hatte damals noch niemand?","coreRule":"⚡ Rückblickend wirkt alles zwingend, vorhersehbar und längst gewusst – dabei war es damals offen. Prüfe, was man zum Zeitpunkt der Entscheidung wissen konnte.","beleg":"Werkstück B.7 (Kontext & Tiefe, drei Ebenen); Fn. gl-b-rueckschau-ebenen (Roese/Vohs 2012, Perspectives on Psychological Science 7(5), S. 412–413)","status":"entwurf","kurz":"Wer das Ergebnis kennt, misst die damalige Lage daran und findet es im Rückblick offensichtlich. Dabei waren Fachleute uneins und die Umfragen knapp: Vorher war die Lage offen, und genau das blendet der Satz aus.","prueffrage":"Welche Tipps gaben die Leute in der Kantine vor der Wahl ab, und wie sicher waren sie sich damals?","rueckmeldung":[{"option":1,"text":"Eine politische Ablehnung kann ein Urteil färben, nur gibt das Szenario dafür keinen Anhaltspunkt. Der Satz „Das hätte man sehen müssen!“ bewertet den Sieg nicht, er behauptet, man hätte ihn vorher erkennen können."},{"option":2,"text":"Persönlichkeit statt Umstände zu betonen ist ein bekannter Denkfehler, kommt hier aber nicht vor: Die Kollegin sagt nichts über die Gründe für As Sieg oder über A als Person. Sie bewertet, was vorher erkennbar gewesen wäre."},{"option":3,"text":"Auffällige Bilder können Einschätzungen tatsächlich verzerren. Hier ist davon aber keine Rede: Die Kollegin beruft sich weder auf Bilder noch auf Zahlen, sondern misst die damalige, offene Lage am heutigen Ergebnis."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"161–162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"41f7297f8014b433"}},{"id":"qx-b1-025","clusterId":"B","werkstueckRef":"B.7","stufe":2,"question":"Welches Vorgehen schützt am besten davor, dass das Wissen um den Ausgang die Erinnerung und das Urteil verfälscht?","scenario":"Anna wechselt den Job. Ein halbes Jahr später läuft es schlecht, und sie denkt: „Ich hab doch gleich gespürt, dass das nicht passt.“ Ihr Freund Ben erinnert sich anders: Damals war sie begeistert und hielt den Wechsel für eine große Chance. Beide wollen bei der nächsten wichtigen Entscheidung später ehrlich beurteilen können, was sie vorher wussten und wie gut sie entschieden haben.","options":["Nach dem Ergebnis in Ruhe überlegen, was man damals eigentlich geglaubt und gewusst hat.","Die Entscheidung so lange aufschieben, bis der Ausgang sicher genug absehbar ist.","Das Ergebnis konsequent als Maßstab nehmen, um die Entscheidung als gut oder schlecht zu bewerten.","Gründe und Unsicherheitsgrad vorab schriftlich festhalten, bevor das Ergebnis bekannt ist."],"correctIndex":3,"explanation":"Wer vor der Entscheidung schriftlich festhält, was er weiß und wie sicher er sich ist, hat später einen Beleg, der nicht mehr durch das Ergebnis verfälscht werden kann. Die Erinnerung nach dem Ausgang ist dagegen genau das, was der Rückschaufehler verzerrt: Wir sind dann überzeugt, es „schon immer gewusst“ zu haben. Auch das Ergebnis taugt nicht als Maßstab, denn eine gute Entscheidung kann schlecht ausgehen und umgekehrt. Beurteilen lässt sich eine Entscheidung nur danach, was zum Zeitpunkt der Entscheidung bekannt und absehbar war. Und abwarten, bis der Ausgang absehbar ist, würde die Entscheidung gerade unmöglich machen, denn Entscheidungen müssen unter Unsicherheit fallen.","coreRule":"⚡ Schreib auf, was du weißt und wie sicher du bist – bevor du das Ergebnis kennst.","beleg":"Werkstück B.7 (Verbindungen: Entscheidungs-Tagebuch; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer vorab schriftlich festhält, was er weiß und wie sicher er ist, hat später einen Beleg, den das Ergebnis nicht färben kann. Die Erinnerung danach neigt dazu, „das habe ich immer gewusst“ zu sagen.","prueffrage":"Wie sicher sind sich Anna und Ben jeweils ihrer Erinnerung, und wie ließe sich heute klären, wer recht hat?","rueckmeldung":[{"option":0,"text":"Nachträgliches Nachdenken klingt gründlich, stützt sich aber auf genau die Erinnerung, die der Ausgang färbt. Das zeigen Anna und Ben: Beide sind überzeugt, und ihre Erinnerungen widersprechen sich."},{"option":1,"text":"Wer wartet, bis der Ausgang absehbar ist, entscheidet nicht mehr unter Unsicherheit, sondern gar nicht. Das Problem der verfälschten Rückschau bleibt trotzdem für alle späteren Urteile bestehen."},{"option":2,"text":"Ein Ergebnis sagt zwar etwas, ist aber ein schlechter alleiniger Maßstab: Gute Entscheidungen können schlecht ausgehen und umgekehrt. Beurteilbar ist nur, was zum Zeitpunkt der Entscheidung bekannt und absehbar war."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b5fa7f18433318f4"}},{"id":"qx-b1-026","clusterId":"B","werkstueckRef":"B.7","stufe":4,"question":"Wie prüfst du am besten, ob diese Strophe das Ereignis wirklich vorhergesagt hat?","scenario":"Nach einer Katastrophe zeigt dir jemand eine mehrdeutige Strophe aus einer alten Prophezeiungssammlung. Er sagt, sie habe genau dieses Ereignis „vorhergesagt“, und verweist darauf, dass sich im Text Bilder finden, die zum Geschehen passen.","options":["Du fragst, ob sich die Handschrift der Strophe sicher auf die Zeit vor der Katastrophe datieren lässt, bevor du sie mit dem Ereignis verbindest.","Du fragst, ob die Deutung der Bilder schon vor der Katastrophe festgehalten wurde und konkret genug war, um scheitern zu können.","Du fragst, ob die Bilder der Strophe korrekt übersetzt wurden, da Übersetzungen die Bedeutung mehrdeutiger Bilder verschieben können.","Du fragst, ob die Person, die die Strophe deutet, Fachwissen über die Sammlung hat und seriös auftritt, bevor du ihrer Deutung traust."],"correctIndex":1,"explanation":"Ob die Deutung schon vor der Katastrophe festgehalten wurde, ist offen; oft wird zu einer mehrdeutigen Strophe erst nachträglich ein passendes Ereignis gesucht. Wer den Ausgang kennt, findet in vagen Bildern fast immer Anknüpfungspunkte, deshalb beweisen passende Bilder nichts. Echte Vorhersagekraft zeigt nur eine Aussage, die vor dem Ereignis festgehalten wurde und so konkret war, dass sie hätte scheitern können. Fehlt das, bleibt nur Deutungskraft im Rückblick. Die anderen Prüfungen klingen sinnvoll, greifen aber zu kurz: Das Alter der Handschrift zu klären ist bei der Echtheit wichtig, aber der Text ist ja alt; das Problem ist nicht, wann er entstand, sondern ob die Deutung vorab feststand. Eine genaue Übersetzung hilft, löst aber nicht das Problem, dass die Bilder mehrdeutig bleiben. Und das Fachwissen der Deutenden macht eine Deutung nicht überprüfbar, die erst nach dem Ereignis entstand.","coreRule":"⚡ Eine Vorhersage zählt nur, wenn sie vor dem Ereignis eindeutig festgehalten wurde.","beleg":"Werkstück B.7 (Anwendung & Relevanz: In der Esoterik)","status":"entwurf","kurz":"Echte Vorhersagekraft zeigt nur, was vor dem Ereignis festgehalten wurde und so konkret war, dass es hätte scheitern können. Wer den Ausgang kennt, findet in vagen Bildern fast immer Passendes; das bleibt dann Deutung im Rückblick.","prueffrage":"Auf wie viele andere Katastrophen der letzten Jahrzehnte ließe sich dieselbe Strophe ebenso gut beziehen?","rueckmeldung":[{"option":0,"text":"Die Datierung der Handschrift ist wichtig, wenn es um die Echtheit geht. Hier ist der Text aber ohnehin alt; offen bleibt, ob die Deutung schon vor dem Ereignis feststand und scheitern konnte."},{"option":2,"text":"Eine genaue Übersetzung ist sinnvoll, löst aber das Kernproblem nicht: Auch eine korrekt übersetzte Strophe bleibt mehrdeutig, und im Rückblick passt zu vagen Bildern fast immer ein Ereignis."},{"option":3,"text":"Fachwissen und seriöses Auftreten sprechen für eine sorgfältige Deutung, machen sie aber nicht überprüfbar. Eine Deutung, die erst nach dem Ereignis entstand, wird dadurch nicht zur Vorhersage."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c5e3b45a78c2778b"}},{"id":"qx-b1-027","clusterId":"B","werkstueckRef":"B.8","stufe":1,"question":"Was ist an dieser Überlegung fehlerhaft?","options":["Du erklärst sein Verhalten mit einer dauerhaften Eigenschaft und blendest die Umstände aus, die du nicht kennst (Attributionsfehler).","Du überträgst auf Jonas, was man Kollegen seines Typs nachsagt, und siehst den Einzelfall nicht mehr (Stereotypisierung).","Du achtest nur auf Vorfälle, die zum Bild des Egoisten passen, und blendest Jonas' rücksichtsvolle Seiten aus (Bestätigungsfehler).","Du wertest Jonas ab, damit du selbst im Vergleich mit ihm als rücksichtsvoller Kollege dastehst (selbstwertdienliche Verzerrung)."],"correctIndex":0,"explanation":"Aus einem einzelnen Verhalten wird hier auf eine stabile Eigenschaft geschlossen („Egoist“, „schon immer“), während die Situation, die du nicht kennst, gar nicht in die Erklärung eingeht. Das ist der typische Fehlschluss beim Beurteilen anderer: Die Person ist das Auffälligste, was wir sehen, ihre Umstände sind für uns unsichtbar. Der Fehler besteht in der Tendenz, die Situation zu unterschätzen, nicht darin, dass der Charakter nie eine Rolle spielt.","coreRule":"⚡ Wer ein Verhalten sofort mit dem Charakter erklärt, sieht die Umstände nicht, die er nicht kennt.","beleg":"Werkstück B.8 (Kernidee; Kontext & Tiefe, Fokus der Aufmerksamkeit; Hinweis zur Beleglage); Fn. gl-b-attribution (Ross/Anderson 1982, Kap. 9)","status":"entwurf","scenario":"Du erfährst, dass Jonas bei der Teamsitzung gestern zwei Kollegen mehrfach das Wort abgeschnitten hat. Dein Gedanke: „Der ist einfach ein rücksichtsloser Egoist, so war der schon immer.“ Über Jonas' Woche weißt du nichts. Was du nicht weißt: Er hatte kurz vorher einen Abgabetermin mit großem Zeitdruck.","kurz":"Aus einem einzelnen Verhalten wird hier ein dauerhafter Charakterzug gemacht, während der Zeitdruck, den du nicht kennst, in die Erklärung gar nicht eingeht. Die Person fällt auf, ihre Umstände bleiben unsichtbar; das heißt aber nicht, dass der Charakter nie eine Rolle spielt.","prueffrage":"Wie hat sich Jonas in früheren Sitzungen verhalten, und wer hat das selbst erlebt?","rueckmeldung":[{"option":1,"text":"Hier ist wirklich ein vorschnelles Urteil über eine Person im Spiel. Eine Gruppe, deren angebliche Eigenschaften auf Jonas übertragen würden, kommt in deinem Gedanken aber gar nicht vor; er wird nur über sich selbst beurteilt."},{"option":2,"text":"„So war der schon immer“ klingt nach einer Verallgemeinerung. Beschrieben wird aber keine Sammlung passender Vorfälle: Der Gedanke stützt sich auf den einen Auftritt in der Sitzung und lässt keine Gegenbeispiele beiseite."},{"option":3,"text":"Eine Abwertung kann tatsächlich dem eigenen Selbstbild dienen. In deinem Gedanken steckt aber kein Vergleich mit dir selbst; es geht allein um Jonas und darum, wie sein Verhalten erklärt wird."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6), Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"df7ec6a75c3ca474"}},{"id":"qx-b1-028","clusterId":"B","werkstueckRef":"B.8","stufe":3,"question":"In einem Podcast heißt es: „Jeder weiß doch: Wir erklären unser eigenes Fehlverhalten mit den Umständen, das Fehlverhalten anderer aber mit deren Charakter. Das ist psychologisch erwiesen.“ Du erfährst, dass eine Auswertung von 173 Studien genau diese Behauptung geprüft hat. Welche Frage hilft dir jetzt am meisten, um die Aussage einzuordnen?","options":["Wie groß war der durchschnittliche Effekt über alle 173 Studien hinweg, und unter welchen Bedingungen zeigte er sich überhaupt?","Wie viele Versuchspersonen nahmen an den 173 Studien insgesamt teil, und wie groß war die kleinste einzelne Studie?","Wer hat die Auswertung der 173 Studien bezahlt, und hatten die Autorinnen ein Interesse an einem bestimmten Ergebnis?","Welche der 173 Studien fand den stärksten Effekt, und wie wurde dort das Verhalten der Versuchspersonen gemessen?"],"correctIndex":0,"explanation":"Wer eine Behauptung prüfen will, schaut auf die Gesamtlage der Belege statt auf Bekanntheit, Einzelfälle oder das eigene Gefühl. Tatsächlich fand die Auswertung von 173 Studien (Malle 2006) für diese Asymmetrie im Durchschnitt praktisch keinen Effekt. Sie zeigte sich nur unter bestimmten Bedingungen, vor allem bei negativem Verhalten, und auch dort nur klein; bei positivem Verhalten kehrte sie sich um. Eine Behauptung kann jahrzehntelang als gesichert gelten und der Überprüfung trotzdem nur teilweise standhalten.","coreRule":"⚡ Auch Lehrbuchwissen braucht einen Quellencheck: Frag nach der Gesamtlage der Belege (Größe und Bedingungen des Effekts), nicht nach Bekanntheit oder Einzelfällen.","beleg":"Werkstück B.8 (Hinweis zur Beleglage); Fn. gl-b-attribution (Malle 2006, Psychological Bulletin 132(6), S. 895, 902, 907)","status":"entwurf","scenario":"Du hörst den Podcast beim Kochen und möchtest die Aussage nicht einfach glauben oder abtun.","kurz":"Entscheidend ist die Gesamtlage: Im Durchschnitt aller 173 Studien zeigte sich praktisch kein Effekt, nur unter bestimmten Bedingungen ein kleiner. Wer eine „erwiesene“ Behauptung nur aus Bekanntheit übernimmt, übersieht, dass sie der Prüfung oft nur teilweise standhält.","prueffrage":"Woher weiß der Podcast, dass „jeder“ das so macht, und welche Belege nennt er dafür?","rueckmeldung":[{"option":1,"text":"Eine große Teilnehmerzahl wirkt beruhigend, weil sie die Auswertung genauer macht. Wie groß der Effekt ist und wann er auftritt, sagt sie aber nicht: Auch eine sehr genaue Auswertung kann einen winzigen Effekt zeigen."},{"option":2,"text":"Wer bezahlt hat, ist eine berechtigte Frage, denn sie hilft, mögliche Interessen zu erkennen. Sie beantwortet aber nicht, was die Daten zeigen, und genau das brauchst du, um die Aussage einzuordnen."},{"option":3,"text":"Der stärkste Einzelbefund klingt nach dem besten Beleg für die Behauptung. Ein Spitzenwert unter 173 Studien sagt aber wenig über den Durchschnitt und darüber, unter welchen Bedingungen der Effekt auftritt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis, Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6)","oeffentlich":false,"doi":"10.1037/0033-2909.132.6.895","seite":"895, 902"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"be2554486916f577"}},{"id":"qx-b1-029","clusterId":"B","werkstueckRef":"B.8","stufe":4,"question":"Wie solltest du den Schluss einschätzen, der Attributionsfehler („wir erklären das Verhalten anderer vorschnell mit ihrem Charakter“) sei ein universelles Merkmal des Menschen?","options":["Die Verallgemeinerung geht zu weit: Vergleichsstudien deuten darauf hin, dass der Effekt außerhalb des Westens schwächer ausfällt, etwa bei Ostasiaten.","Die Verallgemeinerung ist vertretbar: Dass die Person das Auffälligste ist, was man sieht, gehört zur Wahrnehmung und wirkt deshalb in allen Kulturen gleich.","Die Verallgemeinerung ist widerlegt: Weil nur westliche Versuchspersonen untersucht wurden, steht fest, dass der Effekt anderswo fehlt.","Die Herkunft der Versuchspersonen spielt keine Rolle: Entscheidend ist, dass die klassischen Experimente das Ergebnis immer wieder erbracht haben."],"correctIndex":0,"explanation":"Eine Verallgemeinerung ist nur so gut wie die Gruppe, an der getestet wurde. Wurden die klassischen Versuche fast nur mit westlichen Versuchspersonen gemacht, sagt das wenig über „den Menschen“ insgesamt. Tatsächlich deuten Vergleichsstudien darauf hin, dass der „fundamentale“ Fehler anderswo weniger grundlegend wirkt: Ostasiaten schlossen eher als US-Amerikaner auf die Macht der Situation, besonders wenn die Umstände deutlich hervorgehoben waren; ähnliche Befunde gibt es für Russen und früher für Hindus in Indien. Die angemessene Haltung: Der Effekt ist real, aber in Stärke und Verbreitung kulturabhängig.","coreRule":"⚡ Von einer Stichprobe auf „alle Menschen“ zu schließen, ist nur erlaubt, wenn die Stichprobe die Vielfalt der Menschen abbildet.","beleg":"Werkstück B.8 (Kontext & Tiefe); Fn. gl-b-attribution-kultur (Henrich/Heine/Norenzayan 2010, RatSWD Working Paper 139, S. 25 f.)","status":"entwurf","scenario":"In einem Podcast heißt es: „Dass wir das Verhalten anderer vorschnell mit ihrem Charakter erklären und die Umstände unterschätzen, ist ein Grundzug der menschlichen Natur – das tun alle Menschen überall gleich stark, das haben Experimente gezeigt.“ Die klassischen Experimente, auf die sich die Aussage stützt, wurden ganz überwiegend mit westlichen Versuchspersonen durchgeführt.","quote":"","quoteLabel":"","kurz":"Eine Verallgemeinerung trägt nur so weit wie die untersuchte Gruppe. Der Effekt ist real, fällt aber in Vergleichsstudien kulturell unterschiedlich stark aus. Wer von westlichen Versuchspersonen auf „den Menschen“ schließt, überdehnt den Befund.","prueffrage":"An wem wurden die klassischen Experimente eigentlich durchgeführt?","rueckmeldung":[{"option":1,"text":"Dass die Person ins Auge fällt, ist plausibel. Daraus folgt aber nicht, dass die Wirkung überall gleich stark ausfällt, und Vergleichsstudien zeigen genau hier Unterschiede."},{"option":2,"text":"Die Lücke bei den Versuchspersonen ist echt und lässt den Schluss zu weit greifen. Fehlende Daten sind aber noch kein Gegenbeleg: Charakterurteile gibt es auch anderswo, vermutlich nur in anderer Stärke."},{"option":3,"text":"Ein Ergebnis, das sich oft wiederholt, wirkt gut abgesichert. Wiederholungen mit ähnlichen Versuchspersonen zeigen aber nur, dass es bei ihnen stabil ist, nicht, dass es für andere Gruppen gilt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The Weirdest People in the World? RatSWD Working Paper 139 (KonsortSWD)","oeffentlich":true,"url":"https://www.konsortswd.de/wp-content/uploads/RatSWD_WP_139.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The weirdest people in the world? Behavioral and Brain Sciences 33(2–3)","oeffentlich":false,"doi":"10.1017/S0140525X0999152X"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"eee5fddc2c58bce1"}},{"id":"qx-b1-030","clusterId":"B","werkstueckRef":"B.8","stufe":2,"question":"Welche Frage prüft ihre Erklärung am besten?","scenario":"Eine Kollegin sagt über Menschen, die auf Heilkristalle schwören: „Die sind halt naiv und ungebildet.“ Du willst ihre Erklärung prüfen, bevor du sie übernimmst.","options":["Gibt es kontrollierte Studien, die zeigen, ob Heilkristalle über den Placebo-Effekt hinaus wirken?","Welche Hersteller verdienen an Heilkristallen, und wie stark bewerben sie ihre Produkte gegenüber Kunden?","Welche Umstände, etwa Kontrollbedürfnis oder enttäuschende Erfahrungen, machen den Glauben für sie attraktiv?","Wie viele Menschen kaufen Heilkristalle, und wie hat sich diese Zahl in den letzten Jahren entwickelt?"],"correctIndex":2,"explanation":"Die Kollegin führt das Verhalten anderer auf einen stabilen Charakterzug zurück: Sie seien „halt naiv und ungebildet“. Die Situation der Betroffenen blendet sie aus. Diese Verzerrung heißt fundamentaler Attributionsfehler: Wir unterschätzen bei anderen die Macht der Umstände und überschätzen ihre Eigenschaften. Bei Glaubensüberzeugungen können ganz verschiedene Umstände eine Rolle spielen, etwa ein Bedürfnis nach Kontrolle, schlechte Erfahrungen mit der Schulmedizin oder starker sozialer Einfluss im Umfeld. Wer nach ihnen fragt, prüft die Charaktererklärung an der Wirklichkeit. Das ist keine Rechtfertigung des Glaubens, sondern eine bessere Erklärung. Die anderen Fragen sind in anderer Lage sinnvoll, klären hier aber nichts: Ob Heilkristalle wirken, sagt nichts darüber, warum Menschen daran glauben. Wer am Geschäft verdient, erklärt das Angebot, nicht die Nachfrage. Und wie verbreitet der Glaube ist, zeigt nur seine Größe, nicht seine Gründe.","coreRule":"⚡ Frag nach den Umständen, bevor du über den Charakter urteilst.","beleg":"Werkstück B.8 (Anwendung & Relevanz: Bei Aberglaube & Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer fragt, in welcher Lage Menschen so etwas glauben, prüft die Charaktererklärung an der Wirklichkeit. „Naiv und ungebildet“ blendet die Umstände aus: Wir überschätzen bei anderen Eigenschaften und unterschätzen, was Situationen bewirken können.","prueffrage":"Was weiß die Kollegin über diese Menschen, außer dass sie an Heilkristalle glauben?","rueckmeldung":[{"option":0,"text":"Ob Heilkristalle wirken, lässt sich über Studien klären und ist eine berechtigte Frage. Warum Menschen daran glauben, beantwortet sie nicht: Auch Wirkungslosigkeit sagt nichts über die Gründe der Gläubigen."},{"option":1,"text":"Dass Hersteller werben und verdienen, erklärt vor allem das Angebot. Warum Kundinnen und Kunden darauf eingehen, bleibt offen, und gerade das müsstest du klären, um die Erklärung der Kollegin zu prüfen."},{"option":3,"text":"Die Zahl der Käufer und ihr Verlauf zeigen, wie verbreitet der Glaube ist. Warum Menschen so entscheiden, verraten sie nicht, und eine bloße Größe prüft keine Erklärung, die auf Eigenschaften der Käufer zielt."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ross, L.; Anderson, C. A. (1982): Shortcomings in the attribution process. In: Kahneman, D.; Slovic, P.; Tversky, A. (Hg.): Judgment under Uncertainty. Cambridge University Press, Kap. 9","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"202568560ebb7134"}},{"id":"qx-b1-031","clusterId":"B","werkstueckRef":"B.9","stufe":1,"question":"Drei Szenen: Jemand erkennt in einer Wolke ein Tiergesicht. Jemand setzt nach fünfmal Schwarz beim Roulette auf Rot, weil „jetzt Rot dran ist“. Jemand deutet eine zufällige Häufung von Krankheitsfällen in einer Stadt als Zeichen einer Ursache, obwohl die Verteilung statistisch normal ist. Was haben die drei Szenen gemeinsam?","options":["In allen dreien sieht jemand im bloßen Zufall eine Ordnung, die es dort nicht gibt: im Gesicht, in der Serie, in der Häufung.","In allen dreien wird ein bloßer Zusammenhang als Ursache und Wirkung gedeutet: Gesicht, Serie und Häufung haben angeblich einen Grund.","In allen dreien beachtet jemand nur die Treffer, die zu seiner Erwartung passen, und übersieht Gegenbeispiele: Gesicht, Rot, Krankheitsfälle.","In allen dreien wird dem Zufall eine Absicht unterstellt, als steuere jemand die Wolke, die Roulette-Serie und die Krankheitsfälle."],"correctIndex":0,"explanation":"Wolke, Roulette-Serie und Krankheitshäufung haben eine gemeinsame Wurzel: Das Gehirn sucht Ordnung und findet sie auch im reinen Zufall. Im ersten Fall ist es ein vermeintliches Gesicht, im zweiten eine scheinbare Gesetzmäßigkeit, nach der die nächste Runde die Serie ausgleichen müsse, obwohl jede Drehung unabhängig von den vorigen ist, im dritten eine zufällige Ballung, der eine besondere Ursache zugeschrieben wird. Die Neigung, Muster zu sehen, wo nur Rauschen ist, heißt Apophenie; der Roulette-Fall wird meist eigens als Spielerfehlschluss bezeichnet und beruht vor allem auf einem falschen Bild von unabhängigen Zufallsereignissen. Die Muster sind dabei nicht echt, sondern entstehen im Kopf des Betrachters; Apophenie ist eine allgemein menschliche Tendenz, die auch in der Allgemeinbevölkerung regelmäßig vorkommt (Blain u. a. 2020). Die anderen Deutungen klingen sinnvoll, passen aber nicht zu allen drei Szenen: Eine Ursache wird nur in der dritten Szene gesucht, Wolke und Roulette-Serie handeln nicht von Ursache und Wirkung. Ein Bestätigungsfehler setzt eine vorgefasste Erwartung voraus, von der bei Wolke und Roulette nichts zu sehen ist. Und dass jemand die Ereignisse steuert, nimmt in keiner der drei Szenen jemand an; es geht um Muster, nicht um einen Urheber.","coreRule":"⚡ Das Gehirn sieht Muster, auch wo keine sind: in Wolken, Serien und Ballungen.","beleg":"Werkstück B.9 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Alle drei Szenen zeigen, wie das Gehirn auch im reinen Zufall Ordnung findet, die dort nicht ist. Naheliegend ist, überall Ursache, Erwartung oder Absicht zu vermuten, doch die Muster entstehen im Kopf des Betrachters.","prueffrage":"Wie oft fällt beim Roulette fünfmal hintereinander dieselbe Farbe, wenn man über viele Abende hinweg zählt?","rueckmeldung":[{"option":1,"text":"Bei der Krankheitshäufung wird tatsächlich eine Ursache gesucht. Wolke und Roulette-Serie handeln aber nicht von Ursache und Wirkung, deshalb trifft diese Deutung nur eine der drei Szenen."},{"option":2,"text":"Selektives Beachten von Treffern gibt es im Alltag oft. Dafür bräuchte es aber eine vorgefasste Erwartung, die bei Wolke und Roulette nirgends zu sehen ist; auch beim Roulette liegt der Fehler im Bild vom Zufall selbst."},{"option":3,"text":"Hinter Zufallsserien einen Urheber zu vermuten, kommt vor. In diesen drei Szenen nimmt aber niemand an, dass jemand Wolke, Kugel oder Krankheitsfälle steuert; es geht allein um ein Muster, das gesehen wird."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives. Journal of Abnormal Psychology 129(3) (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives, Verlagsfassung","oeffentlich":false,"doi":"10.1037/abn0000504"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"be8e7f221b495955"}},{"id":"qx-b1-032","clusterId":"B","werkstueckRef":"B.9","stufe":3,"question":"Welche Schlussfolgerung ist aus diesem Studienergebnis am besten gerechtfertigt?","options":["Der Zusammenhang ist mäßig; ob das Mustersehen den Glauben verursacht, lässt sich aus der Korrelation in dieser Studie allein nicht ableiten.","Der Zusammenhang ist mäßig; wahrscheinlich löst der Glaube das Mustersehen aus, weil Gläubige auch Münzfolgen nach Absicht absuchen.","Der Zusammenhang ist mäßig; vermutlich steckt ein dritter Faktor dahinter, sodass das Mustersehen selbst den Glauben gar nicht beeinflusst.","Der Zusammenhang ist mäßig; da beide im Schnitt zusammenhängen, lässt sich bei Einzelnen vom Mustersehen verlässlich auf den Glauben schließen."],"correctIndex":0,"explanation":"Ein Wert von r = 0,3 liegt weit unter 1: Das Mustersehen erklärt nur einen kleinen Teil der Unterschiede im Verschwörungsglauben, aber ganz ohne Zusammenhang ist es auch nicht. Außerdem sagt eine Korrelation nichts über die Richtung: Vielleicht macht Mustersehen anfällig für Verschwörungen, vielleicht prägt ein verschwörungsnahes Weltbild auch den Blick auf Zufallsdaten, oder ein dritter Faktor wirkt auf beides. Tatsächlich zeigte eine Reihe von Studien (van Prooijen u. a. 2018) Zusammenhänge meist um r = 0,2 bis 0,4. In Versuchen, in denen ein verschwörungsnaher Text das Mustersehen verstärkte, wirkten die Bedingungen teils nur über das Mustersehen auf den Glauben; die Autoren schließen daher starke Schlüsse über Ursache und Wirkung aus. Eine frühere Studie fand keinen solchen Zusammenhang; die Autoren erklären das unter anderem damit, dass er sich bei Hochgebildeten womöglich nicht zeigt. Eine Schlagzeile mit „macht anfällig“ behauptet mehr, als die Zahlen tragen.","coreRule":"⚡ Mäßige Korrelation heißt: ein Zusammenhang, aber weder vollständige Erklärung noch bewiesene Ursache.","beleg":"Werkstück B.9 (Anwendung & Relevanz: Bei Verschwörungsmythen); Fn. gl-b-prooijen (van Prooijen u. a. 2018, EJSP 48(3), S. 323–324 und 331–332)","status":"entwurf","scenario":"Eine Forschungsgruppe lässt Versuchspersonen Münzwurf-Folgen betrachten und fragt, ob sie darin Muster erkennen. Außerdem erfasst sie, wie sehr die Personen an Verschwörungstheorien glauben. Ergebnis: Wer in den zufälligen Folgen eher Muster sah, glaubte im Schnitt etwas häufiger an Verschwörungen. Der Zusammenhang liegt bei r = 0,3 (zur Orientierung: r = 0 bedeutet kein Zusammenhang, r = 1 ein perfekter). Eine Schlagzeile dazu lautet: „Mustersehen macht anfällig für Verschwörungsglauben!“","quote":"","quoteLabel":"","kurz":"Bei r = 0,3 gibt es einen mäßigen Zusammenhang, aber eine Korrelation verrät nicht die Richtung: Mustersehen könnte den Glauben fördern, der Glaube den Blick prägen, oder ein dritter Faktor wirkt auf beides. „Macht anfällig“ behauptet zu viel.","prueffrage":"Liegt r = 0,3 näher an 0 oder an 1, und hat die Forschungsgruppe das Mustersehen gezielt verändert oder nur gemessen?","rueckmeldung":[{"option":1,"text":"Dass ein verschwörungsnahes Weltbild den Blick auf Zufallsdaten prägt, ist denkbar und von der Schlagzeile nur umgedreht. Gezeigt ist es hier aber genauso wenig: Beides wurde nur gemessen, und „wahrscheinlich“ trägt die Studie für keine der beiden Richtungen."},{"option":2,"text":"Ein dritter Faktor ist möglich, doch ein mäßiger Zusammenhang belegt ihn nicht. Vor allem schließt er eine Wirkung des Mustersehens nicht aus: Dass es gar keinen Einfluss hat, kann aus diesen Daten nicht folgen."},{"option":3,"text":"Dass der Zusammenhang nicht null ist, stimmt. Er gilt aber für den Durchschnitt der Gruppe; bei r = 0,3 erklärt das Mustersehen nur einen kleinen Teil der Unterschiede, und für einzelne Personen lässt sich daraus kaum etwas verlässlich vorhersagen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots: Illusory pattern perception predicts belief in conspiracies and the supernatural. European Journal of Social Psychology 48(3) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5900972","abruf":"2026-10-12"},{"typ":"doi","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots, Verlagsfassung","oeffentlich":true,"doi":"10.1002/ejsp.2331","seite":"331–332"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"898da56a363a281d"}},{"id":"qx-b1-033","clusterId":"B","werkstueckRef":"B.9","stufe":4,"question":"Was ist der erste sinnvolle Prüfschritt?","scenario":"In einem Viertel deiner Gemeinde sind innerhalb eines Jahres auffällig viele Fälle derselben Erkrankung gemeldet worden. Im Ort wird über eine gemeinsame Ursache spekuliert: Manche vermuten das Trinkwasser, andere den Mobilfunkmast am Ortsrand.","options":["Die Wohnorte der Erkrankten kartieren und prüfen, ob sie näher am Mast oder an den Wasserleitungen liegen, um die Ursache einzugrenzen.","Wasserproben aus dem Viertel nehmen und die Strahlung am Mast messen, um beide Vermutungen im Ort anhand von Grenzwerten zu prüfen.","Prüfen, ob die Fallzahl im Viertel über das zufällig zu Erwartende hinausgeht, bevor man nach Wasser, Mast oder anderen Ursachen sucht.","Die Erkrankten befragen, was sie trinken und wie nah sie dem Mast wohnen, und die häufigste Gemeinsamkeit als Ursache prüfen."],"correctIndex":2,"explanation":"Die Clustering-Illusion beschreibt die Tendenz, in zufälligen Verteilungen „Ballungen“ zu sehen und ihnen eine besondere Bedeutung beizumessen; vermeintliche „Krebscluster“ in einer Stadt erweisen sich bei genauer Prüfung oft als statistisch unauffällig. Der erste Schritt ist deshalb die Frage, ob ein solches Muster auch in rein zufälligen Daten ähnlich wahrscheinlich wäre; erst wenn die Häufung über das zufällig zu Erwartende hinausgeht, lohnt die Suche nach einer Ursache. Die Karte der Wohnorte wirkt anschaulich, legt aber das Ziel erst um die vorhandenen Fälle und findet bei wenigen Punkten fast immer ein Muster, auch bei Zufall. Wasserproben und Strahlungsmessung klingen gründlich, sagen aber nur etwas über Grenzwerte und nichts darüber, ob die Häufung überhaupt mehr als Zufall ist. Die Befragung der Erkrankten wirkt naheliegend, doch gemeinsame Gewohnheiten gibt es in jeder Gruppe, ohne Kontrolle taugt die häufigste nicht als Ursache.","coreRule":"⚡ Bevor du ein Muster erklärst, prüfe, ob der Zufall es auch erzeugen könnte.","quote":"„Das kann doch kein Zufall sein!“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.9 (Kontext & Tiefe: Clustering-Illusion; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Zuerst gilt es zu klären, ob die Häufung überhaupt über das Zufällige hinausgeht. Wir sehen in Zufallsdaten leicht „Ballungen“ und suchen dann nach Gründen, die es vielleicht gar nicht braucht; erst eine echte Auffälligkeit rechtfertigt die Ursachensuche.","prueffrage":"Wie viele andere Viertel, Jahre und Krankheiten hätte man ebenso betrachten können, und wie oft fiele dabei irgendwo eine Häufung auf?","rueckmeldung":[{"option":0,"text":"Eine Karte macht Muster sichtbar, und das ist das Problem: Legt man das Ziel erst um die vorhandenen Fälle, findet man bei wenigen Punkten fast immer eine Nähe zu irgendetwas, auch wenn nur Zufall im Spiel ist."},{"option":1,"text":"Messungen wirken gründlich, vergleichen aber nur mit Grenzwerten. Ob die Häufung überhaupt mehr als Zufall ist, sagen sie nicht, und die Suche nach einer Ursache wäre dann verfrüht."},{"option":3,"text":"Gemeinsame Gewohnheiten gibt es in jeder Gruppe, etwa dasselbe Wasser oder denselben Weg zur Arbeit. Ohne Vergleich mit Gesunden sagt die häufigste Gemeinsamkeit wenig über eine Ursache."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"National Cancer Institute: Cancer Clusters Fact Sheet","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/substances/cancer-clusters-fact-sheet","abruf":"2026-10-12"},{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8c43ceeb52c81765"}},{"id":"qx-b1-034","clusterId":"B","werkstueckRef":"B.10","stufe":1,"question":"Du bekommst eine „persönliche Analyse“ und findest dich fast komplett darin wieder. Welche Frage prüft am besten, ob sie wirklich auf dich zugeschnitten ist?","options":["Würden sich auch viele andere Menschen in genau diesen Sätzen über Anerkennung und Zurückhaltung wiedererkennen?","Trifft jeder einzelne Satz der Analyse, auch der über die ungenutzten Fähigkeiten, wirklich auf mein eigenes Verhalten zu?","Wurde der Fragebogen von ausgebildeten Psychologen entwickelt, und ist seine Auswertung wissenschaftlich geprüft worden?","Wie viele Fragen enthielt der kurze Fragebogen, und reichen so wenige Antworten für eine Aussage über meine Persönlichkeit?"],"correctIndex":0,"explanation":"Die Sätze sind so allgemein, dass sie auf fast jeden zutreffen: Fast jeder ist mal gesellig, mal zurückhaltend, fast jeder ist sich selbst gegenüber manchmal kritisch. Sie schmeicheln dem Selbstbild („ungenutzte Fähigkeiten“) und enthalten nur einen Hauch harmloser Kritik, das wirkt echt. Dazu kommt, dass unser Gedächtnis sofort passende Situationen abruft und die unpassenden übergeht. Dass die Aussage auf dich passt, ist deshalb kein Beweis, dass sie für dich gemacht wurde. Entscheidend ist, ob sie auch auf viele andere passen würde. Im Klassenexperiment von Forer (1948) bewerteten Studierende denselben, aus Horoskopen zusammengestellten Text im Schnitt mit 4,26 von 5 als treffend. Satz für Satz auf dich zu prüfen klingt gründlich, ist aber genau das, was der Effekt täuscht, denn das Gefühl der Passung entsteht auch bei Standardtext. Die Ausbildung der Entwickler und die Prüfung des Fragebogens sind berechtigte Fragen, sagen aber nicht, ob dieser Text für dich geschrieben wurde. Und die Länge des Bogens entscheidet das nicht: Auch ein langer Bogen kann denselben Standardtext liefern.","coreRule":"⚡ Wenn eine „persönliche“ Beschreibung auf fast jeden passt, sagt sie nichts über dich.","beleg":"Werkstück B.10 (Kontext & Tiefe)","status":"entwurf","scenario":"Eine App wertet einen kurzen Fragebogen aus und schreibt dir: „Du hast ein großes Bedürfnis nach Anerkennung. Manchmal bist du gesellig, manchmal zurückhaltend. Du bist dir selbst gegenüber oft kritisch und hast Fähigkeiten, die du noch nicht voll nutzt.“ Du denkst: „Das bin genau ich!“","quote":"","quoteLabel":"","kurz":"Entscheidend ist, ob die Sätze auch auf viele andere passen würden, denn das Gefühl „Das bin ich!“ entsteht auch bei Standardtext. Der naheliegende Fehler ist, die Passung bei sich selbst für den Beweis einer Zuschneidung zu halten.","prueffrage":"Steht in den Sätzen irgendetwas Konkretes, etwa ein Ereignis, ein Name oder eine Vorliebe, das nur in deinem Leben vorkommt?","rueckmeldung":[{"option":1,"text":"Satz für Satz bei sich nachzuschauen wirkt gründlich. Das Gedächtnis liefert aber sofort passende Situationen und übergeht die unpassenden, sodass die Prüfung fast immer „stimmt“ ergibt, auch bei Text, der gar nicht für dich entstanden ist."},{"option":2,"text":"Wie der Fragebogen entwickelt und geprüft wurde, ist eine berechtigte Frage. Sie sagt aber nichts darüber, ob gerade dieser Text für dich geschrieben wurde, denn auch ein sauber entwickelter Bogen kann Standardsätze ausgeben."},{"option":3,"text":"Die Zahl der Fragen sagt etwas über die Aussagekraft eines Tests. Hier entscheidet sie die Sache aber nicht, denn auch ein langer Bogen kann am Ende denselben allgemeinen Text liefern, der auf fast jeden passt."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1722461c68af1c1c"}},{"id":"qx-b1-035","clusterId":"B","werkstueckRef":"B.10","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Freundin am ehesten fehlerhaft?","scenario":"Nach einer Sitzung bei einem Medium sagt eine Freundin begeistert: „Es hat mir gesagt, dass ich mir Sorgen um Geld mache und eine Kiste mit alten Fotos habe, die ich nicht wegwerfen kann. Beides stimmt! Das Medium muss echte Fähigkeiten haben.“ Auf Nachfrage räumt sie ein, dass es auch noch einiges andere gesagt hat, das nicht gepasst hat, daran erinnert sie sich aber kaum noch.","options":["Sie zählt die erinnerten Treffer bei Geldsorgen und Fotokiste und übergeht die Fehlschüsse, obwohl solche Aussagen auf fast jeden passen.","Sie lässt sich von der Sicherheit des Mediums beeindrucken und prüft die Aussagen nicht nach, obwohl Auftreten nichts über Treffsicherheit sagt.","Sie schließt daraus, dass niemand die Treffer bei Geldsorgen und Fotokiste widerlegt hat, auf echte Fähigkeiten, obwohl fehlende Gegenbeweise nichts belegen.","Sie bedenkt nicht, dass sich das Medium vorher über sie informiert haben könnte, obwohl sich Geldsorgen und Fotokiste so erklären ließen."],"correctIndex":0,"explanation":"Die Freundin zählt nur die Treffer und blendet die Fehlschüsse aus. „Du machst dir Sorgen um Geld“ und „Du hast eine Kiste mit alten Fotos, die du nicht wegwerfen kannst“ sind typische Barnum-Aussagen aus dem Cold Reading. Ein Cold Reader feuert viele solche Aussagen ab und beobachtet die Reaktion seines Gegenübers. Die Treffer werden vom Klienten bestätigt und ausgebaut, die Fehlschüsse werden ignoriert. So entsteht der Eindruck großer Treffsicherheit, obwohl nur Allgemeines gesagt wurde.","coreRule":"⚡ Wer nur die Treffer zählt und die Fehlschüsse vergisst, hält Allgemeinplätze für Treffsicherheit.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei Wahrsagern, Hellsehern & Cold Reading)","status":"entwurf","kurz":"Die Freundin zählt nur die erinnerten Treffer und blendet die Fehlschüsse aus. Aussagen wie Geldsorgen oder eine Kiste mit alten Fotos passen auf fast jeden, daher sagen zwei Treffer kaum etwas über echte Fähigkeiten.","prueffrage":"Wie viele andere Aussagen hat das Medium gemacht, und wie viele davon haben tatsächlich gepasst?","rueckmeldung":[{"option":1,"text":"Auftreten sagt tatsächlich nichts über Treffsicherheit. Von der Sicherheit des Mediums ist hier aber nicht die Rede: Die Freundin stützt sich auf zwei Aussagen, die sie als zutreffend erlebt hat. Der Fehler liegt darin, welche Aussagen sie zählt."},{"option":2,"text":"Fehlende Gegenbeweise belegen wirklich nichts. Die Freundin argumentiert aber nicht mit unwiderlegten Behauptungen, sondern mit den Treffern, die sie als richtig erlebt hat. Das Problem liegt darin, dass sie die Fehlschüsse ausblendet."},{"option":3,"text":"Dass sich ein Medium vorab informiert, ist möglich. Im Szenario gibt es dafür aber keinen Hinweis, und die vielen falschen Aussagen sprechen eher für Raten als für Vorwissen. Die Treffer lassen sich auch ohne Recherche erklären."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"83021eb1cc48d59f"}},{"id":"qx-b1-036","clusterId":"B","werkstueckRef":"B.10","stufe":3,"question":"Wie viel von dieser Namensgeschichte darfst du als gesichert ansehen?","options":["Dass Barnum auf ein breites Publikum zielte, gilt als gesichert, weil sein Geschäft gut dokumentiert ist; ob er den Satz sagte, bleibt ohne Quelle offen.","Dass Barnum den Satz sagte, gilt als gesichert, weil ihn der Artikel nennt und Barnum als Schausteller bekannt ist; offen ist nur, bei welchem Anlass.","Dass der Effekt auf Barnum selbst zurückgeht, gilt als gesichert, weil er seinen Namen trägt; offen ist nur, in welchem Jahr er ihn beschrieb.","Nichts an der Namensgeschichte gilt als gesichert, weil der Artikel keine Quelle nennt; offen ist dann auch, ob Barnum überhaupt Schausteller war."],"correctIndex":0,"explanation":"Hier gilt es, zweierlei zu trennen: Barnums Ruf und den angeblichen Wortlaut. Real ist sein Ruf als Schausteller, der sein Programm bewusst auf ein möglichst breites Publikum zuschnitt. Der Satz „Wir haben für jeden etwas dabei“ ist ihm dagegen nur populär zugeschrieben, ohne Beleg. Ein Zitat wird nicht dadurch belegt, dass es oft wiederholt wird oder gut zur Person passt. Auch das noch bekanntere „Alle naslang wird ein Dummkopf geboren“ ist nicht verifiziert. Und der Name „Barnum-Effekt“ stammt nicht von Barnum selbst: Er wurde 1956 vom Psychologen Paul E. Meehl geprägt, der ihn nach Barnums Ruf benannte. Der Effekt geht also nicht auf Barnum zurück, nur sein Name wurde geliehen. Wer einem Zitat oder einer Namensgebung vertrauen will, fragt deshalb nach der Quelle, nicht nach der Bekanntheit.","coreRule":"⚡ Ein oft wiederholtes Zitat ist noch kein belegtes Zitat: Frag nach der Quelle.","beleg":"Werkstück B.10 (Kontext & Tiefe); Fn. gl-b-barnum","status":"entwurf","scenario":"In einem Artikel über Persönlichkeitstests steht: „Der Barnum-Effekt geht auf den Zirkusmann P. T. Barnum zurück, der einst sagte: ‚Wir haben für jeden etwas dabei.‘“ Ein Beleg für den Satz wird nicht genannt, der Artikel verweist nur auf Barnums Ruf als Schausteller.","kurz":"Gesichert ist Barnums Ruf als Schausteller für ein breites Publikum, der Wortlaut dagegen ist nur zugeschrieben und ohne Quelle. Ein Zitat gilt nicht schon deshalb als belegt, weil es oft wiederholt wird oder zur Person passt.","prueffrage":"Wann bekam der Effekt seinen Namen, und lebte Barnum da noch?","rueckmeldung":[{"option":1,"text":"Der Satz passt gut zu einem Schausteller und steht im Artikel, das macht ihn glaubwürdig. Belegt ist der Wortlaut damit aber nicht: Ohne Quelle bleibt auch offen, ob Barnum ihn je gesagt hat, nicht nur der Anlass."},{"option":2,"text":"Der Effekt trägt Barnums Namen, daher liegt ein Ursprung bei ihm nahe. Ein Name beweist aber keinen Ursprung: Den Begriff hat 1956 der Psychologe Paul E. Meehl geprägt und ihn nach Barnums Ruf benannt."},{"option":3,"text":"Skepsis gegenüber dem unbelegten Zitat ist berechtigt. Sie geht hier aber zu weit: Barnums Ruf als Schausteller ist unabhängig davon dokumentiert, und fehlende Quellen für den Satz entwerten das nicht."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Barnum effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/barnum.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Meehl, P. E. (1956): Wanted—a good cook-book. American Psychologist 11(6), 263–272","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"6e805f8e5f643b08"}},{"id":"qx-b1-037","clusterId":"B","werkstueckRef":"B.10","stufe":4,"question":"Was folgt aus dem Treffer für die Frage, ob der Dienst dich persönlich „durchschaut“?","scenario":"Dein Streamingdienst schlägt dir einen Song vor, der genau zu deiner Stimmung passt, und du denkst: „Der kennt mich besser als meine Freunde.“ Du weißt, dass der Dienst seine Vorschläge aus den Hörgewohnheiten sehr vieler Nutzer ableitet.","options":["Er zeigt nichts Sicheres, denn ein auf breite Muster gestützter Vorschlag kann sich persönlich anfühlen, ohne dich persönlich zu erfassen.","Er spricht dafür, dass der Dienst dich gut kennt, denn ein Song, der so genau zu deiner Stimmung passt, entsteht aus den Gewohnheiten vieler Nutzer kaum.","Er spricht dafür, dass der Dienst dich eher schlecht kennt, denn ein Vorschlag aus den Daten vieler Nutzer erfasst deine Stimmung nicht, der Treffer war wohl Zufall.","Er spricht dafür, dass der Dienst dich möglichst lange binden will, denn ein Song zur richtigen Stimmung hält Nutzer beim Angebot."],"correctIndex":0,"explanation":"Das gute Gefühl allein sagt wenig darüber, wie der Vorschlag zustande kam. Algorithmen stützen sich oft auf breite statistische Muster, die auf Millionen von Menschen zutreffen, sich für den Einzelnen aber ganz persönlich anfühlen. Das ist ein digitaler Barnum-Effekt: Bereits 1948 gab der Psychologe Bertram Forer seinen Studenten allen denselben, aus Horoskopen zusammengestückelten Text. Sie bewerteten ihn im Mittel mit 4,26 auf einer Skala von 0 bis 5, obwohl er für niemanden maßgeschneidert war. Die gefühlte Treffsicherheit ist deshalb kein Beleg für tiefes Verstehen. Der Schluss vom Treffer auf gutes Kennen geht vom Gefühl auf die Ursache, obwohl breite Muster einen solchen Treffer ebenso erzeugen können. Auch das Gegenteil, der Dienst kenne dich schlecht und der Treffer sei Zufall, folgt aus einem einzelnen Treffer nicht. Dass Empfehlungen Nutzer an den Dienst binden sollen, mag stimmen, beantwortet aber nicht, ob der Dienst dich persönlich erfasst.","coreRule":"⚡ Gefühlte Treffsicherheit ist kein Beweis für echtes Verstehen.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei algorithmischer Personalisierung)","status":"entwurf","kurz":"Der gute Treffer sagt wenig darüber, wie der Vorschlag entstand: Breite Muster aus vielen Nutzerdaten können sich sehr persönlich anfühlen, ohne dich persönlich zu erfassen. Vom Gefühl auf tiefes Kennen zu schließen, ist der Fehler.","prueffrage":"Woraus leitet der Dienst seine Vorschläge ab, und was davon betrifft nur dich?","rueckmeldung":[{"option":1,"text":"Dass ein passender Song nach persönlichem Wissen aussieht, liegt nahe. Die Annahme, so ein Treffer entstehe aus den Gewohnheiten vieler Nutzer kaum, stimmt aber nicht: Breite Muster können genau das erzeugen."},{"option":2,"text":"Wer dem Treffer misstraut, liegt nicht ganz falsch. Doch aus einem einzelnen Treffer folgt auch das Gegenteil nicht: Muster vieler Nutzer können durchaus passen, ohne dass es bloßer Zufall war."},{"option":3,"text":"Dass Empfehlungen Nutzer binden sollen, mag stimmen. Das beantwortet aber nicht die gestellte Frage: Aus der Absicht des Dienstes lässt sich nicht ablesen, wie gut er dich persönlich erfasst."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1f7a1c5f60c1bf17"}},{"id":"qx-b1-038","clusterId":"B","werkstueckRef":"B.11","stufe":1,"question":"Welche Schlussfolgerung ist aus der Beobachtung gerechtfertigt?","scenario":"Du siehst nachts ein Licht, das schnell fliegt, plötzlich stehen bleibt und abrupt die Richtung ändert. Dein Freund sagt: „Ich kenne kein Flugzeug und keinen Satelliten, die das können – also muss es ein außerirdisches Raumschiff sein!“","options":["Es war ein außerirdisches Raumschiff, denn kein bekanntes Flugzeug und kein Satellit kann sich so bewegen.","Es war ein Flugzeug oder eine Drohne, denn die meisten gemeldeten Himmelslichter erweisen sich als gewöhnliche Objekte.","Es war eine optische Täuschung, denn ein Licht ohne Bezugspunkte am Nachthimmel scheint sich oft sprunghaft zu bewegen.","Es war ein unidentifiziertes Flugobjekt im wörtlichen Sinn, denn ich weiß schlicht nicht, was es war."],"correctIndex":3,"explanation":"Die Beobachtung zeigt nur, dass dein Freund keine Erklärung kennt. Das ist eine Aussage über den Stand seines Wissens, nicht über die Ursache des Lichts. Aus „mir fällt keine natürliche Erklärung ein“ folgt nicht, dass die Lieblingserklärung stimmt, und ebenso wenig, dass das Phänomen nicht stattgefunden hat oder doch ein gewöhnliches Objekt war. Eine Wissenslücke ist kein Beweis für irgendeine bestimmte Erklärung. Gerechtfertigt ist nur die ehrliche Feststellung, dass das Licht unidentifiziert bleibt. Sinnvoll ist dann, die Lücke zu untersuchen, statt sie mit einer bevorzugten Erklärung zu füllen. Dass die meisten gemeldeten Lichter gewöhnlich sind, spricht für eine Vermutung, entscheidet diesen Einzelfall aber nicht. Eine optische Täuschung ist als Möglichkeit denkbar, aber hier nicht gezeigt. Und was ein Mensch nicht kennt, sagt nichts darüber, was möglich ist.","coreRule":"⚡ „Ich weiß es nicht“ ist eine vollständige und ehrliche Antwort: Eine Wissenslücke beweist keine bestimmte Erklärung.","beleg":"Werkstück B.11 (Das Licht am Nachthimmel; Kontext & Tiefe)","status":"entwurf","kurz":"Aus „mir fällt keine Erklärung ein“ folgt keine bestimmte Erklärung, denn das beschreibt nur das Wissen deines Freundes, nicht das Licht. Ehrlich gerechtfertigt ist nur: Es bleibt unidentifiziert, und diese Lücke lässt sich untersuchen.","prueffrage":"Was lässt sich bei einem Licht am Nachthimmel mit bloßem Auge über seine Entfernung, Größe und Geschwindigkeit sicher sagen?","rueckmeldung":[{"option":0,"text":"Dass deinem Freund nichts Bekanntes einfällt, stimmt vermutlich. Es beschreibt aber nur seinen Kenntnisstand, nicht das Licht. Die Lücke in seinem Wissen belegt keine Ursache, schon gar keine so besondere."},{"option":1,"text":"Dass die meisten gemeldeten Himmelslichter gewöhnlich sind, spricht für eine Vermutung. Für diesen einen Fall entscheidet es aber nichts. Auch hier würde die Lücke mit einer bevorzugten Erklärung gefüllt, nur in die andere Richtung."},{"option":2,"text":"Ohne Bezugspunkte scheinen Lichter am Nachthimmel tatsächlich oft zu springen, als Möglichkeit ist das denkbar. Im Szenario zeigt aber nichts, dass hier eine Täuschung vorlag; als Feststellung wäre es wieder eine ungeprüfte Lückenfüllung."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"164445a31f34dd88"}},{"id":"qx-b1-039","clusterId":"B","werkstueckRef":"B.11","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Dein Onkel sagt: „Es gibt keinen einzigen Beweis, dass es Leben auf anderen Planeten gibt – also gibt es keins.“","options":["Er folgert aus dem fehlenden Beweis für Leben, dass es keins gibt, obwohl ein fehlender Beweis allein noch nicht zeigt, dass etwas nicht existiert.","Er setzt schon voraus, dass es kein Leben gibt, und nimmt das als Beleg dafür, obwohl eine Behauptung nicht ihr eigener Beleg sein darf.","Er widerlegt die Behauptung, Leben auf anderen Planeten sei bewiesen, obwohl niemand sie aufgestellt hat und sein Argument deshalb ins Leere geht.","Er schließt aus eigener Erfahrung, nie Außerirdischen begegnet zu sein, auf alle Planeten, obwohl persönliche Erfahrung nur einen Ausschnitt zeigt."],"correctIndex":0,"explanation":"Der Onkel schließt von „nicht bewiesen“ auf „falsch“. Das ist das Argument aus Unwissenheit: Ein fehlender Beweis allein zeigt nicht, dass etwas nicht existiert, sondern zunächst nur, dass wir es nicht wissen. Gewicht bekommt das Fehlen eines Belegs erst, wenn gründlich dort gesucht wurde, wo ein Beleg zu erwarten wäre; über die allermeisten Planeten wissen wir dafür noch viel zu wenig. Der Fehler liegt also im Übergang von der Wissenslücke zur festen Aussage. Zulässig wäre: „Ich kenne keinen Beleg und halte die Frage deshalb für offen.“ Die anderen Vorwürfe klingen sinnvoll, passen aber nicht: Sein Grund, der fehlende Beweis, ist nicht schon die Behauptung selbst, es liegt also kein Zirkelschluss vor. Er bekämpft keine Behauptung, die niemand aufgestellt hat, sondern vertritt seine eigene. Und er beruft sich nicht auf eigene Erfahrung, sondern auf das Fehlen von Beweisen.","coreRule":"⚡ Kein Beweis dafür heißt nicht „falsch“, kein Beweis dagegen nicht „wahr“.","beleg":"Werkstück B.11 (Kontext & Tiefe: Negative Form)","status":"entwurf","kurz":"Aus „nicht bewiesen“ folgt noch nicht „falsch“: Ein fehlender Beweis zeigt zunächst nur, dass wir es nicht wissen. Der Fehler ist, die Wissenslücke wie eine Widerlegung zu behandeln, obwohl kaum ein Planet untersucht ist.","prueffrage":"Was genau wurde bisher untersucht, und was würde man finden, wenn es dort doch etwas gäbe?","rueckmeldung":[{"option":1,"text":"Dass eine Behauptung nicht ihr eigener Beleg sein darf, stimmt als Regel. Hier ist der Grund aber ein anderer Satz als die These: „Kein Beweis bekannt“ ist nicht dasselbe wie „es gibt kein Leben“. Ein Zirkel liegt nicht vor."},{"option":2,"text":"Ein solches Scheinargument gibt es, es passt hier aber nicht. Der Onkel widerlegt keine fremde Behauptung, sondern vertritt seine eigene These. Im Szenario hat niemand gesagt, Leben auf anderen Planeten sei bewiesen."},{"option":3,"text":"Der Schluss vom Einzelnen aufs Ganze wäre ein eigener Fehler, den der Onkel hier nicht macht. Er verweist nicht auf eigene Begegnungen, sondern darauf, dass es überhaupt keinen Beweis gibt. Dass daraus nichts folgt, ist das Problem."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0420c8486af15502"}},{"id":"qx-b1-040","clusterId":"B","werkstueckRef":"B.11","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"In einer Debatte heißt es: „Die Wissenschaft kann bisher nicht bis ins letzte Detail erklären, wie das erste Leben aus unbelebter Materie entstand. Also muss es erschaffen worden sein.“","options":["Der Schluss ist fehlerhaft, weil er von einer offenen Einzelfrage auf das Versagen der ganzen Wissenschaft schließt; ein Teilbefund trägt keine Gesamtaussage.","Der Schluss ist fehlerhaft, weil er die Erschaffung des ersten Lebens schon voraussetzt; er nimmt damit als gegeben an, was erst zu zeigen wäre.","Der Schluss ist fehlerhaft, weil aus einer Lücke im Wissen über das erste Leben keine bestimmte Erklärung folgt; sie zeigt nur, dass etwas noch offen ist.","Der Schluss ist fehlerhaft, weil er die Forschung zum ersten Leben auf ihre ungelösten Einzelheiten verkürzt; ein verzerrtes Bild lässt sich leichter ablehnen."],"correctIndex":2,"explanation":"Eine Wissenslücke ist selbst kein Beleg für eine bestimmte Erklärung. Aus „Das wissen wir noch nicht“ folgt nicht „Also gilt meine bevorzugte Antwort“. Dieser Fehlschluss heißt Argument aus Unwissenheit, in religiösen Zusammenhängen auch „Gott der Lücken“: Eine aktuelle Lücke im wissenschaftlichen Verständnis wird als Beweis für die eigene Position ausgegeben. Dabei wird die Lücke willkürlich mit einer bevorzugten, unbewiesenen Erklärung gefüllt. Die ehrliche Antwort auf eine Lücke lautet: „Das wissen wir (noch) nicht.“ Eine Verallgemeinerung wäre sinnvoll zu rügen, doch hier wird aus der Lücke nicht auf das Versagen der Wissenschaft, sondern auf eine bestimmte Erklärung geschlossen. Ein Zirkelschluss klingt naheliegend, weil die Erschaffung das Ergebnis ist, aber die Begründung ist allein die Lücke und nicht die Erschaffung selbst. Ein Strohmann läge vor, wenn die Forschung verzerrt dargestellt würde; der Stand wird hier jedoch zutreffend wiedergegeben.","coreRule":"⚡ Eine Wissenslücke ist eine Frage, keine Antwort.","beleg":"Werkstück B.11 (Anwendung & Relevanz: Im Kreationismus & „Intelligent Design“; Der Kipppunkt)","status":"entwurf","kurz":"Eine Wissenslücke ist kein Beleg für eine bestimmte Erklärung. Aus „Das wissen wir noch nicht“ folgt nicht „Also gilt meine Antwort“. Die Lücke wird einfach mit der bevorzugten Erklärung gefüllt, ehrlich wäre nur: „Das wissen wir (noch) nicht.“","prueffrage":"Welche Beobachtung nennt die Aussage, die für sich genommen auf eine Erschaffung hindeutet?","rueckmeldung":[{"option":0,"text":"Eine Verallgemeinerung wäre tatsächlich zu rügen, hier aber nicht der Fall: Es geht nur um eine einzelne offene Frage. Der Fehler liegt woanders, nämlich darin, dass aus dieser Lücke eine bestimmte Erklärung abgeleitet wird."},{"option":1,"text":"Dass die Erschaffung das Ergebnis des Schlusses ist, lässt an einen Zirkel denken. Begründet wird sie aber allein mit der Wissenslücke, nicht mit sich selbst. Das Problem ist die Lücke als Beweis, nicht eine vorausgesetzte Schlussfolgerung."},{"option":3,"text":"Ein verzerrtes Bild der Forschung wäre ein Strohmann, doch hier trifft das nicht zu: Dass Einzelheiten noch offen sind, wird zutreffend wiedergegeben. Fehlerhaft ist erst der Schritt von dieser Lücke zur behaupteten Erschaffung."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a9858a48f18a1e15"}},{"id":"qx-b1-041","clusterId":"B","werkstueckRef":"B.12","stufe":1,"question":"Welcher Denkfehler steckt in der Schlussfolgerung der Zuschauerin, und woran liegt er?","scenario":"Ein Nachrichtenmagazin kündigt eine Sondersendung an: „Die Form der Erde: Gibt es eine Kontroverse?“ Eine Astrophysikerin und ein YouTuber, der die Erde für eine Scheibe hält, bekommen exakt gleich viel Redezeit. Der Moderator schließt: „Eine faszinierende Diskussion mit vielen offenen Fragen. Bilden Sie sich Ihre eigene Meinung.“ Eine Zuschauerin sagt danach: „Dann scheint sich die Wissenschaft ja nicht einig zu sein.“","options":["Sie schließt von der gleichen Redezeit zweier Gäste auf eine gleich starke Beweislage, obwohl die Sendung nichts über die Verteilung der Expertenmeinungen sagt.","Sie schließt von der Fachrolle der Astrophysikerin auf die Richtigkeit ihrer Aussagen, obwohl auch Fachleute sich irren können und ein Titel allein nichts beweist.","Sie schließt von der Zahl der Anhänger des YouTubers auf die Richtigkeit seiner Behauptung, obwohl Beliebtheit nichts darüber sagt, ob etwas stimmt.","Sie liest nur die Aussagen heraus, die zu ihrer bisherigen Meinung passen, obwohl eine faire Prüfung auch Gegenhinweise berücksichtigen muss."],"correctIndex":0,"explanation":"Wie viel Bühne und Redezeit jemand bekommt, sagt nichts darüber, wie viele Fachleute seine Position teilen oder wie gut sie belegt ist. Bei der Form der Erde stützen Satellitendaten, Flugrouten, Erdkrümmung und astronomische Beobachtungen eine Seite erdrückend, die andere hat dem nichts Vergleichbares entgegenzusetzen. Die Sendung formt trotzdem den Eindruck einer 50/50-Kontroverse unter Experten, und die Zuschauerin übernimmt ihn. Bei politischen Meinungsfragen ist es sinnvoll, beide Seiten anzuhören. Bei Fragen mit erdrückender Beweislage verzerrt dasselbe Prinzip die Realität. Die richtige Prüffrage lautet daher nicht „Wurden beide gehört?“, sondern „Wie verteilen sich Belege und Fachmeinungen tatsächlich?“. Dass der Moderator beide Positionen als gleichwertig behandelt und die Beweislage nicht einordnet, überlässt die Wahrheitsfindung dem Publikum und erzeugt den falschen Eindruck einer Kontroverse.","coreRule":"⚡ Gleiche Redezeit ist keine gleiche Beweislage.","beleg":"Werkstück B.12 (Die Debatte über die Form der Erde; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Gleiche Redezeit zeigt nur, wie die Sendung gebaut ist, nicht, wie sich Belege und Fachmeinungen verteilen. Aus der Bühne auf eine echte Kontroverse unter Fachleuten zu schließen, ist der Fehler; hier stützt die Beweislage eine Seite erdrückend.","prueffrage":"Was weißt du über die Form der Erde aus anderen Quellen, etwa von Satellitenbildern oder Flugrouten, und passt das zu einer offenen Streitfrage?","rueckmeldung":[{"option":1,"text":"Allein auf einen Titel zu bauen, wäre in der Tat ein Fehlschluss. Die Zuschauerin tut das aber nicht: Sie beruft sich nirgends auf die Astrophysikerin, sondern schließt aus dem Eindruck, den die Sendung erzeugt."},{"option":2,"text":"Dass Beliebtheit nichts über Wahrheit sagt, stimmt allgemein. Im Szenario spielt die Zahl der Anhänger des YouTubers aber keine Rolle; der Schluss entsteht aus der gleichen Bühne beider Gäste."},{"option":3,"text":"Sich nur Passendes herauszupicken, ist ein bekannter Fehler. Hier steht aber nichts über eine vorgefasste Meinung der Zuschauerin; sie übernimmt den Eindruck, den die Sendung selbst vermittelt."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016, Journal of Experimental Psychology: Applied)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"40f58977740fa85b"}},{"id":"qx-b1-042","clusterId":"B","werkstueckRef":"B.12","stufe":2,"question":"Welche Frage deckt am besten auf, dass diese Gleichbehandlung das Bild verzerren könnte?","scenario":"Du siehst eine Talkrunde zu einem Gesundheitsthema: links eine Epidemiologin, die den breiten Befund der Fachliteratur vertritt, rechts ein Gast mit eigener Theorie, die kaum ein Fachmensch teilt. Beide bekommen gleich viel Redezeit, und der Moderator schließt mit: „Eine spannende Kontroverse, bilden Sie sich Ihre eigene Meinung.“","options":["Haben die Gäste ein finanzielles Interesse am Ausgang der Debatte, das ihre Aussagen färben könnte?","Entspricht die Verteilung der Gäste der tatsächlichen Verteilung der Expertenmeinungen im Fachgebiet?","Wurden beiden Gästen dieselben Fragen gestellt, und durften sie auf die Einwände des anderen antworten?","Lassen sich die Quellen, auf die sich beide Gäste berufen, für Zuschauer öffentlich einsehen und überprüfen?"],"correctIndex":1,"explanation":"Ob eine Debatte das Bild der Wirklichkeit wiedergibt, hängt nicht davon ab, wie fair die Bühne gebaut ist, sondern davon, wie die Beweislage tatsächlich verteilt ist. Wenn nahezu alle Fachleute eine Position teilen und nur eine Handvoll die andere, erzeugen zwei gleich große Redeanteile beim Publikum den falschen Eindruck eines 50/50-Streits unter Experten. Wer das prüfen will, vergleicht die Verteilung der Gäste mit der Verteilung der Expertenmeinungen im Feld.","coreRule":"⚡ Frag nicht nach der Fairness der Bühne, sondern nach dem Gewicht der Belege.","beleg":"Werkstück B.12 (Das Anti-Denkmuster; Red Flags)","status":"entwurf","kurz":"Entscheidend ist, wie viele Fachleute hinter welcher Position stehen. Gleiche Redezeit täuscht bei einer Handvoll Abweichler einen 50/50-Streit unter Experten vor, obwohl die Bühne fair wirkt.","prueffrage":"Woran hättest du als Zuschauer in der Sendung erkennen können, dass der zweite Gast mit seiner Theorie in der Fachwelt fast allein steht?","rueckmeldung":[{"option":0,"text":"Ein Eigeninteresse kann Aussagen färben, und das zu prüfen ist sinnvoll. Es betrifft aber nur, wie glaubwürdig ein einzelner Gast ist, nicht, wie viele Fachleute welche Position teilen."},{"option":2,"text":"Gleiche Fragen und Erwiderungsrechte sprechen für einen fairen Ablauf. Gerade dieser faire Rahmen kann aber den Eindruck eines Gleichstands noch verstärken, statt die Verzerrung aufzudecken."},{"option":3,"text":"Nachprüfbare Quellen sind wünschenswert. Sie zeigen aber nicht, welches Gewicht eine Position im Fach hat: Auch eine Außenseitertheorie kann offen belegt sein."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"85be3e2728feacfb"}},{"id":"qx-b1-043","clusterId":"B","werkstueckRef":"B.12","stufe":3,"question":"Ein Nachrichtenmagazin plant zwei Beiträge. Beitrag 1: Ist die Erde eine Kugel? Beitrag 2: Bei der Behandlung einer seltenen Krankheit gehen zwei Forschungsgruppen mit jeweils guter Datenlage von unterschiedlichen Wirkmechanismen aus, und die Fachwelt ist gespalten. Wie sollte die Redaktion die beiden Beiträge anlegen?","options":["In beiden Beiträgen sollten beide Gäste gleich lang reden, weil gleiche Redezeit das Kennzeichen fairer Berichterstattung ist.","Nur im ersten Beitrag sollten beide Seiten ausführlich zu Wort kommen, weil nur dort eine verbreitete Fehlvorstellung auszuräumen ist.","Nur im zweiten Beitrag sollten beide Seiten ausführlich zu Wort kommen, weil nur dort die Fachwelt wirklich gespalten ist.","Im zweiten Beitrag sollte nur eine Forschungsgruppe auftreten, weil Zuschauer bei einer Krankheit klare Auskunft statt Streit brauchen."],"correctIndex":2,"explanation":"Zwei Seiten gleichwertig darzustellen ist nur sinnvoll, wenn die Frage wirklich offen ist. Bei der seltenen Krankheit stützen beide Positionen belastbare Daten, und die Fachwelt ist tatsächlich gespalten; hier bildet eine Debatte die Lage korrekt ab. Bei der Kugelgestalt der Erde gibt es keine legitime wissenschaftliche Kontroverse mehr; die Frage gilt als längst entschiedene Kernfrage der Wissenschaft. Eine Debatte mit gleicher Redezeit erzeugt beim Publikum den falschen Eindruck einer 50/50-Kontroverse unter Experten und verzerrt die Realität. Gleiche Redezeit ist kein Maß für Fairness: Entscheidend ist, ob die Verteilung der Positionen im Beitrag der tatsächlichen Verteilung der Expertenmeinungen und der Beweislage entspricht. Die anderen Gedanken klingen vertretbar, scheitern aber an der Lage: Gleiche Redezeit in beiden Beiträgen wirkt fair, täuscht beim Beitrag zur Erde aber einen Streit unter Fachleuten vor. Eine Fehlvorstellung im Gespräch zu entkräften wirkt aufklärerisch, ließe aber im zweiten Beitrag die tatsächlich gespaltene Fachwelt ohne Stimme. Nur eine Forschungsgruppe auftreten zu lassen wirkt übersichtlich, verschweigt aber, dass beide Gruppen eine gute Datenlage haben.","coreRule":"⚡ Zwei Seiten gehören dorthin, wo die Frage wirklich offen ist. Gewichte Positionen nach Beweislage, nicht nach Redezeit.","beleg":"Werkstück B.12 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"Die Redaktion möchte „fair und ausgewogen“ berichten und überlegt, in beiden Beiträgen jeweils zwei Gäste mit gleicher Redezeit auftreten zu lassen.","kurz":"Zwei Positionen gleichwertig zu zeigen, ist nur dort sinnvoll, wo die Fachwelt wirklich gespalten ist, also beim Beitrag zur Krankheit. Gleiche Redezeit allein macht nicht fair: Beim Thema Erde würde sie einen Expertenstreit vortäuschen, den es nicht gibt.","prueffrage":"Was unterscheidet die Datenlage hinter den Positionen beim ersten Thema von der beim zweiten?","rueckmeldung":[{"option":0,"text":"Für den zweiten Beitrag passt das, denn dort steht tatsächlich Position gegen Position. Beim Thema Erde würde gleiche Redezeit aber einen Streit unter Fachleuten vortäuschen, den es nicht gibt. Fairness misst sich am Gewicht der Belege, nicht an der Stoppuhr."},{"option":1,"text":"Fehlvorstellungen zu klären ist ein gutes Ziel, doch dafür braucht es keine gleichberechtigte Debatte, die eine offene Frage nahelegt. Und der zweite Beitrag, in dem die Fachwelt wirklich gespalten ist, bliebe ohne beide Stimmen."},{"option":3,"text":"Klare Auskunft ist ein berechtigter Wunsch, aber hier würde sie nur durch Weglassen entstehen. Beide Gruppen haben eine gute Datenlage, die Fachwelt ist gespalten. Zeigt man nur eine Gruppe, wirkt die Lage entschiedener, als sie ist."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2ab872e4bc04852f"}},{"id":"qx-b1-044","clusterId":"B","werkstueckRef":"B.12","stufe":4,"question":"Welche Wirkung hat dieses Format auf Zuschauer, die das Thema nicht aus eigener Sachkenntnis beurteilen können?","scenario":"Ein Fernsehsender plant eine Sondersendung zum Klimawandel. Im Studio sitzen zwei Gäste: eine Klimaforscherin, deren Aussagen dem Stand der Fachliteratur entsprechen, und ein Redner, der die menschengemachte Erwärmung bestreitet und mit seiner Haltung unter Fachleuten kaum Rückhalt hat. Der Moderator gibt beiden exakt gleich viel Redezeit und schließt mit den Worten: „Eine spannende Debatte mit offenem Ausgang. Bilden Sie sich Ihre eigene Meinung.“","options":["Sie gewinnen den Eindruck, unter Fachleuten sei die Frage noch offen, obwohl die Fachwelt weitgehend einig ist.","Sie erkennen an den Aussagen der Forscherin, dass diese dem Stand der Fachliteratur folgen, und halten sie für glaubwürdiger.","Sie deuten das offene Schlusswort so, dass der Redner die Forscherin widerlegt hat, und halten die Erwärmung für widerlegt.","Sie prüfen die Aussagen beider Gäste anhand der Fachliteratur nach, wie es ihnen der Moderator nahelegt, und urteilen dann selbst."],"correctIndex":0,"explanation":"Wer nicht selbst beurteilen kann, wie verbreitet eine Position unter Fachleuten ist, schließt aus der Bühne auf das Gewicht: Gleiche Redezeit und ein offenes Schlusswort legen nahe, dass sich zwei etwa gleich starke Lager gegenüberstehen. Tatsächlich bejahen über 99 % der einschlägigen Fachartikel eine menschengemachte Erwärmung; die Beweislage ist also keineswegs 50 zu 50. Gleiche Bühnenzeit bildet nicht die Beweislage ab, sondern verzerrt sie (falsche Ausgewogenheit). Eine bloße Gegenüberstellung ersetzt außerdem keine Einordnung: Die Bewertung der Beweiskraft wird dem unvorbereiteten Zuschauer überlassen.","coreRule":"⚡ Eine 50:50-Bühne kann eine 99:1-Fachwelt als Streit erscheinen lassen.","beleg":"Werkstück B.12 (Anwendung & Relevanz: Bei der Leugnung des Klimawandels; Verweis auf Band VI)","status":"entwurf","kurz":"Gleiche Redezeit und ein offenes Schlusswort wirken wie ein Gleichstand zweier Lager. Wer nicht selbst urteilen kann, schließt von der Bühne auf die Beweislage, obwohl die Fachwelt weitgehend einig ist: falsche Ausgewogenheit.","prueffrage":"Woran könnte jemand ohne Sachkenntnis in dieser Sendung erkennen, welche der beiden Positionen in der Fachwelt Rückhalt hat?","rueckmeldung":[{"option":1,"text":"Dass die Forscherin dem Stand der Fachliteratur folgt, stimmt, nur sieht man es ihren Aussagen nicht an. Wer das Thema nicht selbst beurteilen kann, erkennt nicht, welche Position zur Fachliteratur passt."},{"option":2,"text":"Ein Sieg des Redners legt sich nicht nahe: Das offene Schlusswort spricht eher gegen den Eindruck, die Forscherin habe verloren. Die Wirkung liegt anderswo, nämlich im Bild eines Gleichstands, nicht in einer Widerlegung."},{"option":3,"text":"Der Moderator fordert nur zur eigenen Meinungsbildung auf, einen Hinweis auf Nachprüfen gibt er nicht. Selbst dann würden Zuschauer ohne Sachkenntnis die Fachliteratur kaum beurteilen können. Die Einordnung bleibt ihnen überlassen."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Cornell Chronicle (2021): More than 99.9% of studies agree: Humans caused climate change","oeffentlich":true,"url":"https://news.cornell.edu/stories/2021/10/more-999-studies-agree-humans-caused-climate-change","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lynas, M.; Houlton, B. Z.; Perry, S. (2021): Greater than 99% Consensus on Human Caused Climate Change in the Peer-Reviewed Scientific Literature. Environmental Research Letters 16(11), 114005","oeffentlich":true,"doi":"10.1088/1748-9326/ac2966"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f1a90444c232dccc"}},{"id":"qx-b1-045","clusterId":"B","werkstueckRef":"B.13","stufe":1,"question":"Welche Rückfrage trifft den Kern des Fehlers in diesem Gespräch?","scenario":"Im Chat schreibt eine Kollegin: „Wie soll ein winziger Anteil eines unsichtbaren Gases wie CO2 das ganze Klima der Erde verändern? Das kann ich mir beim besten Willen nicht vorstellen, also ist die Sache Unsinn.“ Du willst ihr antworten.","options":["Beweist dein fehlendes Vorstellungsvermögen etwas über die Sache, oder zeigt es nur, wo dein Wissen gerade endet?","Verwechselst du das gemeinsame Ansteigen von CO2 und Wärme mit einer Ursache, oder liegt ein Wirkzusammenhang vor?","Beruft sich deine Aussage über das unsichtbare Gas auf eine Quelle, die veraltet sein könnte, oder gibt es neuere Daten?","Stützt sich dein Schluss auf einen einzelnen Fall, in dem der winzige Anteil nichts bewirkte, oder auf mehrere?"],"correctIndex":0,"explanation":"Die Kollegin schließt von „Ich kann mir nicht vorstellen, wie X wahr sein könnte“ auf „X ist nicht wahr“. Das ist ein Fehlschluss, denn die Grenzen der eigenen Vorstellungskraft sind kein Beleg gegen eine Behauptung. Unsere Intuition ist für Alltagsdinge in mittlerer Größe und bei mittlerer Geschwindigkeit geeignet. Bei Rückkopplungen im Klimasystem, in der Quantenphysik oder bei der Entwicklung des Auges versagt sie regelmäßig, und die Wirklichkeit hat keine Pflicht, unserem Bauchgefühl zu entsprechen. Auch die Verwandlung einer Raupe in einen Schmetterling, bei der in der Puppe große Teile des Körpers abgebaut und neu aufgebaut werden, klingt unvorstellbar und ist trotzdem real. Die richtige Rückfrage trennt deshalb sauber zwischen dem eigenen Unglauben und der Frage, was für oder gegen die Behauptung spricht. Die anderen Rückfragen klingen berechtigt, scheitern aber am Chat: Die Kollegin behauptet keinen gemeinsamen Anstieg zweier Größen, also auch keinen Zusammenhang, den man mit einer Ursache verwechseln könnte. Sie nennt keine Quelle, deren Alter sich prüfen ließe. Und sie nennt keinen Einzelfall, sondern allein ihr Vorstellungsvermögen.","coreRule":"⚡ Was ich mir nicht vorstellen kann, ist deshalb nicht unmöglich.","quote":"Ich kann es mir nicht vorstellen, also kann es nicht wahr sein.","quoteLabel":"Merksatz:","beleg":"Werkstück B.13 (Die unmögliche Raupe; Kernidee; Kontext & Tiefe; Anwendung & Relevanz)","status":"entwurf","kurz":"Aus „Ich kann mir das nicht vorstellen“ folgt nicht „Das stimmt nicht“: Die Grenzen der eigenen Vorstellung zeigen, wo das Wissen endet, und sagen nichts über die Sache. Bei Rückkopplungen und Ähnlichem versagt die Intuition regelmäßig.","prueffrage":"Welche Gründe nennt die Kollegin dafür, dass die Sache Unsinn ist?","rueckmeldung":[{"option":1,"text":"Die Verwechslung von gemeinsamem Auftreten und Ursache ist ein häufiger Fehler. Im Chat taucht aber kein solcher gemeinsamer Anstieg auf, den man falsch deuten könnte. Die Kollegin stützt sich allein darauf, dass sie es sich nicht vorstellen kann."},{"option":2,"text":"Das Alter einer Quelle zu hinterfragen ist ein guter Reflex. Hier gibt es aber gar keine Quelle, die veraltet sein könnte: Die Kollegin nennt keine, sondern verweist auf ihr eigenes Vorstellungsvermögen. Die Rückfrage geht am Kern vorbei."},{"option":3,"text":"Ein einzelner Fall als Grundlage wäre tatsächlich eine dünne Basis. Die Kollegin nennt aber keinen Fall, in dem der kleine Anteil nichts bewirkte. Ihr Argument ist allein, dass sie sich die Wirkung nicht vorstellen kann."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Jabr, F. (2012): How Does a Caterpillar Turn into a Butterfly? Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/caterpillar-butterfly-metamorphosis-explainer/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c3d5832059485d0f"}},{"id":"qx-b1-046","clusterId":"B","werkstueckRef":"B.13","stufe":2,"question":"Warum ist die Intuition in diesem Fall ein schlechter Maßstab, obwohl dasselbe Bauchgefühl bei dubiosen Verkaufsangeboten gut schützt?","scenario":"Ein Kollege sagt über ein neues Medikament: „Wie soll ein winziger Wirkstoff den ganzen Körper beeinflussen? Das kann ich mir nicht vorstellen, also wirkt es nicht.“ Die Zulassungsstudien liegen offen vor, er hat sie nicht gelesen. Zu gut klingende Angebote kennst du selbst als Fall, in dem dich ein Bauchgefühl zu Recht zum genaueren Hinsehen bringt.","options":["Weil sie hier als letztes Wort dient und verhindert, dass er die vorliegenden Belege überhaupt prüft.","Weil sie hier aus schlechten Einzelerfahrungen vorschnell auf alle Medikamente schließt und deshalb zu pauschal urteilt.","Weil sie hier von leicht abrufbaren Beispielen gespeist wird und die Risiken von Medikamenten verzerrt erscheinen lässt.","Weil sie hier auf einem Autoritätsargument beruht und der Meinung einer Person mehr traut als den vorliegenden Daten."],"correctIndex":0,"explanation":"Ein Bauchgefühl ist ein brauchbarer erster Filter: Es lässt uns bei Angeboten, die zu gut klingen, genauer hinsehen und schützt so vor vielen Betrügereien. Zum Problem wird es, wenn es zur unanfechtbaren Endinstanz wird. „Ich kann mir das nicht vorstellen“ sagt etwas über die Grenzen der eigenen Vorstellungskraft und des eigenen Wissens, nicht über die Wirklichkeit. Die Intuition ist für Alltagssituationen mit mittleren Größen und Geschwindigkeiten geeicht, bei komplexen wissenschaftlichen Themen weit außerhalb der Alltagserfahrung führt sie in die Irre. Wer seine Intuition hier über die vorliegenden Studien stellt, schaltet die Prüfung der Belege ab, die sie herausfordern könnten. Die Intuition ist nicht grundsätzlich unzuverlässig, sondern nur als finale Urteilsinstanz problematisch. Die anderen Erklärungen nennen bekannte Denkfehler, die hier aber nicht vorliegen: Der Kollege schließt nicht aus schlechten Erfahrungen auf alle Medikamente, von Erfahrungen ist gar nicht die Rede. Von auffälligen Berichten, die sein Urteil färben könnten, steht im Szenario ebenfalls nichts. Und er beruft sich auf keine Autorität, sondern allein auf das eigene Gefühl.","coreRule":"⚡ Die Intuition darf den Anfang der Prüfung machen, aber nicht das letzte Wort haben.","beleg":"Werkstück B.13 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"„Das kann ich mir nicht vorstellen“ sagt etwas über die Grenzen der eigenen Vorstellungskraft, nicht über das Medikament. Als Filter schützt das Bauchgefühl, als letztes Wort hält es davon ab, die vorliegenden Studien zu prüfen.","prueffrage":"Wie oft konnte der Kollege sein Gefühl über Arzneiwirkungen schon an echten Ergebnissen überprüfen, verglichen mit deinem Gefühl bei Verkaufsangeboten?","rueckmeldung":[{"option":1,"text":"Pauschal wirkt das Urteil tatsächlich, es betrifft aber nur dieses eine Mittel. Von schlechten Erfahrungen mit Medikamenten ist keine Rede: Der Zweifel kommt allein daraus, dass er sich den Mechanismus nicht vorstellen kann."},{"option":2,"text":"Verzerrte Risikowahrnehmung ist ein bekannter Fehler, im Szenario geht es aber gar nicht um Risiken oder auffällige Berichte. Der Kollege stützt sich auf seine Vorstellungskraft, nicht auf Beispiele, die ihm leicht einfallen."},{"option":3,"text":"Eine Autorität kommt im Szenario nicht vor: Der Kollege verlässt sich auf sein eigenes Gefühl, nicht auf die Meinung einer anderen Person. Das Problem liegt darin, dass er die offen vorliegenden Studien beiseiteschiebt."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1650e671225cb5ba"}},{"id":"qx-b1-047","clusterId":"B","werkstueckRef":"B.13","stufe":4,"question":"Was ist an dieser Aussage als Argument gegen die Evolution des Auges ihr eigentliches Problem?","scenario":"Jemand sagt: „Ich kann mir einfach nicht vorstellen, wie sich aus zufälligen Mutationen und natürlicher Selektion etwas so Komplexes wie ein menschliches Auge entwickeln konnte. Das ist doch unmöglich!“","options":["Sie baut aus der Evolutionstheorie einen leicht angreifbaren Strohmann, obwohl die Theorie neben dem Zufall auch die natürliche Selektion als Mechanismus annimmt.","Sie macht die Grenze der eigenen Vorstellungskraft zum Maßstab für die Wirklichkeit, obwohl daraus nichts über die Entstehung des Auges folgt.","Sie greift die Forschenden persönlich an, statt ihre Befunde zu prüfen, obwohl ein Angriff auf Personen kein einziges ihrer Ergebnisse widerlegen kann.","Sie beruft sich auf die Meinung einer Autorität statt auf Belege, obwohl auch anerkannte Fachleute sich in Einzelfragen irren können."],"correctIndex":1,"explanation":"Der Satz „Ich kann mir nicht vorstellen, wie …“ beschreibt nur, was in einem Kopf möglich ist, nicht was in der Natur möglich ist. Aus fehlender Vorstellungskraft folgt nichts über die Wirklichkeit: Vieles, was sich als wahr herausgestellt hat, widerspricht der Alltagsintuition, etwa dass Uhren in schneller Bewegung langsamer gehen oder dass riesige Kontinente langsam über den Globus driften. Der Einwand ist also kein Argument, sondern ein Bekenntnis zur eigenen Wissenslücke, etwa über die kleinen Zwischenschritte, in denen komplexe Strukturen entstehen können. Hilfreich ist die Frage, ob der Mangel an Vorstellungskraft ein Beweis gegen die Behauptung oder nur ein Beweis für die Grenzen des eigenen Wissens ist.","coreRule":"⚡ Wenn du es dir nicht vorstellen kannst, such eine Erklärung oder Analogie, statt es abzulehnen.","beleg":"Werkstück B.13 (Kontext & Tiefe; Anwendung & Relevanz: Bei der Evolutionstheorie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Fehlende Vorstellungskraft sagt etwas über den eigenen Kopf, nicht über die Natur. Wer „kann ich mir nicht vorstellen“ als „unmöglich“ liest, macht aus einer Wissenslücke, etwa über viele kleine Zwischenschritte, einen Einwand gegen die Sache selbst.","prueffrage":"Welche einfacheren Augen gibt es heute bei anderen Tieren, und was zeigen sie über mögliche Zwischenstufen?","rueckmeldung":[{"option":0,"text":"Ein Strohmann verzerrt die Gegenseite, und das wirkt hier plausibel, weil der Zufall so betont wird. Die Aussage nennt aber Mutation und Selektion beide, gibt die Theorie also korrekt wieder. Ihr Problem liegt im Schluss, nicht in der Darstellung."},{"option":2,"text":"Persönliche Angriffe sind ein bekannter Denkfehler, und ein solcher Angriff würde tatsächlich keinen Befund widerlegen. Hier kommen aber gar keine Forschenden vor: Die Aussage richtet sich gegen die Erklärung selbst, nicht gegen Personen."},{"option":3,"text":"Autoritätsargumente sind verführerisch, und auch Fachleute können sich in Einzelfragen irren. Die Aussage beruft sich aber auf keine Autorität, sondern ausschließlich auf das eigene Vorstellungsvermögen. Genau darin liegt ihr Problem."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"174512fe5295e969"}},{"id":"qx-b1-048","clusterId":"B","werkstueckRef":"B.14","stufe":1,"question":"Welcher Denkfehler steckt in dem Satz „Das ist rein natürlich, die Natur weiß am besten, was gut für uns ist“?","scenario":"In der Drogerie rät dir jemand zu einem pflanzlichen Erkältungsmittel: „Das ist rein natürlich, ohne all die aggressive Chemie. Die Natur weiß am besten, was gut für uns ist.“","options":["Er schließt aus dem langen Gebrauch eines Mittels auf dessen Wirksamkeit (Appell an die Tradition).","Er schließt aus einer Besserung nach der Einnahme auf die Wirkung des Mittels (Post-hoc-Fehlschluss).","Er schließt aus der Beliebtheit eines Mittels bei vielen Menschen auf dessen Wirkung (Appell an die Menge).","Er schließt von der Herkunft eines Stoffs auf dessen Sicherheit und Wirkung (Appell an die Natur)."],"correctIndex":3,"explanation":"Der Satz setzt „natürlich“ mit „gut, sicher, überlegen“ gleich. Das ist ein Fehlschluss, denn die Herkunft eines Stoffs sagt nichts über Sicherheit oder Wirkung. Die Natur ist gleichgültig gegenüber unserem Wohlbefinden: Sie bringt Heilendes hervor, aber auch Tödliches wie Botulinumtoxin, Schlangengift oder Knollenblätterpilze. Ob ein Mittel hilft oder schadet, zeigen Reinheit, Dosierbarkeit und getestete Wirkung. Der Fehler liegt also nicht in einer angeblichen Schwäche natürlicher Stoffe, sondern darin, dass von der Herkunft auf Sicherheit und Wirkung geschlossen wird. Der Satz bewertet einen Stoff nach seiner Herkunft statt nach geprüfter Evidenz. Die anderen Fehlschlüsse gibt es ebenfalls, sie kommen in dem Satz aber nicht vor: Er beruft sich weder auf langen Gebrauch noch darauf, dass viele Menschen das Mittel nutzen, und er nennt auch keine Besserung nach der Einnahme.","coreRule":"⚡ „Natürlich“ ist ein Herkunftsetikett, kein Gütesiegel.","beleg":"Werkstück B.14 (Das Gespräch in der Drogerie; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Der Satz bewertet das Mittel nach seiner Herkunft, nicht nach geprüfter Wirkung. „Natürlich“ sagt aber nichts über Sicherheit oder Nutzen: Die Natur bringt Heilendes hervor, aber auch Tödliches wie Knollenblätterpilze.","prueffrage":"Was steht auf der Packung über die Menge der Inhaltsstoffe und über Studien zur Wirkung?","rueckmeldung":[{"option":0,"text":"Pflanzliche Mittel haben oft eine lange Geschichte, das macht diese Deutung naheliegend. Im Satz kommt aber weder langer Gebrauch noch Überlieferung vor; er stützt sich nur darauf, dass der Stoff natürlich ist."},{"option":1,"text":"Dass ein Mittel nach der Einnahme zu helfen scheint, ist ein klassischer Anlass für Fehlschlüsse. Hier hat aber noch niemand etwas eingenommen, und es wird keine Besserung berichtet. Es geht nur um die Herkunft des Mittels."},{"option":2,"text":"Ein Mittel, das viele nutzen, wirkt schnell vertrauenswürdig. Der Satz nennt aber weder Nutzerzahlen noch Beliebtheit. Er wirbt allein mit „natürlich“ und „ohne Chemie“, und das ist ein Herkunftsargument."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"aa13fc20b5524e5d"}},{"id":"qx-b1-049","clusterId":"B","werkstueckRef":"B.14","stufe":2,"question":"Was spricht an dieser Argumentation am ehesten gegen den Schluss, der Rindenextrakt sei dem Laborprodukt überlegen?","options":["Die Rinde enthält viele weitere Substanzen, und ihr Wirkstoffgehalt schwankt mit Baum und Jahreszeit. Die Herkunft sagt also nichts über Reinheit und Dosis aus.","Kopfschmerzen gehen oft von selbst vorbei, auch nach einem Rindenextrakt. Eine Besserung danach beweist also nicht, dass der Stoff aus der Rinde wirkt.","Hersteller von Weidenrinden-Extrakten werben mit „natürlich“, weil sich das gut verkauft. Das Urteil der Freundin stammt darum wohl aus der Werbung, nicht aus Belegen.","Weidenrinde wird seit Jahrhunderten gegen Schmerzen genutzt, doch langer Gebrauch belegt keine Wirksamkeit. Der Extrakt der Freundin ist darum nicht besser belegt."],"correctIndex":0,"explanation":"Die Freundin schließt von der Herkunft auf die Qualität. Das ist ein Fehlschluss, denn entscheidend sind Reinheit, Dosierbarkeit und geprüfte Wirkung. Weidenrinde enthält neben dem Vorläuferstoff Salicin hunderte andere Substanzen, von denen manche die Wirkung abschwächen oder Nebenwirkungen haben können. Außerdem schwankt der Wirkstoffgehalt je nach Baum, Jahreszeit und Standort, sodass sich kaum genau dosieren lässt. Eine Aspirin-Tablette enthält dagegen eine festgelegte Menge reiner Acetylsalicylsäure, deren Vorläufer in der Weidenrinde vorkommt. Das macht Synthetisches nicht automatisch besser, es zeigt nur, dass „natürlich“ kein Qualitätsmerkmal ist. Die anderen Gedanken klingen vernünftig, gehen aber am Argument vorbei: Dass sich Kopfschmerzen von selbst bessern können, wäre erst nach einer Einnahme ein Thema, die Freundin argumentiert aber mit der Herkunft. Von Werbung ist im Szenario keine Rede, ihre Wahl begründet sie nicht mit Verkaufsversprechen. Und auf den langen Gebrauch der Weidenrinde beruft sie sich nicht, sie schließt von der Herkunft des Wirkstoffs auf seine Qualität.","coreRule":"⚡ Die Herkunft eines Stoffes sagt nichts über seine Qualität. Reinheit, Dosis und getestete Wirkung entscheiden.","beleg":"Werkstück B.14 (Kontext & Tiefe: Der entscheidende Vorteil des „Künstlichen“)","status":"entwurf","scenario":"Eine Freundin hat Kopfschmerzen und will keine Tabletten nehmen. Sie sagt: „Ich nehme lieber Weidenrinden-Extrakt statt Aspirin. Der Wirkstoff kommt ja ursprünglich aus der Rinde, also ist das Original natürlich besser als die Kopie aus dem Labor.“","kurz":"Die Freundin schließt von der Herkunft auf die Qualität. Der Rindenextrakt enthält aber viele weitere Stoffe und schwankt im Wirkstoffgehalt, „natürlich“ sagt also nichts über Reinheit und Dosis.","prueffrage":"In welcher Beziehung steht der Wirkstoff der Weidenrinde zu dem der Aspirin-Tablette?","rueckmeldung":[{"option":1,"text":"Dass Kopfschmerzen oft von selbst vergehen, stimmt, und eine Besserung danach beweist wenig. Die Freundin beruft sich aber auf keine Besserung, sondern auf die Herkunft des Wirkstoffs. Der Gedanke würde erst nach einer Einnahme greifen."},{"option":2,"text":"Dass „natürlich“ gern als Verkaufsargument dient, ist bekannt. Im Szenario steht davon aber nichts, die Freundin begründet ihre Wahl mit der Herkunft. Selbst wenn Werbung dahinterstünde, wäre der Schluss damit noch nicht geprüft."},{"option":3,"text":"Dass langer Gebrauch noch keine Wirksamkeit belegt, trifft zu. Die Freundin beruft sich aber gar nicht auf Tradition, sondern auf die Herkunft des Wirkstoffs. Über Reinheit und Dosierbarkeit, um die es hier geht, sagt dieser Einwand nichts."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vlachojannis u. a. (2011), Verlagsfassung","oeffentlich":false,"doi":"10.1002/ptr.3386"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"873d2bddb7540013"}},{"id":"qx-b1-050","clusterId":"B","werkstueckRef":"B.14","stufe":3,"question":"Eine Bekannte erzählt dir, sie esse am liebsten unverarbeitete Lebensmittel, gehe oft in den Wald und setze bei leichten Erkältungen auf Kräutertee. Ihr Bruder lehnt dagegen die vom Arzt empfohlene Behandlung seiner Erkrankung ab und nimmt stattdessen nur noch „rein natürliche“ Präparate, weil „die Natur am besten weiß, was gut für uns ist“. Woran erkennst du, dass beim Bruder der Appell an die Natur zum gefährlichen Fehlschluss wird?","options":["Er ersetzt eine geprüft wirksame und sichere Behandlung durch Alternativen, deren Wirkung und Dosierung ungeprüft sind, und riskiert dadurch schwere Folgen.","Er vertraut dem Wort „rein“ auf seinen Präparaten, das als Werbebegriff keine geprüfte Qualität garantiert, und trifft dadurch eine Fehlentscheidung.","Er hält die Natur für klüger als die Ärzte, und schon diese Überzeugung allein macht den Appell an die Natur zum gefährlichen Fehlschluss.","Er verlässt sich auf Erfahrungsberichte anderer Anwender statt auf Studien, und solche Berichte sind als Beleg für eine Wirkung unzuverlässig."],"correctIndex":0,"explanation":"Eine Vorliebe für Natürliches ist für sich genommen harmlos und oft sogar gesund: Wer unverarbeitete Lebensmittel mag, im Wald spazieren geht oder bei einer leichten Erkältung Kräutertee trinkt, trifft keine riskante Entscheidung. Der Fehlschluss wird erst gefährlich, wenn er zu einer Entscheidung mit Folgen wird. Das ist der Fall, wenn eine nachweislich wirksame und sichere Behandlung durch Mittel ersetzt wird, deren Wirkung nie geprüft wurde und deren Dosis schwankt. Dann entscheidet die Herkunft über die Behandlung statt die belegte Wirkung. Ein Beispiel: Wer eine Chemotherapie zugunsten von Aprikosenkernen ablehnt, setzt sich einem Gift aus (sie enthalten Amygdalin, aus dem im Körper giftige Blausäure entstehen kann), statt die Krankheit zu behandeln. Die Herkunft sagt weder etwas über Sicherheit noch über Wirksamkeit. Die richtige Frage lautet immer: Was zeigen die besten Belege über Sicherheit, Reinheit, Dosierbarkeit und Wirksamkeit genau dieses Mittels? Die anderen Antworten klingen einleuchtend, treffen aber nicht den Kern: Dass „rein“ ein Werbewort ist, stimmt, gefährlich wird es aber erst durch das Absetzen der Behandlung. Die Überzeugung, dass Natürliches besser ist, teilt in milder Form auch seine Schwester, ohne sich zu gefährden. Und von Erfahrungsberichten, auf die er sich stützt, steht im Fall nichts.","coreRule":"⚡ Natürliche Vorlieben sind harmlos – gefährlich wird erst der Ersatz geprüfter Lösungen durch ungeprüfte.","beleg":"Werkstück B.14 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Gefährlich wird der Appell an die Natur, wenn er eine geprüft wirksame Behandlung verdrängt. Die Herkunft eines Mittels sagt weder etwas über Sicherheit noch über Wirkung. Die Vorliebe der Bekannten bleibt harmlos, weil sie keine Behandlung ersetzt.","prueffrage":"Bei welchen Beschwerden setzt die Bekannte auf Natürliches, und bei welchen ihr Bruder?","rueckmeldung":[{"option":1,"text":"Dass „rein“ ein Werbewort ist, stimmt. Schlimm wäre es aber erst durch das, was er damit tut: Er setzt die empfohlene Behandlung ab. Auch ein geprüftes Präparat würde diese nicht ersetzen, wenn seine Wirkung nicht belegt ist."},{"option":2,"text":"Seine Überzeugung ist unbegründet, aber für sich genommen noch kein Risiko. Seine Schwester teilt sie in milder Form, ohne sich zu gefährden. Gefährlich wird sie erst, wenn sie eine Entscheidung mit Folgen lenkt, hier den Verzicht auf die Behandlung."},{"option":3,"text":"Erfahrungsberichte sind tatsächlich ein schwacher Beleg für Wirkung. Im Fall steht davon aber nichts: Er beruft sich darauf, dass die Natur es am besten wisse. Gefährlich ist nicht seine Quelle, sondern der Ersatz einer geprüften Behandlung."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Milazzo, S.; Horneber, M. (2015): Laetrile treatment for cancer. Cochrane Database of Systematic Reviews, CD005476 (Volltext frei in PMC6513327)","oeffentlich":true,"doi":"10.1002/14651858.CD005476.pub4","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8fc0de1dda93dbe6"}},{"id":"qx-b1-051","clusterId":"B","werkstueckRef":"B.14","stufe":4,"question":"Wie ist diese Behauptung am treffendsten zu beurteilen?","scenario":"Ein Verkäufer behauptet: „Dieser Stoff aus der Pflanze ist dem im Labor hergestellten überlegen, obwohl beide chemisch exakt identisch sind. Denn der natürliche trägt eine Lebenskraft in sich.“","options":["Sie ist ein Bestätigungsfehler, weil der Verkäufer nur Belege für die Überlegenheit des Pflanzenstoffs sammelt und Befunde zum Laborstoff übergeht.","Sie ist ein Autoritätsargument, weil sich der Verkäufer auf seine Stellung als Fachmann für Pflanzenstoffe beruft, statt Belege für den Vorteil zu nennen.","Sie ist ein Strohmann, weil der Verkäufer der Gegenseite eine Behauptung über den Laborstoff unterstellt, die sie nie aufgestellt hat, und diese dann widerlegt.","Sie ist eine unbelegte Zusatzannahme, weil bei identischen Molekülen kein Unterschied gezeigt wird und Wirkung und Sicherheit durch Tests geprüft werden müssen."],"correctIndex":3,"explanation":"Die Behauptung gibt zu, dass beide Stoffe chemisch identisch sind, und setzt dann einen Vorteil des „natürlichen“ obendrauf, die „Lebenskraft“. Diese behauptete Überlegenheit ist unbewiesen, und sie lässt sich auch nicht an den Molekülen festmachen, die ja gleich sind. Die Herkunft sagt weder etwas über Wirksamkeit noch über Sicherheit: Der Knollenblätterpilz ist ebenso natürlich wie Arsen. Was zählt, sind Reinheit, Dosierbarkeit, Wirksamkeit und Sicherheit, und die muss man durch Tests belegen.","coreRule":"⚡ Bei identischen Molekülen bleibt „Lebenskraft“ eine Behauptung, kein Befund.","beleg":"Werkstück B.14 (Anwendung & Relevanz: In der Pseudomedizin & Wellness-Industrie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Die Behauptung räumt ein, dass die Moleküle gleich sind, setzt aber einen Vorteil des „Natürlichen“ obendrauf, den sie nicht belegt. Herkunft sagt nichts über Wirkung und Sicherheit, das zeigen erst Tests.","prueffrage":"Welcher messbare Unterschied zwischen den beiden Stoffen wird in der Aussage tatsächlich genannt?","rueckmeldung":[{"option":0,"text":"Einseitig für den Pflanzenstoff zu werben wirkt wie Bestätigungsfehler. Dafür müsste der Verkäufer aber Belege sammeln und Gegenbefunde ausblenden. Er nennt gar keine Belege, sondern setzt den Vorteil einfach behauptend obendrauf."},{"option":1,"text":"Dass kein Beleg für den Vorteil genannt wird, stimmt. Der Verkäufer beruft sich aber nicht auf Fachwissen oder eine Stellung, sondern auf eine „Lebenskraft“. Damit liegt keine Berufung auf eine Autorität vor."},{"option":2,"text":"Ein Strohmann verlangt, dass jemand der Gegenseite eine Position unterstellt und diese dann widerlegt. Hier gibt es keine unterstellte Position: Der Verkäufer stellt seinen Vorteil des Pflanzenstoffs selbst auf."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"},{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"346210bc94a31f86"}},{"id":"qx-b1-052","clusterId":"B","werkstueckRef":"B.15","stufe":1,"question":"Was ist an diesem Schluss fehlerhaft, und welche Information würde ihn am ehesten prüfen?","scenario":"In einem Ratgeber-Artikel steht: „Zwei bekannte Tech-Gründer haben ihr Studium abgebrochen und sind Milliardäre geworden. Also ist ein Studienabbruch ein guter Weg zum Erfolg.“","options":["Der Schluss stützt sich nur auf die Erfolgreichen; entscheidend wäre, wie es allen ergangen ist, die ihr Studium abgebrochen haben.","Der Schluss beruft sich auf das Ansehen der beiden Gründer; entscheidend wäre, ob sie als Fachleute für Bildung und Ausbildung gelten.","Der Schluss stammt aus einem Ratgeber, der Leser gewinnen will; entscheidend wäre, wer den Artikel bezahlt oder bestellt hat.","Der Schluss rechnet mit einem Durchschnitt der Milliardäre, der Ausreißer verdeckt; entscheidend wäre die Streuung ihrer Vermögen."],"correctIndex":0,"explanation":"Hier werden nur diejenigen betrachtet, die einen Auswahlprozess erfolgreich durchlaufen haben. Die vielen Menschen, die ebenfalls abgebrochen haben und gescheitert sind, tauchen in keiner Erfolgsgeschichte auf, wären für den Schluss aber entscheidend. Erst der Vergleich zeigt, ob Abbrechen die Erfolgschance erhöht oder ob Glück, Timing und andere Faktoren die Hauptrolle spielen. Ähnlich ist es bei Gewohnheiten wie „früh aufstehen“: Auch viele Gescheiterte können sie gehabt haben.","coreRule":"⚡ Wenn nur Gewinner gezeigt werden, frag nach denen, die dasselbe getan haben und trotzdem gescheitert sind.","beleg":"Werkstück B.15 (Kernidee; Anwendung & Relevanz: In der Business- & Self-Help-Industrie)","status":"entwurf","kurz":"Der Schluss betrachtet nur die Erfolgreichen unter den Studienabbrechern. Die vielen, die ebenfalls abgebrochen haben und gescheitert sind, fehlen; erst der Vergleich mit ihnen zeigt, ob Abbrechen die Chancen erhöht oder Glück und Timing entscheiden.","prueffrage":"Woher kennt der Artikel gerade diese zwei Gründer, und warum wird über sie überhaupt geschrieben?","rueckmeldung":[{"option":1,"text":"Auf die Gründer als Vorbilder zu schauen, wirkt naheliegend. Sie dienen im Artikel aber nur als Beispiele, nicht als Experten für Bildung; ihr Fachwissen entscheidet nicht darüber, ob der Schluss trägt."},{"option":2,"text":"Wer einen Text bestellt hat, ist ein vernünftiger Anlass zur Vorsicht. Für die Frage, ob der Schluss trägt, sagt das aber nichts: Ein Fehlschluss bleibt einer, auch wenn die Quelle ohne jedes Interesse schreibt."},{"option":3,"text":"Von Ausreißern und Streuung zu sprechen, wäre bei Durchschnittswerten sinnvoll. Der Artikel rechnet aber gar nicht mit einem Durchschnitt, sondern stützt sich auf zwei Einzelfälle."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"84dd879517ed2fe1"}},{"id":"qx-b1-053","clusterId":"B","werkstueckRef":"B.15","stufe":2,"question":"Welche Frage prüft die Schlussfolgerung des Lesers am besten?","scenario":"In einer Zeitung wird ein Medium gefeiert, weil es ein Ereignis angeblich korrekt vorhergesagt hat. Berichtet wird nur über diese eine Vorhersage. Ein Leser schreibt: „Das kann kein Zufall sein, das Medium hat offenbar echte Fähigkeiten.“","options":["Wie viel Geld und Ansehen gewinnt die Zeitung, wenn sie dieses Medium wegen einer Vorhersage feiert?","Wie viele andere Vorhersagen dieses und anderer Medien lagen daneben und wurden nie erwähnt?","Wie gründlich haben anerkannte Stellen die behaupteten Fähigkeiten dieses Mediums geprüft?","Wie viele Leser der Zeitung halten das Medium schon länger für glaubwürdig und folgen ihm?"],"correctIndex":1,"explanation":"Bei diesem Medium hörst Du nichts von den vielen Vorhersagen desselben Mediums (und aller anderen), die danebenlagen. Die Treffer überleben in der öffentlichen Erinnerung, die Fehlschüsse verschwinden. Der eine berichtete Treffer ist also eine nach Erfolg gefilterte Auswahl. Ob er etwas über echte Fähigkeiten aussagt, lässt sich erst beurteilen, wenn Du auch die verfehlten Vorhersagen kennst.","coreRule":"⚡ Zeig mir nicht nur die Treffer, sondern alle Versuche.","quote":"Aber wo ist der Friedhof? Welche unsichtbaren Daten der Gescheiterten fehlen in diesem Bild?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.15 (Anwendung & Relevanz: In der Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Ein einzelner berichteter Treffer sagt wenig, solange die verfehlten Vorhersagen unsichtbar bleiben: Treffer werden erinnert, Fehlschüsse verschwinden. Erst der Blick auf beide zeigt, ob echte Fähigkeiten im Spiel sind.","prueffrage":"Warum berichtet die Zeitung gerade über diese Vorhersage, und worüber hätte sie geschrieben, wenn sie nicht eingetroffen wäre?","rueckmeldung":[{"option":0,"text":"Nach den Interessen einer Quelle zu fragen, ist oft sinnvoll. Hier lässt sich damit aber nicht beurteilen, ob der Treffer Zufall war, denn das hängt davon ab, wie viele Vorhersagen danebenlagen."},{"option":2,"text":"Eine Prüfung der Fähigkeiten wäre aufschlussreich, wenn sie vorläge. Eine Bescheinigung ersetzt aber nicht den Blick darauf, wie viele Vorhersagen getroffen und wie viele verfehlt wurden."},{"option":3,"text":"Dass viele Leser dem Medium vertrauen, zeigt Zuspruch und womöglich gute Erinnerungen an einzelne Treffer. Über die tatsächliche Trefferquote sagt es nichts, denn dafür müsste man Treffer und Fehlschüsse zählen."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"bce21cc5efc7ee07"}},{"id":"qx-b1-054","clusterId":"B","werkstueckRef":"B.15","stufe":3,"question":"Du liest in einem Wirtschaftsmagazin, wie ein Mathematiker im Zweiten Weltkrieg den Generälen mit einem einzigen Satz widerspricht: „Meine Herren, Sie liegen komplett falsch.“ Wie gehst du mit der Szene um?","options":["Ich halte den Kerngedanken für prüfbar, die wörtliche Szene aber für ungesichert, weil anschauliche Details ohne Quelle leicht dazugedichtet sind.","Ich prüfe, ob es den Mathematiker wirklich gab, und halte den Wortlaut dann für bestätigt, weil die Szene von einer belegten Person handelt.","Ich verwerfe die Szene samt Kerngedanken, weil ein wörtlicher Satz ohne Quelle zeigt, dass das Magazin unseriös arbeitet und der Kern nichts taugt.","Ich übernehme den Satz des Mathematikers vorerst, weil sein Kerngedanke stimmt und eine so treffende Szene wohl auch im Wortlaut stimmt."],"correctIndex":0,"explanation":"Anschauliche Details wie wörtliche Dialoge sind kein Beleg, sondern oft das Ergebnis dramatisierenden Nacherzählens. Real ist Walds Arbeit für die Statistical Research Group der Columbia University, für die er 1943 Memoranden verfasste, die aus den Treffern zurückgekehrter Flugzeuge die Verwundbarkeit einzelner Flugzeugteile schätzen. Eine ausdrückliche Empfehlung, wo gepanzert werden soll, enthalten sie nicht, und der Dialog selbst ist nicht dokumentiert. Auch die Rahmung vom einsamen Außenseiter greift zu kurz, denn das US-Militär wertete Kampfschäden bereits systematisch aus. Die vernünftige Haltung trennt also zwischen dem prüfbaren Kern (der Idee der Auswahlverzerrung: Die Daten der Zurückgekehrten verzerren das Bild) und der ungesicherten Ausschmückung.","coreRule":"⚡ Eine gute Lehrgeschichte ist noch keine Quelle – prüfe, was davon belegt ist.","beleg":"Werkstück B.15 (Die unsichtbaren Einschusslöcher); Fn. gl-b-wald (Mangel/Samaniego 1984, JASA 79(386), S. 259–267)","status":"entwurf","scenario":"Der Artikel erzählt eine mitreißende Geschichte über Abraham Wald und die Panzerung von Bombern. Wörtliche Dialoge, genaue Trefferverteilungen und ein einsamer Held, der die ahnungslosen Militärs belehrt, machen die Erzählung sehr anschaulich. Eine Quelle für diese Details nennt der Artikel nicht.","kurz":"Der Kern, dass die Daten der Zurückgekehrten das Bild verzerren, lässt sich prüfen. Der wörtliche Satz ist dagegen nirgends belegt. Anschaulichkeit ersetzt keine Quelle, und eine gut erzählte Szene macht nicht jedes Detail wahr.","prueffrage":"Woher könnte ein Magazin heute den genauen Wortlaut eines Satzes kennen, der vor über 80 Jahren in einer Besprechung gefallen sein soll?","rueckmeldung":[{"option":1,"text":"Dass es Wald und seine Arbeit gab, lässt sich belegen und beruhigt. Daraus folgt aber nicht, dass er den Satz so gesagt hat: Die Person zu bestätigen, bestätigt nicht den überlieferten Dialog, und der ist nicht dokumentiert."},{"option":2,"text":"Ein wörtlicher Satz ohne Quelle verdient tatsächlich Skepsis. Daraus folgt aber weder, dass das ganze Magazin unseriös ist, noch dass der Kern nichts taugt: Eine ausgeschmückte Szene macht eine belegte Idee nicht falsch."},{"option":3,"text":"Der Kerngedanke stimmt, das ist richtig. Er überträgt sich aber nicht auf jedes erzählte Detail: Dass eine Szene treffend wirkt, spricht nicht für ihren Wortlaut, denn gerade solche Dialoge entstehen oft erst beim dramatisierenden Nacherzählen."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1d80b3f2f2436739"}},{"id":"qx-b1-055","clusterId":"B","werkstueckRef":"B.15","stufe":4,"question":"Welche Frage prüft die Behauptung des Architekten am besten?","scenario":"Ein Architekt behauptet: „Früher hat man besser gebaut. Sieh dir die alten Häuser an, die noch heute stehen!“","options":["Wie viele der damals gebauten Häuser sind inzwischen abgerissen oder eingestürzt?","Wie komfortabel sind die alten Häuser nach heutigen Maßstäben bei Dämmung und Heizung?","Wie stark hat sich die durchschnittliche Wohnfläche pro Person seit damals verändert?","Wie unterscheiden sich die Baustile der damaligen Häuser von denen der heutigen?"],"correctIndex":0,"explanation":"Die Behauptung stützt sich nur auf Gebäude, die einen langen Auswahlprozess überstanden haben: Was baufällig war, wurde abgerissen, umgebaut oder ist eingestürzt. Dass die übrig gebliebenen Häuser solide sind, folgt daraus fast zwangsläufig und sagt wenig über die Bauweise einer ganzen Epoche. Erst der Blick auf die verschwundenen Häuser zeigt, ob früher tatsächlich besser gebaut wurde. Die anderen Fragen sind in anderen Zusammenhängen sinnvoll, passen hier aber nicht: Der Komfort nach heutigen Maßstäben sagt nichts darüber, wie haltbar die Häuser waren. Die Wohnfläche pro Person betrifft ein anderes Merkmal als die Haltbarkeit, um die es in der Behauptung geht. Und Unterschiede der Baustile erklären nicht, welche Häuser den Auswahlprozess nicht überstanden haben.","coreRule":"⚡ Was heute noch steht, ist eine Auswahl – nicht die Gesamtheit dessen, was einmal gebaut wurde.","beleg":"Werkstück B.15 (Red Flags; Anwendung & Relevanz)","status":"entwurf","kurz":"Die Behauptung beruht nur auf Häusern, die lange genug überdauert haben; baufällige verschwanden längst. Dass die übrigen solide wirken, folgt fast zwangsläufig und sagt wenig über die Bauweise der ganzen Zeit.","prueffrage":"Wer hat im Lauf der Zeit entschieden, welche Häuser stehen bleiben, und nach welchen Gesichtspunkten?","rueckmeldung":[{"option":1,"text":"Komfort wirkt wie ein naheliegender Maßstab beim Vergleich von alt und neu. Die Behauptung handelt aber von Solidität und Haltbarkeit; Dämmung und Heizung sagen darüber nichts, und die verschwundenen Häuser bleiben unberücksichtigt."},{"option":2,"text":"Der Vergleich zeigt, wie sich das Wohnen verändert hat, etwa beim Platz pro Person. Die Behauptung betrifft aber die Haltbarkeit der Bauten, ein ganz anderes Merkmal, das die Wohnfläche nicht berührt."},{"option":3,"text":"Unterschiedliche Baustile können durchaus Hinweise auf Bauweisen geben. Sie erklären aber nicht, welche Häuser abgerissen wurden oder einstürzten, und genau dieser Blick auf die Verschwundenen fehlt hier."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"933c183eddb1b661"}},{"id":"qx-b1-056","clusterId":"B","werkstueckRef":"B.16","stufe":1,"question":"Was passiert sprachlich, wenn Menschen im Netz als „Bots“ oder „NPCs“ abgetan werden, und was ist daran problematisch?","options":["Die Menschen werden mit ekelerregenden Tieren verglichen und damit auf Instinkte reduziert, sodass Ausgrenzung leichter fällt.","Die Menschen werden als gefühllose Automaten ohne eigenes Denken dargestellt, sodass ihre Gründe nicht mehr geprüft werden müssen.","Die Menschen werden als Vertreter einer verhassten Ideologie angesehen, sodass sie nur noch als Teil einer Gruppe gelten.","Die Menschen werden als besonders gefährlich und mächtig dargestellt, sodass Misstrauen gegen sie gerechtfertigt erscheint."],"correctIndex":1,"explanation":"Wer Menschen als „NPCs“ oder „Bots“ bezeichnet, stellt sie als kalte, gefühllose Automaten dar und beraubt sie damit ihrer Wärme, Individualität und Empathie. Das ist die mechanistische Form der Entmenschlichung: Sie werden wie seelenlose Instrumente behandelt, die nur Skripte abspielen. Die Folge: Wer ein Gegenüber so einordnet, hat keinen Anlass mehr, dessen Gründe ernst zu nehmen, denn bei einem Automaten gibt es keine eigenen Gründe. Ein Tiervergleich wäre dagegen die animalische Form, die Menschen auf primitive, instinktgetriebene Kreaturen reduziert und Ekel, Angst oder Verachtung hervorruft. Die Gruppenabwertung durch Etiketten macht Menschen zu bloßen Repräsentanten einer verhassten Ideologie, nimmt ihnen aber nicht die Eigenschaft, denkende Wesen zu sein. Der Gefährlichkeitsvorwurf setzt sogar voraus, dass sie handlungsfähig sind. Entscheidend ist also, ob dem Gegenüber das eigene Denken und Fühlen abgesprochen wird oder ob nur seine Position kritisiert wird. Die Kritik an einer Position ist legitim, die Aberkennung des Menschseins ist es nicht.","coreRule":"⚡ Wer anderen das eigene Denken und Fühlen abspricht, muss ihre Gründe nicht mehr prüfen.","beleg":"Werkstück B.16 (Kontext & Tiefe: Zwei Mechanismen; Anwendung & Relevanz: In der politischen Propaganda)","status":"entwurf","scenario":"In einem Kommentarbereich schreibt jemand unter eine Diskussion: „Mit denen brauchst du gar nicht zu reden. Das sind doch alles NPCs, die immer dieselben Sätze runterbeten.“ Die Angesprochenen sind echte Menschen mit eigenen Gründen für ihre Meinung.","kurz":"Wer Menschen „NPCs“ nennt, stellt sie als Automaten dar, die nur Skripte abspielen. Dann gibt es scheinbar keine eigenen Gründe mehr, die man prüfen müsste. Der Fehler: Statt die Position zu kritisieren, wird dem Gegenüber das Denken abgesprochen.","prueffrage":"Worauf bezieht sich die Aussage: auf das, was die Leute vorbringen, oder auf die Leute selbst?","rueckmeldung":[{"option":0,"text":"Entmenschlichung erleichtert Ausgrenzung tatsächlich, und Tiervergleiche sind eine bekannte Form davon. Hier fällt aber kein Tiervergleich: Die Menschen gelten als seelenlose Skriptabspieler, nicht als instinktgetriebene Kreaturen."},{"option":2,"text":"Gruppenetiketten reduzieren Menschen oft auf Vertreter einer Ideologie. Im Satz wird aber keine Ideologie genannt, und die Leute gelten nicht als Überzeugte, sondern als gar nicht denkend. Genau darin liegt der Unterschied."},{"option":3,"text":"Misstrauen lässt sich leicht mit einer Bedrohung begründen. Der Satz stellt die Menschen aber gerade nicht als handlungsfähig dar, sondern als Leute, „die immer dieselben Sätze runterbeten“. Gefährlichkeit würde ihnen eigenes Handeln zugestehen."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam (2006), Verlagsfassung","oeffentlich":false,"doi":"10.1207/s15327957pspr1003_4"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a3216a16ae3c69d8"}},{"id":"qx-b1-057","clusterId":"B","werkstueckRef":"B.16","stufe":2,"question":"Ein Kommentator behauptet: „Der Völkermord in Ruanda 1994 ist allein den Hetzsendungen eines Radiosenders zuzuschreiben. Ohne dieses Radio wäre nichts passiert.“ Wie beurteilst du diese Behauptung am besten?","options":["Die Behauptung überschätzt das Radio: Hetzsprache kann Hemmungen senken und das Töten erleichtern, aber andere Faktoren wirkten daneben mit.","Die Behauptung verallgemeinert vorschnell: Aus dem Fall eines einzigen Völkermords lässt sich nichts über die Wirkung von Hetzsprache sagen.","Die Behauptung ist ein Zirkelschluss: Sie setzt die Wirkung der Hetzsendungen voraus und nimmt den Völkermord dann als Beleg für diese Wirkung.","Die Behauptung überschätzt die Sprache: Angst vor dem Krieg und die Mobilisierung durch Behörden erklären das Töten, die Hetze war nur Begleitmusik."],"correctIndex":0,"explanation":"Die Behauptung macht aus einem Faktor die einzige Ursache. Wer Nachbarn monatelang als „Ungeziefer“ bezeichnet, löst moralische Hemmungen und macht das Töten sprachlich leichter. Zugleich gab es weitere Treiber: die Angst vor dem Krieg, Hetzblätter und die Mobilisierung durch Behörden und Bürgermeister. Ein Ereignis mit mehreren zusammenwirkenden Ursachen auf eine einzige zu verkürzen, ist ein typischer Denkfehler. Auch das Gegenteil, Sprache habe gar keine Wirkung, wäre falsch, denn Ursachen können sich verstärken. Die anderen Einwände klingen bedenkenswert, passen aber nicht: Die Behauptung gilt einem einzelnen Ereignis und verallgemeinert nicht auf andere Fälle. Sie dreht sich auch nicht im Kreis; ihr Problem ist nicht, dass sie ihre Voraussetzung als Beleg nimmt, sondern dass sie die Wirkung eines Faktors zur einzigen Ursache steigert. Und die Hetze zur bloßen Begleitmusik zu erklären, übergeht, dass monatelange Entmenschlichung Hemmungen senkt.","coreRule":"⚡ Sprache kann Hemmungen lösen, erklärt aber nie allein die Tat.","beleg":"Werkstück B.16 (Die Kakerlaken im Radio); Fn. gl-b-rtlm (Human Rights Watch 1999, „Leave None to Tell the Story“)","status":"entwurf","scenario":"Der Sender sprach über die Tutsi nicht als Nachbarn, sondern über Monate hinweg als „Kakerlaken“ und „Ungeziefer“. Zur gleichen Zeit herrschten Angst vor dem Krieg, es kursierten Hetzblätter, und Behörden und Bürgermeister mobilisierten die Bevölkerung.","quote":"","quoteLabel":"","kurz":"Der Völkermord hatte mehrere zusammenwirkende Ursachen: Monatelange Entmenschlichung senkte Hemmungen, daneben wirkten Kriegsangst, Hetzblätter und die Mobilisierung durch Behörden. Der Fehler liegt darin, einen Faktor zur einzigen Ursache zu machen.","prueffrage":"Welche anderen Umstände gab es zur gleichen Zeit, und was hätten sie allein bewirken können?","rueckmeldung":[{"option":1,"text":"Die Behauptung bezieht sich nur auf Ruanda und verallgemeinert nichts. Auch ein einzelner Fall kann zeigen, dass Hetzsprache wirkt. Ihr Fehler liegt woanders: Sie macht einen Faktor zur einzigen Ursache."},{"option":2,"text":"Ein Zirkelschluss hieße, dass die Behauptung ihre Voraussetzung als Beleg nimmt. Sie schließt aber von der Hetze auf das Töten, ohne sich im Kreis zu drehen. Ihr Fehler ist, einen Faktor zur alleinigen Ursache zu steigern."},{"option":3,"text":"Kriegsangst und die Mobilisierung durch Behörden wirkten tatsächlich mit. Die Hetze zur bloßen Begleitmusik zu erklären, übergeht aber, dass monatelange Entmenschlichung Hemmungen senkt. Das ist dieselbe Verkürzung, nur mit anderem Faktor."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"ba65847a55d3f60e"}},{"id":"qx-b1-058","clusterId":"B","werkstueckRef":"B.16","stufe":3,"question":"Eine Politikerin sagt in einer Talkshow: „Menschen, die ihre Gegner als ‚Ungeziefer‘ bezeichnen, tun das, weil sie sie töten wollen, denn Entmenschlichung ist die Ursache jeder Gewalt.“ Was folgt aus diesen Befunden für ihre Behauptung?","options":["Sie wird bestätigt, denn bei Gewalt aus Nutzen ging Entmenschlichung tatsächlich mit mehr Gewaltbereitschaft einher.","Sie geht zu weit, denn bei Gewalt, die als gerecht empfunden wird, fehlte der Zusammenhang, und das widerlegt „jede Gewalt“.","Sie wird bestätigt, denn auch bei Gewalt, die als gerecht empfunden wird, ging Entmenschlichung mit mehr Bereitschaft einher.","Sie geht zu weit, denn bei Gewalt aus Nutzen fehlte der Zusammenhang mit Entmenschlichung, und das widerlegt „jede Gewalt“."],"correctIndex":1,"explanation":"Die Behauptung verallgemeinert: Aus „Entmenschlichung kommt bei manchen Gewalttaten vor“ wird „sie erklärt jede Gewalt“. Gegen eine solche Allaussage genügt eine Gewaltart ohne den Zusammenhang, und die zeigte sich hier: Bei Gewalt, die als gerecht empfunden wird, ging Entmenschlichung nicht mit mehr Bereitschaft einher, bei Gewalt aus Nutzen dagegen schon. Zwei Grenzen gehören dazu: Gemessen wurden Einstellungen und gedachte Szenarien, keine Taten, und Entmenschlichung nur als abgesprochenes Denken und Fühlen, nicht als Tiervergleich wie „Ungeziefer“. „Jede Gewalt“ ist also zu stark, „keine Gewalt“ wäre es ebenfalls.","coreRule":"⚡ Wer „jede“ oder „immer“ behauptet, braucht nur einen gut belegten Gegenfall zu fürchten: Entmenschlichung erklärt nicht jede Gewalt, denn wer „gerecht“ bestrafen will, braucht einen vollen Menschen als Ziel.","beleg":"Werkstück B.16 (Hinweis zur Beleglage); Fn. gl-b-rai (Rai/Valdesolo/Graham 2017, PNAS 114(32), S. 8511–8516); Fn. gl-b-kteily-folter (Kteily u. a. 2015, JPSP 109(5), S. 901–931)","status":"entwurf","scenario":"In Experimenten und Befragungen mit Online-Teilnehmern (Einstellungsfragen und gedachte Szenarien, keine echten Täter) wurde die Bereitschaft zu zwei Arten von Gewalt erhoben: Gewalt aus Nutzen (etwa einem Fremden für Geld schaden) und Gewalt, die als gerecht empfunden wird (etwa Strafe für ein Fehlverhalten). Entmenschlichung wurde dabei als abgesprochene Fähigkeit zu denken und zu fühlen gemessen. Ergebnis: Wer ein Opfer stärker entmenschlichte, war eher zu Gewalt aus Nutzen bereit. Bei Gewalt, die als gerecht empfunden wird, zeigte sich dieser Zusammenhang nicht; wer sich vorstellte, einen Fremden für sein Fehlverhalten zu bestrafen, hielt ihn sogar für menschlicher.","kurz":"Eine Allaussage wie „jede Gewalt“ scheitert schon an einer Gewaltart ohne den Zusammenhang, und bei als gerecht empfundener Gewalt fehlte er. Der Fehler ist, aus Fällen, in denen etwas vorkommt, auf „immer“ zu schließen.","prueffrage":"Wie wurden Gewaltbereitschaft und Entmenschlichung in den Studien gemessen, und wie nah ist das an dem, wovon die Politikerin spricht?","rueckmeldung":[{"option":0,"text":"Bei Gewalt aus Nutzen stimmt der Zusammenhang, und das ist ein echter Befund. Die Behauptung soll aber für jede Gewalt gelten, und dafür trägt ein Teilbefund nicht, zumal die Studie Einstellungen misst und nichts darüber sagt, ob Menschen jemanden töten wollen."},{"option":2,"text":"Hier ist der Befund ins Gegenteil gedreht. Bei als gerecht empfundener Gewalt zeigte sich gerade kein Zusammenhang, wer bestrafen wollte, hielt den Fremden sogar für menschlicher. Genau das macht die Allaussage angreifbar."},{"option":3,"text":"Der Gedanke, dass eine Ausnahme gegen eine Allaussage genügt, ist richtig, aber die Gewaltarten sind vertauscht. Bei Gewalt aus Nutzen zeigte sich der Zusammenhang, bei als gerecht empfundener Gewalt fehlte er."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Rai, T. S.; Valdesolo, P.; Graham, J. (2017): Dehumanization increases instrumental violence, but not moral violence. PNAS 114(32), 8511–8516 (frei in PMC5559031)","oeffentlich":true,"doi":"10.1073/pnas.1705238114","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"04c2b62d9dca1eea"}},{"id":"qx-b1-059","clusterId":"B","werkstueckRef":"B.16","stufe":4,"question":"Welche Beurteilung wird dieser Sprache am besten gerecht?","scenario":"In einem Forum lest ihr Kommentare, die eine Gruppe von Menschen durchgehend „Ungeziefer“ und „Seuche“ nennen und von der „Säuberung“ der Gesellschaft sprechen. Zu Gewalt wird nirgends ausdrücklich aufgerufen. Eine Mitleserin meint: „Das ist doch nur Wut, das darf man nicht so ernst nehmen.“","options":["Es ist wohl eher Frust, denn solange kein ausdrücklicher Aufruf zu Gewalt fällt, deutet „Ungeziefer“ in einem Forum meist auf Wut hin.","Es ist bereits Gewalt, denn Wörter wie „Seuche“ und „Säuberung“ schaden der Gruppe ebenso wie ein körperlicher Angriff.","Es ist ein Warnsignal, denn die Gleichsetzung einer ganzen Gruppe mit Ungeziefer senkt die Hemmung vor Gewalt, auch ohne offenen Aufruf.","Es verrät, dass die Schreibenden selbst zuschlagen werden, denn wer eine ganze Gruppe „Ungeziefer“ nennt, tut das meist als Vorstufe eigener Taten."],"correctIndex":2,"explanation":"Entscheidend ist, was die Sprache bewirkt, nicht ob sie einen ausdrücklichen Aufruf enthält. Ein einzelner Spruch wie „fauler Hund“ ist nur die mildeste Form der Entmenschlichung. Wird dagegen eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt, als Seuche beschrieben und ihre Beseitigung als „Säuberung“ gerahmt, ist das etwas anderes: Sie wird aus dem Kreis derer herausgenommen, denen man moralische Rücksicht schuldet. Das kann Gewalt erleichtern, weil die Hemmung, Menschen zu schaden, bei „Ungeziefer“ weniger greift; nicht jede Gewalt erklärt sich allerdings so. In Ruanda 1994 gingen Monate der Hetze gegen „Kakerlaken“ dem Völkermord voraus. Die Sprache allein erklärt solche Taten nicht, denn Angst, Krieg und organisierte Mobilisierung kamen hinzu, aber sie lieferte die Wörter, die das Töten leichter machten. Die Einordnung als Warnsignal beurteilt die Sprache, nicht die Person, die sie benutzt. Die anderen Deutungen klingen verständlich, scheitern aber hier: Dass kein ausdrücklicher Aufruf vorliegt, stimmt, hilft aber nicht weiter, denn die Vorbereitung geschieht meist unterhalb des Aufrufs. Wörter können verletzen, doch sie sind keiner Tat gleichzusetzen. Und von der Wortwahl lässt sich nicht sicher auf das künftige Handeln einzelner Schreibender schließen.","coreRule":"⚡ Wird eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt und ihre Beseitigung als „Säuberung“ gerahmt, ist das ein Warnsignal, auch wenn kein offener Gewaltaufruf fällt.","beleg":"Werkstück B.16 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist, was die Sprache bewirkt: Wird eine ganze Gruppe durchgehend als Ungeziefer und Seuche beschrieben, kann das die Hemmung vor Gewalt senken, auch ohne Aufruf. Wut allein erklärt das nicht, denn die Wortwahl rahmt die Gruppe als etwas, das man beseitigen darf.","prueffrage":"Gegen wen richten sich die scharfen Wörter: gegen Meinungen und Handlungen oder gegen Menschen allein wegen ihrer Zugehörigkeit?","rueckmeldung":[{"option":0,"text":"Dass ein ausdrücklicher Aufruf fehlt, stimmt. Das entlastet die Sprache aber nicht, denn Entmenschlichung wirkt meist unterhalb eines Aufrufs und zählt unabhängig davon, ob dahinter Wut oder Kalkül steckt."},{"option":1,"text":"Wörter können durchaus verletzen und einer Gruppe schaden. Sie sind aber keine körperliche Tat. Das Gewicht dieser Sprache liegt darin, dass sie Gewalt erleichtern kann, nicht darin, dass sie schon Gewalt wäre."},{"option":3,"text":"Hetze kann Gewalt vorbereiten, wie Ruanda zeigt. Aus der Wortwahl lässt sich aber nicht sicher ablesen, was einzelne Schreibende tun werden. Beurteilt wird hier die Sprache, nicht die Absicht einzelner Personen."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): Seven Challenges for the Dehumanization Hypothesis. Perspectives on Psychological Science 16(1), 3–13 (frei in PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"48a1a5a1cb03b1c3"}}]`);export{t as n,n as t};